INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44502110768', 'Proto Wafer Caixa Com 12 Unidades - Nutrata', '🍫 Nutrata Proto Wafer – Proteína com Sabor e Crocância! 💪✨ Se você busca praticidade, sabor e alta proteína, o Nutrata Proto Wafer é o snack perfeito para o seu dia! Com uma combinação irresistível de camadas crocantes + recheio cremoso + chocolate delicioso, ele se torna a escolha ideal para quem deseja suplementar proteína sem abrir mão do prazer. 😋 ⭐ Benefícios que vão te conquistar 🍫 Sabor incrível e textura crocante 😍 Baixo açúcar ⚡ Perfeito para pré ou pós-treino 👜 Prático para levar na bolsa, mochila ou trabalho 🔥 Snack saudável para matar a vontade de doce sem culpa 🍪 Experiência irresistível Desfrute de um wafer proteico com aroma marcante e cobertura deliciosa. Ideal para atletas, pessoas em dieta, rotina fitness ou quem quer simplesmente um lanche proteico gostoso e nutritivo.', 94.0, 94.0, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-820li-mlnpooo2fabp3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1346435001%2F44502110768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697809033', 'Mini Abajur Dinosauro Luz Noturna 1W 3000K Bivolt Avant', 'Ilumine a noite com a Luz Noturna Anjo da Avant. Perfeita para proporcionar segurança e conforto aos pequenos, essa luminária garante uma iluminação suave e agradável no quarto, ideal para criar um ambiente aconchegante e relaxante. PROPRIEDADES: Proporciona segurança e auxílio em locais que necessitam de uma pequena fonte de luz. Não emite infravermelho e ultravioleta. Produto não tóxico. Composição livre de mercúrio. Baixo consumo de energia. CARACTERISTICAS DE FUNCIONAMENTO: Tensão de entrada: 100V a 240V. Fator de potência: >0,50. Bivolt Automático (100V-240V) ESPECIFICAÇÕES TÉCNICAS E COMERCIAIS: Potência: 1W Fluxo Luminoso: 80 lm Emissão de Cor: Amarela Temperatura de Cor: 3000K IRC: >70 Uso: Interno Garantia Oficial Avant de 12 meses para defeitos de fabricação. Sobre a Avant: A Avant, marca reconhecida por sua qualidade e inovação, oferece uma ampla variedade de produtos para iluminação, com foco em design, funcionalidade e segurança. Com a missão de iluminar os momentos mais importantes da vida, a Avant se dedica a oferecer soluções inteligentes e eficientes para todos os ambientes.', 43.17, 25.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-m04wkn70js0l6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F21697809033', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
