INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499405523', 'Spot Led Authentic Emb. Redondo 12w 4000k 14cm BF Avant', 'SPOT AUTHENTIC 12W - Iluminação de Destaque com Luz Neutra O SPOT AUTHENTIC 12W é a escolha perfeita para iluminar e destacar objetos e texturas em ambientes internos, sejam eles residenciais ou comerciais. Com design moderno e funcional, ele oferece um sistema direcionável para ajustar o ângulo da luz de acordo com a sua necessidade, proporcionando uma luz neutra que realça a beleza natural dos espaços. PROPRIEDADES: Construção livre de mercúrio. Ajuste manual de direção da luz. Acabamento em policarbonato na cor branca. Baixo consumo de energia. CARACTERÍSTICAS DE FUNCIONAMENTO: Temperatura ambiente: -5°C a 40°C. Tensão de entrada: 100V a 240V. Fator de potência: >0,50. Tipo de Instalação: Embutido. ESPECIFICAÇÕES TÉCNICAS E COMERCIAIS: Código: 281080870 Descrição Comercial: LED-SPOT-AUTHENTIC-EMB-RED-NE4000K-12W-BIVOLT-960 Fluxo Luminoso: 960 lm Candelas: 1910 cd Eficiência de Emissão Luminosa: 80 lm/W Temperatura de Cor: 4000K (Luz Neutra) Dimensões (mm): Ø140 x Ø140 x 35 Nicho de Corte (mm): Ø120mm Peso (g): 162 Garantia: 12 meses (contra defeitos de fabricação) SOBRE A MARCA AVANT A Avant é uma marca reconhecida no mercado de iluminação por oferecer produtos de alta qualidade, design moderno e tecnologia inovadora. Com foco na sustentabilidade, a Avant utiliza materiais ecologicamente corretos e oferece soluções eficientes para o consumo de energia, contribuindo para um futuro mais sustentável.', 61.9, 46.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-m01org9yh0dq93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F18499405523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259668114', 'Mandioca Descascada iFrutus', 'A Mandioca Descascada iFrutus é a escolha perfeita para quem busca praticidade e sabor na cozinha. Já descascada e embalada para preservar sua qualidade e frescor, essa mandioca é ideal para diversas receitas, como cozidos, frituras, purês e sopas. Com textura macia e sabor autêntico, facilita o preparo das suas refeições, economizando tempo sem abrir mão do melhor da culinária brasileira. A mandioca é rica em vitaminas do complexo B e C, sais minerais como cálcio, fósforo, ferro e potássio. Possui poucas proteínas e quase nenhuma gordura, além de ser rica em fibras solúveis. É um alimento versátil, podendo ser usado em diversas receitas como farinha, pão, cuscuz, purê, sopa e muito mais.', 16.49, 16.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mj72lsoo3ll0c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555006%2F58259668114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
