INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22130824929', 'Bíblia Leão Rei dos reis | NAA | Letra Grande | Capa Dura', 'Bíblia Leão Rei dos reis Bíblia Leão Rei dos reiscom uma capa ilustrada e acabamento com capa dura. A Sociedade Bíblica do Brasil apresenta à Igreja brasileira e aos leitores da Bíblia a Nova Almeida Atualizada, resultado de uma profunda revisão da consagrada tradução Almeida Revista e Atualizada. De forma mais específica, o texto desta revisão respeita o princípio tradutório de equivalência formal e se caracteriza por um estilo que corresponde ao português culto escrito hoje no Brasil. Título: Bíblia Sagrada Linguagem: Nova Almeida Atualizada | NAA Tamanho da Letra: Grande Capa: Dura Índice: Não Páginas: 952 Formato: 21 x 14 x 3 cm Peso: 0.650 Kg ISBN: 7898680400646 Editora: O Verso da Vida', 60.31, 60.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-mtuj79vmihov9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22130824929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
