INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203283201', 'Nutrify Vegan Tasty Proteína Vegetal em Pó - 420g', 'A Vegan Tasty Nutrify é uma proteína plant-based desenvolvida para quem busca aumentar a ingestão diária de proteínas de forma prática, saborosa e alinhada a um estilo de vida vegano. Sua fórmula combina proteína isolada de ervilha e proteína concentrada de girassol, oferecendo uma alternativa vegetal versátil para o dia a dia. Além das proteínas vegetais, a Vegan Tasty conta com vitamina B12 na forma ativa (metilcobalamina), nutriente comumente incluído em rotinas veganas. O grande diferencial está no sabor agradável, pensado para evitar gosto residual e tornar o consumo mais prazeroso, inclusive em uso contínuo. Cada porção de 35 g (2 dosadores) é ideal para preparo de shakes, vitaminas ou receitas, integrando facilmente a alimentação diária. Embalagem com 12 porções. Suplemento alimentar. Não substitui uma alimentação equilibrada. Utilize conforme a recomendação do rótulo; em caso de condições específicas, gestação, lactação, uso por menores ou restrições alimentares, busque orientação de um profissional habilitado.', 168.0, 151.2, NULL, 'Health > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261k-mjhaun5v8zd030', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1649409907%2F58203283201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
