INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13098136285', 'Cartão de Árbitro Futsal Penalty', 'Garanta uma partida justa e precisa com o Cartão de Árbitro Penalty Futsal. Em sua embalagem apresenta três cartões de cores distintas para as marcações de penalidades, sendo: amarelo, vermelho e azul confeccionados em laminado de PVC flexível. Dispõe também de lápis para anotações e de uma capa de plástico para manter os cartões guardados e seguros. Reutilize os cartões diversas vezes assim que apagar os registros. Adquira e comprove a qualidade Penalty! Benefícios: Produto leve. Anotações rápidas. Acompanha porta cartão e mini lápis. Alguns diferenciais técnicos: O Cartão de Árbitro da Penalty acompanha 3 cartões, uma case em plástico e um mini lápis.', 59.99, 59.99, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-llpfmox1o7ph6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F13098136285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
