INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793116577', 'Par Pneu Bike Pirelli 700x45 Touring Serve Aro 29 + 2 Camara', 'Par Pneu Bike 700x45 Touring Pirelli Serve Aro 29 + 2 Câmara A Pirelli lança a linha premium de pneus de bicicleta, que foi desenvolvida especialmente para todos os segmentos disponíveis no mercado brasileiro. Os novos produtos contam com a mais avançada tecnologia em termos de compostos e processo produtivo que, alinhada à tradição da marca Pirelli, culmina em um pneu que acompanha o desempenho das bicicletas mais sofisticadas do mercado nacional. Uma excelente escolha para o dia a dia sobre duas rodas na cidade. Seu desenho garante conforto e segurança em toda pedalada, graças a baixa resistência no rolamento. Pneu para bicicletas híbridas ou MTB 29er medida 700x45c (equivale a um 29x1.75) modelo slick Touring da marca Pirelli com arame. Ótimo custo x benefício, este pneu é indicado para o uso em asfalto. Se você possui uma bike 29er e deseja um pneu mais leve e confortável para rodar em ruas e estradas sem gastar muito este produto é uma boa opção, não há necessidade da troca das câmaras pois é possível usar câmaras de até 29x2.10 neste pneu, possui peso aproximado de + / - 820gr, sulcos laterais para uma melhor aderência nas curvas, certificação do Inmetro do Brasil, suporta uma pressão máxima de 45 PSI.', 189.9, 189.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-lzl3jbw849ae52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102597%2F22793116577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48559735931', 'Desinfetante Líquido Lysoform Original 5L', 'O que você precisa saber sobre este produto Volume: 5 L. Unidades por kit: 1. Formato de venda: Unidade. Tipo de embalagem: Galão. DESINFETE A SUA CASA COM EFICIÊNCIA: Lysoform desinfetante é a marca mais recomendada por médicos para desinfetar. PROTEGE TODA A SUA FAMÍLIA: desinfetante casa pode ser usado em ambientes com crianças e animais domésticos. EMBALAGEM ECONÔMICA: a embalagem do desinfetante 5L é ideal para quem usa Lysoform em maior frequência. FRAGRÂNCIA ORIGINAL: para os dias de limpeza pesada ou uma faxina rápida', 94.41, 84.97, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mo5j4h544kck1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F48559735931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
