INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898766452', 'Mandoline Slicer Nicer Fatiador Cortador De Legumes 14 Em 1', 'Economize Tempo e Dinheiro: Com este aparelho de corte você pode economizar 70% do tempo na cozinha e dizer adeus para os olhos lacrimejantes quando cortar cebolas. Ele oferece todas as funcionalidades de vários aparelhos em um. As lâminas podem cortar todos os tipos de legumes, vegetais, queijos e frutas. Tem o seu próprio recipiente para armazenar as lâminas e assim, nunca perdê-las. Tenha todas as lâminas ao seu alcance. Você vai preparar seus alimentos de forma mais prática e rápida!!! Descrição do Produto: = 1 Ralador Fatiador De Legumes Mandoline Slicer = Material: ABS + PP + Aço Inoxidável = Tipo de lâmina: Aço Inoxidável = 6 tipos diferentes de lâminas para ralar e fatiar alimentos = Peso: 0.49 KG = Tamanho: 31 x 12 x 11cm Itens Inclusos: =Conjunto de 6 lâminas (4cm x 9cm cada) -lâmina para ralar tiras finas -lâmina para ralar tiras grossa -lâmina para ralar/triturar -lâmina para fatiar chips ondulada -lâmina para fatiar reto 1,0cm de espessura -lâmina para fatiar reto 1,5cm de espessura =1 Protetor para as mãos =1 Suporte para Fatiar =1 Recipiente transparente com capacidade de 1500ml', 74.99, 74.99, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljno428ybrmr39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329277472%2F21898766452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598558581', 'Fogão de Piso Esmaltec 4 Bocas com Acendimento Manual Branco Ideal Pop', 'Fogão de Piso Esmaltec 4 Bocas com Acendimento Manual Branco Ideal Pop O Fogão Esmaltec Ideal Pop é a escolha perfeita para quem busca praticidade, eficiência e segurança na cozinha. Com 4 queimadores, sendo 3 pequenos e 1 família, ele oferece versatilidade para diferentes tipos de preparo. Seu acendimento manual e mesa de aço inox com espaldar garantem durabilidade e facilidade na limpeza. Para maior estabilidade e segurança durante o uso, o fogão conta com trempes duplas em aço esmaltado, proporcionando firmeza às panelas. O forno limpa fácil, com capacidade de 50 litros, possui porta de vidro total, permitindo melhor visualização dos assados. Além disso, conta com prateleira ajustável e vidro interno removível, tornando a limpeza ainda mais simples. O puxador ergonômico facilita o manuseio, enquanto os pés altos e retos com fácil encaixe garantem mais praticidade na hora da instalação e higienização do ambiente. O Esmaltec Ideal Pop combina funcionalidade e segurança para tornar sua rotina na cozinha muito mais eficiente! Imagens meramente ilustrativas.', 638.0, 638.0, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mqesc2unzdvwed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F22598558581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
