INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212860919', 'Kit 2 Cadeiras Eiffel Eames Preta Pés De Madeira Sala Quarto Escritório Moderna Wood Design Premium', 'CADEIRA EIFFEL EAMES PÉS DE MADEIRA Transforme seu ambiente com a Cadeira Eiffel Eames, uma peça moderna, elegante e versátil para compor salas de jantar, cozinhas, escritórios, quartos, áreas gourmet, bares e restaurantes. Com design atemporal inspirado no estilo Charles Eames, ela combina beleza, conforto e praticidade em um único produto. Seu assento anatômico em polipropileno possui formato curvo que se adapta melhor ao corpo, oferecendo mais conforto no uso diário. A base com pés de madeira e estrutura metálica estilo Eiffel garante firmeza, estabilidade e resistência, além de valorizar a decoração com um visual leve, moderno e sofisticado. Ideal para quem busca uma cadeira bonita, resistente e fácil de combinar, a Cadeira Eiffel é perfeita para mesa de jantar, escrivaninha, penteadeira, recepção, home office, cafés, restaurantes e diversos ambientes residenciais ou comerciais. DESTAQUES DO PRODUTO • Design moderno, elegante e atemporal • Modelo Eiffel / Eames com pés de madeira • Assento anatômico em polipropileno • Base em madeira com estrutura metálica • Produto leve, resistente e versátil • Fácil de limpar no dia a dia • Ideal para sala de jantar, cozinha, escritório e área gourmet • Combina com ambientes residenciais e comerciais • Disponível na cor Preto. • Suporta até 120 kg ESPECIFICAÇÕES TÉCNICAS - Produto: Cadeira Eiffel Eames - Modelo: Charles Eames Eiffel / DSW - Material do assento: Polipropileno - Material da estrutura: Madeira e metal - Material dos pés: Madeira - Cores disponíveis: Branco - Altura total: 82 cm - Altura do assento: 45 cm - Largura: 45 cm - Profundidade: 43 cm - Peso aproximado: 5 kg - Peso suportado: até 120 kg - Ambientes indicados: sala de jantar, cozinha, escritório, quarto, área gourmet, bares, cafés, restaurantes e recepções - Montagem: produto enviado desmontado BENEFÍCIOS PARA O SEU AMBIENTE A Cadeira Eiffel é uma excelente escolha para quem deseja renovar a decoração com um móvel bonito, funcional e de fácil harmonização. Seu visual minimalista combina com estilos modernos, escandinavos, industriais, clean e contemporâneos. Além disso, o assento em polipropileno facilita a limpeza e manutenção, enquanto a base com pés de madeira traz um toque acolhedor e sofisticado para o ambiente. Por ser uma cadeira versátil, pode ser usada tanto em mesas de jantar quanto em escritórios, quartos, penteadeiras, salas de espera, recepções e espaços comerciais. É uma peça que une conforto, praticidade e design em uma só solução. Importante: o produto é enviado desmontado e acondicionado em embalagem reforçada para maior segurança no transporte. As cores podem apresentar pequenas variações de tonalidade de acordo com a iluminação, lote do produto ou configuração da tela do dispositivo.', 258.0, 191.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-820lh-mpo1tdeo426bc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1767767311%2F58212860919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194451701', 'Lança-água Animal - Dragverd', 'O Lança-água Animal, além dos rostos ferozes, traz também a cauda do Tubarão, Jacaré, Dragão e Baleia. Nas cores azul, laranja, verde e roxo, é um brinquedo super divertido e prático, que vai render muitas risadas durante os banhos de piscina da garotada.Produzido em polietileno expandido e polipropileno mede 33cm de comprimento quando fechado e seu jato alcança aproximadamente 8 metros de distância. Recomendado para crianças acima de 3 anos, é garantia de muita folia na água!', 21.0, 21.0, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gt-mfbbesnd16hab6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23194451701', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099154292', 'Tábua de Vidro para Corte Retangular 30cm x 40cm - estamp-2', 'Os amantes de comida vão adorar a Tábua de Vidro Retangular 30cm x 40cm Modern da Mor. Com exclusivas estampas xadrez, esse utensílio vai tornar sua cozinha um ambiente ainda mais atraente. Além do uso convencional de picar e fatiar alimentos, esta tábua ainda pode ser utilizada como uma bonita bandeja, servindo de apoio para oferecer aos seus convidados deliciosos doces preparados com todo capricho! Produzidas em vidro temperado com pés em silicone, têm grande resistência ao calor, até 120°C, e ao frio, -10°C. Para facilitar, podem ser levadas à lava louças. Basta escolher suas estampas preferidas entre as cores verde, rosa, amarelo e laranja e pedir agora mesmo a sua!', 32.0, 32.0, NULL, 'Home & Living > Kitchenware > Chopping Boards', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mgb7fd6hmc5k4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F22099154292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
