INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594030894', 'Capacete Aberto Liberty 3 New Presonalizado Meia Lua Blade Viseira Fumê', 'Capacete Adesivado Modelo: New Tree Marca: Protork Personalização: Blade Meia Lua AGV Viseira: Fumê Este capacete aberto oferece conforto e sensação de liberdade a cada quilômetro percorrido. Graças ao seu desenho, você terá um amplo campo de visão e audição, o que lhe permitirá manter-se atento a fatores externos. Rigidez e durabilidade É fabricado com materiais de alta qualidade que absorvem energia e proporcionam grande dureza. Em caso de impacto o golpe se concentrará num só ponto, para amortecer o movimento e evitar contusões. Suavidade em sua caminhada Seu material interno de Nylon é acolchoado e elástico, permitindo maior absorção de impacto quando o capacete para. Sinta conforto e segurança ao longo do seu percorrido!', 179.9, 161.91, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-820mb-mqrxe5nwej2a8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F652972169%2F23594030894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594405407', 'Kit 5 Produtos Skincare Kokeshi Limpeza e Hidratação', 'KIT 5 PRODUTOS SKINCARE KOKESHI LIMPEZA E HIDRATAÇÃO Linha completa de cuidados com a pele, produtos inspirados em tradições asiáticas, que se beneficiavam do uso do arroz para manter a pele com aparência de porcelana. O Kit Skincare Kokeshi é um kit completo, que vai te auxiliar nos cuidados diários com a pele, desde a higiene até a hidratação. Indicado para todos os tipos de pele, a skincare da Kokeshi é uma rotina de cuidados prática e descomplicada para o dia-a-dia, e que vão te proporcionar uma pele hidratada, com viço e imperfeições atenuadas. O Kit vai te proporcionar uma experiência completa com os produtos da Kokeshi, e uma pele revitalizada. O Kit Skincare Kokeshi contém: 1 unidade do creme facial Pele de Porcelana 30g 1 unidade do creme para os olhos Olhos de Gueixa 15g 1 unidade da espuma de limpeza Espuma de Chamego 150ml 1 unidade do Sérum Booster Kokeshi 30ml 1 unidade da Água Micelar Rice 215ml', 199.9, 139.93, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-820m6-mq7p9d2muo740e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395166866%2F22594405407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598942193', 'Kit 10 Panos Microfibra Multiuso Limpeza Secagem Cozinha', 'Apresentamos o revolucionário Pano de Microfibra Multiuso, confeccionado com tecido de primeira qualidade, composto inteiramente por 100% de microfibra. Este incrível pano é a solução definitiva para suas tarefas de limpeza. Sua composição de microfibra garante a máxima absorção, enquanto sua incrível tecnologia de fabricação impede que solte fiapos ou pelinhos, proporcionando uma limpeza impecável. Sua facilidade de torção e manuseio torna a limpeza uma tarefa simples e eficiente. Este pano versátil é a escolha ideal para qualquer tipo de limpeza, desde a sua casa até a manutenção de seu veículo. Deixe o Pano de Microfibra Multiuso elevar o padrão da sua limpeza, proporcionando resultados excepcionais a cada uso. Contém: 10 unidades Cor: Colorido Cores Sortidas Medidas: 30 largura x 30 altura cm Composição: 88% poliéster e 12% poliamida LAVAGEM: Nossos panos de microfibra são de excelente qualidade, excelente textura e muito funcional', 59.99, 25.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/br-11134207-7r98r-llaox1xq1oi37a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F20598942193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
