INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256597317', 'Sapatilha Ciclismo MTB Speed JET Adventure Pro Bike Tipo Shimano', 'Com mais de 20 anos de mercado, a paixão pelo o mundo das 2 rodas, fez Surgir a Jet Adventure. Vendo a necessidade do mercado por produtos com qualidade e preço acessível, o espírito aventureiro da marca vem se destacando no mercado nacional com produtos para o segmento de bike e moto. Buscamos aliar os melhores conceitos de produção e matéria-prima para você que possui o “Espírito de Aventura” ou é um profissional do esporte. Não Procure mais vá de JET ADVENTURE uma marca que preza pela qualidade e conforto dos seus produtos! A TMX Duas Rodas é Revendedora autorizada JET ADVENTURE® * Especificações Técnicas: - Solado rígido, para não dissipar a energia da pedalada (perder força); - Placa interna do taco com reforço, gerando mais durabilidade; - Costura dupla nos pontos principais; - Bico remodelado e vulcanizado, conferindo maior resistência; - Tecido respirável aumentando a ventilação; - Palmilha com tecnologia "Memory" que se modela ao pé do piloto gerando mais conforto; - Visual Clean; - Sistema de fechamento "Rollking" com ve lcro adicional, garantindo maior firmeza e praticidade ao calçar e descalçar; - Cabos de aço revestidos de nylon; - Língua com cortes anatômicos para maior conforto; - Peso: 0,650 kg.', 482.9, 329.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8262g-mlmflv83jfgj03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F58256597317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
