INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997305208', 'Barbeador De Pêlos Do Corpo Feminino Kemei Elétrico Sem Dor Para Pernas Rosto E Axilas Aparador De Biquíni Portátil À Prova D''água', 'Remoção de cabelo elétrico indolor e hipoalergênico - Aparador de biquíni elétrico para mulheres adota lâminas de aço inoxidável hipoalergênico cabeça, ajudando a obter um barbear próximo e seguro sem dor ou irritação, mesmo para peles sensíveis. Barbear cabelos indolores. Navalha elétrica à prova d''água, segurança seca e molhada - Barbeador elétrico à prova d''água seguro de usar, mesmo no banho ou no chuveiro. O design da cabeça da navalha destacável e a escova de limpeza longa tornam este aparador de cabelo fácil de limpar. Cabelos indesejados Não há mais nicks, cortes e irritações, remove de perto os cabelos indesejados suavemente. Navalha elétrica segura e suave para mulheres: Experimente fácil, curva abraçada, barbear suave em um design reutilizável e recarregável que minimiza a irritação da pele e reduz resíduos de barbear descartáveis A Fast, Close Shave: Barbear de forma rápida e suave com 3 lâminas flutuantes ultra-afiadas e folhas externas ultrafinas duplas; use um movimento fácil de costas e volta para cobrir rapidamente áreas maiores do seu corpo Detalhado, barbear suave e aparar também: as lâminas de aço inoxidável hipoalergênicas ajudam a prevenir irritações e colisões na barbear na pele sensível; o aparador pop-up garante uma preparação próxima e segura de áreas sensíveis À prova d''água para uso molhado ou seco: Barbear dentro ou fora do chuveiro com um design confortável e barbeador que manuseia com facilidade, mesmo com as mãos molhadas Nome da marca kemei Tipo de alimentação: Recarregável Uso do braço: Rosto, Cabelo, barba, cabelos de perna, cabelos de braço, cabelos de biquíni, uso: Rosto, cabelo, barba, barba, cabelo de corpo, cabelos de perna, cabelos de braço, cabelos de biquíni, cabelos nas axilas Tensão: 100-240V Tempo de carregamento: 1 horas Tempo de trabalho: 30 minutos Potência: 3W Número do modelo KM-3213 Motor: muito poderoso Cor da imagem no show da página do produto: como a imagem na página do produto Conteúdo da Embalagem 1 x máquina Pincel 1 x Cabo de Carga', 150.0, 71.0, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/cn-11134207-7r98o-lkw7ghm3jm3x8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450997010%2F20997305208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
