INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44559037252', 'Boneco Articulado Montável Blokees DaaLaMode Hatsune Miku Official Outfit Colecionável Model Kit', 'BLOKEES DAALAMODE SERIES - HATSUNE MIKU OFFICIAL OUTFIT | MODEL KIT DETALHES - Produto Oficialmente Licenciado - Corpo Totalmente Articulado - Configuração Completa - Design Bem Equilibrado - Montagem Sem Ferramentas Dê vida a Hatsune Miku com o Blokees DaaLaMode Series - Hatsune Miku Official Outfit. Este brinquedo de personagem oficialmente licenciado apresenta 77 peças, um corpo totalmente articulado, acessórios detalhados e um design bem equilibrado. Com montagem fácil e placas faciais intercambiáveis, ele captura as expressões dinâmicas e o estilo icônico de Miku. Perfeito para fãs e colecionadores, este brinquedo de personagem oferece um design impecável e opções versáteis de exibição. Entre no Universo Radiante de Miku hoje! CONTEÚDO DA EMBALAGEM - Hatsune Miku Official Outfit Character Toy x 1 - Conjunto Completo de Acessórios x 1 - Suporte de Exibição x 1 - Manual de Instruções x 1 ESPECIFICAÇÕES - Tipo: Brinquedos de personagens para montar - Série: Blokees DaaLaMode Series - Modelo: Hatsune Miku Official Outfit - Idade recomendada: 14 anos ou mais - Material: Plástico PVC e ABS ecologicamente correto e tecido Distribuído por Polibrinq As imagens são meramente ilustrativas. As cores, dimensões e detalhes do produto podem variar, devendo prevalecer a descrição e as especificações técnicas disponibilizadas ao consumidor.', 480.98, 399.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-81zwj-mn5u2pq84lxfc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537682554%2F44559037252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598794874', 'Copo Treinamento com Válvula Redutora Rosa (240ml) – TurmaTube', 'O Copo Treinamento com Válvula Redutora Rosa (240ml) – TurmaTube é ideal para os primeiros passos do bebê na transição da mamadeira para o copo. Seu bocal rígido e anatômico ajuda a introduzir líquidos como água, sucos ou leite com facilidade, promovendo mais autonomia no dia a dia. A válvula redutora de pingos evita vazamentos e sujeiras, enquanto a composição livre de BPA e a válvula em PVC atóxico garantem mais segurança durante o uso. Perfeito para acompanhar o bebê na fase da dentição com conforto e durabilidade. ✨ Detalhes do Produto: 🍼 Copo Treinamento com Válvula Redutora Rosa (240ml) – Ideal para a fase de transição da mamadeira. 🛡️ Material seguro – Livre de BPA e com válvula em PVC atóxico. 📏 Capacidade – 240ml. 💧 Válvula redutora de pingos – Evita vazamentos e mantém o uso prático e limpo. 🎨 Estampa exclusiva TurmaTube – Com o personagem da turminha! Feito para ajudar seu bebê a conquistar mais autonomia com conforto e segurança. ⚠️ Recomendações Importantes: Higienize todos os componentes com produtos neutros após cada uso. Substitua o produto ao sinal de desgaste. 💜 TurmaTube - Fazemos parte da sua rede de apoio, cuidando de você e do seu bebê em cada etapa da jornada materna. Por razões de saúde e segurança pública, não realizamos trocas deste produto de uso pessoal, conforme arts. 6º, I, e 8º do Código de Defesa do Consumidor.', 29.99, 23.99, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md62jgb3633m3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1245828786%2F22598794874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
