INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21329166342', 'Sutiã Top Moldado Dilady Sem Aro Sem Bojo Laterais Largas Alta Sustentação Feminino', 'Sutiã Top Sustentação Moldurado Ultra Dilady Modelo: 0318122 O Sutiã Top Sustentação Moldurado Ultra Dilady foi desenvolvido especialmente para proporcionar conforto, segurança e alta sustentação, sem abrir mão da leveza e da liberdade de movimentos. Sua modelagem estilo top oferece excelente ajuste ao corpo, sendo ideal para mulheres que buscam uma peça confortável para o uso diário, principalmente para quem possui seios mais volumosos e precisa de maior estabilidade ao longo do dia. O modelo não possui aro nem bojo, proporcionando uma sensação de conforto sem apertos ou incômodos, enquanto a estrutura moldurada auxilia na sustentação natural do busto. As laterais largas oferecem maior firmeza e ajudam a distribuir melhor a sustentação, enquanto as alças reguláveis permitem um ajuste personalizado, acompanhando diferentes biotipos com conforto e segurança. Seu design moderno e discreto torna a peça perfeita para compor a rotina diária, unindo praticidade, elegância e excelente vestibilidade. Diferenciais do produto: - Modelagem estilo top moldurado; - Sem aro e sem bojo; - Alta sustentação para maior conforto; - Ideal para seios volumosos; - Laterais largas que proporcionam mais firmeza; - Alças reguláveis para ajuste personalizado; - Excelente adaptação ao corpo; - Tecido macio, elástico e confortável; - Design moderno e discreto; - Ideal para o uso diário. Composição: Tecido principal: 75% Poliamida e 25% Elastano. Detalhes: 77% Poliamida, 13% Elastano e 10% Poliéster. O Sutiã Top Sustentação Moldurado Ultra Dilady está disponível na Usee Brasil!', 149.99, 89.99, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/br-11134207-820mc-mpxmvwrd3wg13e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F21329166342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
