INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27164128627', 'COLORGRAM NUDE BLUR TINT (22 colors)', 'TINTO DE BLOCO COLORGRAM NUDE (8 cores) Edição Crayon Shin-chan. Blurs Fine Lines & Imperfeições: Alcançar um decote impecável com o efeito soft-blur do Colorgram Nude Blur Tint. A tonalidade labial leve preenche linhas finas e suaviza imperfeições para um acabamento fosco perfeito. Fórmula fosca sem peso: Experimente a textura ultrafina e em pó que se encaixa perfeitamente em seus lábios sem se sentir pesado. Receba um acabamento fosco que fica vibrante o dia todo sem a sensação seca e de bolo. Longa duração e não pegajosa: aproveite o desgaste diário sem se preocupar em borrar ou a viscosidade. O Colorgram Nude Blur Tint oferece uma sensação confortável e não oleosa com corte colorido Colorgram Nude oferece uma sensação confortável e não oleosa com pagamento de cores estendidas. Perfeito para Cada Ocasião: Esta tonalidade labial versátil funciona perfeitamente para looks casuais e eventos glam. Os tons naturais e nus complementam todos os tons de pele e proporcionam uma aparência mais completa e volumosa. Fácil Aplicação e Hidratação fáceis: Basta deslizar o tom em seus lábios para um efeito desfoque instantâneo. Sua fórmula hidratante garante que os lábios fiquem macios e flexíveis, tornando-os perfeitos para o uso diário.', 57.73, 57.73, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134207-7rdvk-m1f085yl3st3d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F27164128627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
