INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259699282', 'Linguiça Toscana Sadia', 'A Linguiça Toscana Sadia é feita com carne suína selecionada e temperos equilibrados, garantindo um sabor irresistível e uma textura macia em cada mordida. Prepare seu produto na panela, airfryer, forno ou churrasqueira. Para sua segurança, siga as instruções abaixo: * Mantenha o produto cru separado dos outros alimentos. * Lave com água e sabão as superfícies de trabalho, incluindo as tábuas de corte, utensílios e mãos depois de manusear o produto cru. * Consuma somente após cozido, frito ou assado completamente.', 28.49, 28.49, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zue-miyqbuhybdoi34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F58259699282', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
