INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099271146', 'Quem disse, Berenice? Máscara De Cílios Big Bang Sem Limites 10g', 'A Máscara de Cílios Big Bang Sem Limites é uma máscara para cílios preta que, além de alongar, também fortalece os cílios. Com ativos naturais, o resultado do uso é o crescimento dos fios em 8%, em 45 dias de uso contínuo*, Além de: 700% volume, 300% definição, 200% alongamento e 100% mais curvatura;Fórmula super preta de longa duração;Descarrega quantidade ideal de produto;Não borra ou forma grumos;Secagem rápida;Dermatologicamente e ofalmologicamente testada. É para você arrasar no olhar, sem limites! *Crescimento dos fios já existentes. Nenhum produto do Boticário é testado em animais, ou seja, este item possui selo Cruelty Free. Produto Vegano. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 79.9, 79.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-822y0-mi4tyt7dz5l09e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671118112%2F22099271146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203299051', 'Quem Disse, Berenice? Cremoso Batom Rosa 260 3,8g', 'O Batom Rosa 260 Cremoso Quem Disse, Berenice? é Ideal para quem busca um look vibrante e sofisticado. Sua fórmula com textura cremosa e ultra pigmentação garante cor intensa e uniforme, sem ressecar. A embalagem no formato batom bala é super prática e fácil de aplicar. Experimente a praticidade e o conforto de um batom cremoso que não resseca! O resultado? Lábios hidratados, livres daquela sensação pegajosa, deixando você pronta para arrasar. Nenhum produto Quem Disse, Berenice? é Testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 29.9, 23.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mjhgp7vpc9hj56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671118112%2F58203299051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
