INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253174139', 'Roda Liga Traseira Fan 160 Titan 160 2025 Lançamento Preto', 'RODA TRASEIRA MOdelo titan 2025 LIGA DE LEVE PE GALINHA Smart Fox DA LOJA MEGA MOTOS COMPATÍVEL COM MOTOS COM FREIO A DISCO MODELOS: TITAN 160 2025 Se você não quer PERDER TEMPO lavando ARO, dando POLIMENTO COM BOMBRIL e depois ver sua roda toda ENFERRUJADA, então já PASSOU da HORA de colocar um RODÃO na sua MÁQUINA. E pode ter CERTEZA, você ACERTOU EM CHEIO na ESCOLHA! Pois as RODA DE LIGA LEVE Smart fox DA LOJA MEGA MOTOS são as MELHORES VENDIDAS no BRASIL! - ORIGINAIS DE FÁBRICA - ALUMINIO DE ALTÍSSIMA RESISTÊNCIA (para não amassar em qualquer buraco) - COM RETENTOR E ESPAÇADOR (VELOCIDADE, SEGURANÇA E MAIOR DURABILIDADE) ***** FIQUE ATENTO ANTES DE COMPRAR RODAS COMUNS, POIS ELAS NÃO VEM COM rolamentos e espaçadores da e retentor roda ******** Sendo que, com as RODAS DE LIGA LEVE DA LOJA MEGA MOTOS você apenas instala no pneu e pode rodar a vontade, elas vão COMPLETAS e na hora da LIMPEZA é SUPER FÁCIL e muito MAIS RÁPIDO! Além disso, você pode usar COM ou SEM CÂMERA de AR e você ainda GANHA DE BRINDE OS BICOS. Sua MOTO EQUIPADA, MAIS BONITA e como as MELHORES RODAS DO BRASIL! FICHA TÉCNICA: MARCA: Smart Fox COR: PRETO ITENS INCLUSOS: 1 - RODA TRASEIRA MODELO 160 2025 TITAN E FAN E START 150/160 2025 1- BICO SEM CAMARA', 507.0, 507.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjfkhocet6gy65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337270308%2F58253174139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
