INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398220431', 'Livro Os mistérios de Baskerville Série Os mistérios de Baskerville Hall Vol. 1 Hall Ali Standish Intrínseca', 'Antes do lendário Sherlock Holmes, existiu um menino chamado Arthur... Nesta aventura inspirada na obra e na infância de Arthur Conan Doyle, um jovem detetive entra em uma escola para prodígios repleta de mistérios onde tudo pode acontecer O jovem Arthur Conan Doyle sempre foi brilhante, capaz de decifrar os enigmas mais complicados. Quando é convidado para estudar em Baskerville Hall, uma escola para crianças excepcionais, ele acredita ser sua chance de ajudar a família e provar seu valor. Na instituição, Arthur logo faz novos amigos: Irene Eagle, uma garota corajosa e determinada, e Jimmie Moriarty, um aluno genial que promete ser um desafio à altura das habilidades dedutivas de Arthur. Juntos, eles vão descobrir que a nova escola tem suas peculiaridades, como criaturas extraordinárias e explosões que ninguém consegue explicar, mas também inimigos que podem surgir de onde menos se espera. Para a surpresa do trio, eles são chamados para participar de uma poderosa sociedade secreta, o Trevo, com uma condição: solucionar três testes nada simples. No entanto, conforme os dias passam em Baskerville Hall, Arthur se depara com um mistério ainda mais intrigante — e muito mais perigoso. E cabe ao jovem Conan Doyle resolvê-lo…', 69.9, 69.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6edr6mgniw7c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F22398220431', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
