INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898643043', 'Perfurador de Solo a Gasolina 52cc 2,5HP Brocas 80x10cm + 80x20cm Carbon Fak', 'PERFURADOR DE SOLO GASOLINA 52CC 2,5HP FAK520PS CARBON FAK O aliado ideal para quem trabalha no campo! Com motor potente de 52 cilindradas e 2,5HP, o Perfurador de Solo CARBON FAK520PS é a ferramenta perfeita para agilizar tarefas na propriedade rural. Projetado para atender às exigências do agronegócio, este equipamento oferece alta eficiência na perfuração de diversos tipos de solo, sendo ideal para plantio de mudas, cercamento de áreas, reflorestamento, instalação de mourões e demais atividades agrícolas. CARACTERÍSTICAS DO PRODUTO - Estrutura e brocas de alta resistência; - Fácil manutenção e manuseio; - Produto leve e compacto; - Proporciona perfurações na vertical / horizontal; - Maior autonomia FICHA TÉCNICA Código Carbon: X607169 Motor: gasolina 2 Tempos Óleo 2T: 25:1 ---- 25 Litros de gasolina: 1 Litro de óleo 2T; Potência: 2,50 HP (1,85kw) - 52cc; Rotação: Máxima 11.000 RPM - Na Lenta 3.000 RPM; Arranque: Manual com mola retrátil; Autonomia: Aproximadamente 1 hora; Tanque: 1000 ml; Redução: Taxa de Redução 29:1 Engrenagens: Em Aço Temperado; ITENS INCLUSOS Motor Perfurador de Solo a Gasolina 52cc Broca 80x10cm Broca 80x20cm Kit de Ferramentas Misturador de Combustível Manual de Instruções *Garantia de 6 meses (3 meses de fábrica + 3 meses de loja)* **Assistência técnica e peças de reposição diretamente com a CARBON FAK, em todo território nacional', 995.99, 773.6, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb44hcccoznz25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389803646%2F23898643043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
