INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47356893264', 'Super Mario 2026 - It’s-a me, Mario! - Contém 10 Envelopes (50 Figurinhas) - Novo - Editora Panini', 'Super Mario 2026 - Contém 10 Envelopes (50 Figurinhas) Este Kit contém:10 envelopes - cada envelope contém 5 figurinhas.Os envelopes são lacrados e as figurinhas são aleatórias e sortidasA coleção Oficial SUPER MARIO 2026: It''s-a me, Mario! chegou para levar os fãs a uma jornada inesquecível pelos jogos Super Marios Wonder, Luigis Mansion 2, Princess Peach Show Time e Super Mario Party Jamboree. A coleção completa contém 224 cromos colecionáveis, incluindo 64 especiais com efeito metalizado e 16 cromos que brilham no escuro! Nostalgia, diversão e o melhor do universo dos encanadores mais famosos do mundo dos games numa coleção imperdível para todo colecionador. Segmentos: Colecionáveis, Colecionáveis - Entretenimento Marcas: Panini Editora: Panini Idioma: Português Condição: Novo/Lacrado', 47.0, 47.0, NULL, 'Hobbies & Collections > Collectible Items > Idol Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-82621-mli76wvy60w4b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F47356893264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42479748546', 'Mangá - Shaman King BIG Vol. 15 - por Hiroyuki Takei - Editora JBC ISBN 9788545716570', 'Shaman King BIG Vol. 15 O Shaman Fight está chegando ao fim! Hao e Yoh agora se encaram como iguais, dentro e fora do campo de batalha!À medida que o Shaman Fight entra em sua fase decisiva, Yoh e seus aliados enfrentam batalhas cada vez mais intensas, em que força e convicções são levadas ao limite. Com os cinco Guerreiros Elementais já escolhidos, o equilíbrio de poder muda drasticamente. Diante de inimigos implacáveis, alianças são testadas e sacrifícios se tornam inevitáveis, enquanto a presença de Hao se impõe sobre Yoh, menos como um inimigo e mais como um xamã impossível de ser evitado, para o bem ou para o mal. Além disso, os humanos descobrem a localização da fase final do Shaman Fight, e Hao pede ajuda a Yoh para confrontá-los! Qual será a escolha de Yoh e sua turma? Autor(es): Hiroyuki Takei ISBN: 9788545716570, 978-85-457-1657-0 Check-List: Junho/2026 Editora: JBC Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 05/06/2026 Idioma: Português Condição: Novo/Lacrado', 112.9, 112.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-81zvf-mmmbmm7mksn541', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F42479748546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
