INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799555547', 'Moedor Maquina Manual De Moer Carne Moída N° 12 com Manivela', 'O Moedor de Carne Nagano pode ser utilizado para serviços pesados, com grande capacidade. Corpo em liga de alumínio de alta qualidade. Aparência suave, com estruturas conjuntas fáceis para operação e limpeza. Geralmente é utilizado para moer carne ou vegetais. Com ele você irá conseguir preparar hambúrguer, almôndegas, carne moída e outras diversas receitas de forma artesanal. Material: Alumínio', 100.8, 100.8, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7repl-m1wst6q4pl8p3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F18799555547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794466681', 'Sofá Heitor Luxo 3 Lugares 2,00m Pé Metal 2 Lugares Madeira Maciça Castellar Móbile', 'SOFÁ HEITOR O sofá Heitor é um modelo imponente e contemporâneo, perfeito para quem busca design e conforto. Sua estrutura robusta em madeira maciça e pés metálicos discretos se unem à elegância do estofamento. Ideal para elevar a decoração do seu ambiente, ele une funcionalidade e arte! Altura: 90cm Profundidade: 90cm Comprimento: 200cm Especificações técnicas: Almofadas decorativas inclusas. Encosto com almofadas soltas de fibra 100% siliconada. Assento com espuma D28 e manta acrílica. Estrutura em madeira reflorestada. CUIDADOS: Use um pano levemente umedecido, seguido de pano seco. Evite exposição ao sol e chuva, e não utilize produtos químicos.', 3343.9, 3343.9, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mffuv10hkdtzea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F309237167%2F22794466681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48860819393', 'Conjunto Feminino Infantil Pequena Sonhadora', 'Descrição: Conjunto Feminino Infantil Pequena Sonhadora Conjunto em moletom quentinho e confortável. Casaco turquesa com estampa frontal e calça na cor azul marinho com detalhe lateral, cintura elástica e punhos em ribana. Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Inverno - Gênero: Feminino - Tecido Peça: Moletom - Composição: 50% Algodão e 50% Poliéster - Faixa Etária: 1 à 12 anos - Garantia: 1 Mês - Idade recomendada: 1 - 12 anos - Tipo de Roupa: Conjunto - Tabela de Medidas: Tabela de Medidas Casaco: Tamanho | Busto | Comprimento 2 | 32CM | 38CM 3 | 34CM | 40CM 4 | 35CM | 42CM 6 | 36CM | 44CM 8 | 38CM | 46CM 10 | 40CM | 48CM 12 | 42CM | 51CM Tabela de Medidas Calça: Tamanho | Cintura | Comprimento 2 | 20CM | 49CM 3 | 21CM | 54CM 4 | 23CM | 66CM 6 | 24CM | 71CM 8 | 25CM | 74CM 10 | 26CM | 82CM 12 | 27CM | 91CM', 69.9, 50.33, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-822ws-mofh12p0q6mk0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F48860819393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
