INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199447148', 'Nissin Galinha Caipira Miojo', 'Nissin Lámen Galinha Caipira é o sabor preferido e o queridinho dos consumidores, aquele que não pode faltar em casa. Refeição prática pronta em apenas 3 minutos e com 11 variações de sabores. Modo de Preparo: Micro-ondas: Coloque 450ml de água e o macarrão em um recipiente próprio para micro-ondas. Leve ao forno micro-ondas em potência alta por 5 min, interrompendo na metade do tempo para mexer. Retire do micro-ondas, misture o tempero e sirva em seguida. Fogão: Ferva 450 ml de água. Junte o macarrão e cozinhe por 3 minutos. Retire do fogo e misture o tempero.', 3.49, 3.49, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Noodles', 'https://cf.shopee.com.br/file/sg-11134201-82598-mqnelllo9ogd48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555006%2F23199447148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698057392', 'Farol Milha Tiggo 2010 2011 2012 2013 Lente Lisa Vidro Com Suporte', 'Farol de Milha Auxiliar Caoa Chery Tiggo 2010 2011 2012 2013 Com Suporte Características: Produto novo de ótima qualidade; Feito sob medida, encaixe perfeito; Não acompanha lâmpadas e soquetes. Especificações técnicas: Acompanha suporte; Encaixe de lâmpada: H8; Cor da carcaça: cromada; Regulagem de foco manual; Lente lisa em vidro resistente; Suporta lâmpadas até 55 watts. Compatível com os modelos: Chery Tiggo 2010 a 2013 Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 122.22, 110.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rfg9-m36q1668yfh3e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F22698057392', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
