INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6175562512', 'Euro Le Parfum 100ml Paris Elysees', 'Euro é uma fragrância masculina fougére, ideal para homens de espírito conquistador. Essa fragrância traduz a força e a virilidade dos homens. É um perfume que homenageia a moeda europeia, que recebe o mesmo nome. O perfume masculino Euro é composto pelas notas de coentro, bergamota e artemísia. O perfume tem o cravo das notas florais e jasmim, o que torna o perfume sensual, e o musgo de carvalho que deixa o perfume com aroma amadeirado confortável. Família Olfativa: Fougére. Notas de Topo: Notas de Coentro, Bergamota e Artemísia. Notas de Coração: Cravo das Notas Florais e Jasmim. Notas de Fundo: Musgo de Carvalho. Ocasião sugerida: Pode ser utilizado em ocasiões diurnas ou noturnas, se adaptando perfeitamente as suas necessidades.', 70.0, 42.89, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lt5ehck8tqxg8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F6175562512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
