INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198838575', 'Body Splash Fresh Pear Bloom Feminino 200ml Desodorante Colônia Refrescante', 'BODY SPLASH FRESH PEAR BLOOM FEMININO 200ML DESODORANTE COLÔNIA REFRESCANTE O Body Splash Fresh Pear é uma celebração da leveza e do frescor. Sua fragrância frutada com toque floral proporciona uma sensação imediata de conforto e bem-estar a cada borrifada. Perfeito para o dia a dia, especialmente em climas quentes, deixa a pele suavemente perfumada com um rastro delicado, moderno e refrescante. Sua fórmula leve foi desenvolvida para garantir uma fixação suave, sem pesar ou ressecar a pele, mantendo a sensação de frescor ao longo do dia. DESTAQUE DO PRODUTO • Fragrância leve e refrescante • Toque floral-frutado equilibrado • Ideal para o dia a dia • Sensação de frescor prolongado • Não resseca a pele • Perfeito para climas quentes Caminho Olfativo Frutado • Floral MODO DE USO: Borrife diretamente sobre a pele limpa e seca, especialmente em áreas de maior circulação como pulsos e pescoço. Reaplique sempre que desejar renovar a fragrância. INFORMAÇÕES TÉCNICAS: • Tipo: Body Splash / Desodorante Colônia • Volume: 200ml • Público: Feminino • Fixação: Suave COMPOSIÇÃO Alcohol, Aqua, Parfum, Propylene Glycol, Benzyl Benzoate, Butylphenyl Methylpropional, Citral, Citronellol, Farnesol, Geraniol, Limonene, Linalool, Polyglyceryl-3 Caprylate', 85.9, 45.5, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820lo-mnx61ejpcmx0c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609741857%2F23198838575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
