INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898685296', 'Umidificador De Ar E Ionizador Alision Portátil Bivolt-Ioniza, Purifica E Melhora A Qualidade Do Ar', 'UMIDIFICADOR DE AR E IONIZADOR ALISION PORTÁTIL BIVOLT - IONIZA E UMIDIFICA O AMBIENTE, MELHORANDO A QUALIDADE DO AR. Respire um ar mais limpo! O Ionizador Umidificador Alision ioniza e umidifica o ambiente, melhorando a qualidade do ar. Baixo nível de ruído, com 2 bicos que se adaptam em qualquer garrafa pet (300ml a 1L). Possui as funções ionizador e umidificador com funcionamento separado. São apenas 200g de peso, que cabem na palma da mão, além de acompanhar bolsa para transporte. Capacidade: 90ml/h Volume da Garrafa PET: 300ml até 1L Liberação de Íons Negativos: > 1.000.000 íons/cm³ Peso: 200 gramas Voltagem: Bivolt Potência: 12W Consumo de Energia: 0,6 kWh / mês (1 hora de uso por dia) Cor: Prata UTILIZAR APENAS AGUA FILTRADA!', 199.99, 104.99, NULL, 'Home Appliances > Small Household Appliances > Air Treatment', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lin5t9f1w8j91a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443028693%2F21898685296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
