INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594366801', 'Bebida Vegetal de Amendoas Baunilha Almond Breeze 1L', 'A Almond Breeze Baunilha é uma deliciosa bebida vegetal à base de amêndoas, ideal para quem busca uma alternativa saudável, leve e saborosa ao leite de origem animal. Produzida com amêndoas cuidadosamente selecionadas, ela combina o sabor suave e natural da oleaginosa com um toque aveludado de baunilha, tornando-se perfeita para o consumo puro, em receitas ou como acompanhamento de cafés, chás e cereais.', 23.9, 23.9, NULL, 'Food & Beverages > Beverages > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meuhci5l6akj16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1607520022%2F22594366801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
