INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793942929', 'Refletor Holofote LED Branco Quente 10W - DNI 6064', 'O refletor Slim Super LED SMD DNI 6064 é a escolha ideal para obter-se uma iluminação de alta potência com uma grande economia. <br>Refletor de alta qualidade com baixa emissão de calor e altíssima durabilidade.<br><br><br><br>Onde Usar:<br><br>- Entrada de garagens e portões;<br><br>- Portarias;<br>- Escadarias;<br><br>- Letreiros;<br><br>- Jardins;<br><br>E muito mais!<br><br><br><br>Praticidade:<br><br>- Iluminação super potente<br><br>- Alta durabilidade<br><br>- Baixo consumo<br><br><br><br>Ficha Técnica:<br><br>- Tensão: 127/220V (Bivolt)<br><br>- Potência Máxima:10W<br><br>- Tipo de LED:SMD<br><br>- Cor do LED: Branco / Frio<br><br>- Fluxo Luminoso: 900 Lm<br><br>- IP (Índice de Proteção):66 - Nota máxima é o 68<br><br>- Temperatura de Cor: 3000K<br><br>-Marca:DNI<br><br>- Código: DNI 6064<br><br><br>- Medidas: 12 x 12,8 x 3,8cm<br><br><br><br>Instalação:<br><br>Caso tenha alguma dúvida de como instalar o seu refletorDNI 6065, <br><br><br>Atenção:<br><br>Lembre de apertar bem os parafusos ao fim da instalação.<br>Evite instalar o refletor em posições que facilitem a entrada de água noproduto ou na fiação. Caso seja necessário, proteja a conexão do cabo com o produto.<br><br><br><br>Sugestão de Uso:<br><br>Para melhorar o desempenho do seu produto, sugerimos que utilize o sensor de presença DNI 6020de modo que aluz do seu refletor se acenda sempre que houver movimento.<br>Outro itemque sugerimos na utilização deste item é o DNI 6911.Este produto tem como finalidade acender a luz de seu refletor sempre que o ambiente escurecer.<br><br><br><br><br>*imagens meramente ilustrativas', 33.94, 33.94, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-lydo1ye00xpm89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F22793942929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23030830963', 'Além das Adversidades | Bill Johnson', 'Além das Adversidades Jesus é seu modelo e exemplo de como lidar com todas as crises e circunstâncias. Não fomos criados para sermos reativos às circunstâncias, mas facilmente nos tornamos vítimas dessa mentalidade. Quer seja em nossa vida pessoal ou no mundo ao nosso redor, somos tentados a reagir imediatamente de forma instintivas às crises que se apresentam. Oramos a partir de um lugar de instabilidade, medo e ansiedade, entretanto quando sabemos quem é o nosso Pai e o que Ele diz sobre o que estamos passando, podemos orar com confiança mesmo quando tudo ao nosso redor parece estar ruindo. Em meio a desastres e crises, concentre-se nas verdades imutáveis de quem Deus é, o que Jesus revelou sobre o Bom Pai e como Jesus lidou com as circunstâncias que enfrentou enquanto caminhava na Terra. Afinal, Jesus é o seu modelo e exemplo! Título: Além das Adversidades Autora: Bill Johnson Acabamento: Brochura Páginas: 144 Formato: Altura: 18 cm Largura: 12,5 cm Profundidade: 1,5 cm Peso: 250 g ISBN: 9786587532134 Editora: Chara', 30.87, 30.87, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-iq6um36lihov2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23030830963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
