INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698010979', 'Refil Para Remendo De Pneu Carro E Moto Macarrão Caixa 120 Peças', '2 CAIXAS DE REMENDO REFIL PARA PNEUS SEM CÂMARA Principais caraterísticas: - Não corra risco de perder hora em seu trabalho, perder uma reunião importante ou até mesmo de ser assaltado na rua fazendo a troca de seu pneu furado, com esse refil, você mesmo pode fazer o reparo do pneu em instantes, evitando riscos desnecessários; Modo de usar: - 1 Verificar o dano e remover o elemento perfurante; - 2 Limpar o furo com a agulha escariadora e determinar o tamanho e direção do dano; - 3 Colocar o reparo centralizado na agulha aplicadora; - 4 Introduzir o reparo no furo, de forma a preencher totalmente a área danificada; - 5 Retire a agulha e corte o excedente; Informações técnicas: - Refil para remendo de pneus de carros e motos; - 2 Caixas com 60 unidades, total: 120 refil; - Comprimento do refil: 100mm; - Espessura do refil: 6mm; - Fabricante: Rotta 376;', 51.9, 51.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Others', 'https://cf.shopee.com.br/file/br-11134207-820m3-mmgx9qrooxkw8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F509931028%2F19698010979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
