INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8671114173', 'Livro - Marilla de Green Gables - Capa comum - Principis', 'A pergunta de Anne ecoou em meu coração por toda a minha vida: Oh, Marilla, o que aconteceu? Este romance é a resposta para tal questão foi minha criação de Marilla Cuthbert e a origem de Green Gables antes de Anne Shirley chegar com seu espírito livre e caprichoso. Editora: Principis Edição: 1, 2021 Autor: Sarah McCoy Idioma: Português Páginas: 352 Dimensões: L 15.50 x A 22.60 x E 1.80 ISBN: 9786555523652', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/afa9b2d30c43511da3c4748ab0b4a476', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8671114173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098987953', 'Livro Literatura infantil Nico', '"Nico é meu amigo. Ele passou por um período meio complicado e ninguém conseguia entender o porquê de tanta chatice. O pai dele desvendou tudo quando foi à sua escola conversar com a professora dele. Que tal você também descobrir o que aconteceu? Basta abrir o livro! Boa leitura." - Carol Levy_x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2023_x000D_ Autor: Carol Levy_x000D_ Ilustrador: Lalan Bessoni_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.34_x000D_ ISBN: 9786553842038_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Família, Emoções, Sentimentos, Pai_x000D_ BISAC: Literatura Infantil / Temas Sociais / Emoções & Sentimentos_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmf-lmdp0spbzkgp0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21098987953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7992626100', 'Livro - O corvo e outros contos extraordinários - Capa comum - Principis', 'O Corvo e contos extraordinários é uma seleção dos textos mais expressivos do autor considerado o mestre do mistério e procura mostrar o gênio criativo de um dos mais conhecidos escritores americanos. Além dos contos, este volume também traz a tradução do poema O Corvo feita por Fernando Pessoa. Editora: Principis Edição: 1, 2019 Autor: Edgar Allan Poe Idioma: Português Páginas: 144 Dimensões: L 16.00 x A 23.00 x E 0.90 ISBN: 9786550970352', 24.9, 24.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/e62bbf26f26f95b4fa63e7f5ed11d4e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F7992626100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197738390', 'Lâmina De Tosa Pet Andis Ultraedge - 15 1.2mm', 'As lâminas profissionais Ultraedge, sinônimo de avanço tecnológico, são responsáveis pela longa durabilidade do corte, pelo excelente desempenho e pelos longos intervalos entre a afiações. As lâminas têm um acabamento especial em cromo para resistir oxidações, acarretando melhora no desempenho. Compatíveis com as marcas Oster A5 , Andis, AG, AGC, WahlKM1, Km2 e Laube. ALTURA DO CORTE: 1,2 mm Marca: Andis', 365.0, 357.7, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8akblbggnox80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F23197738390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
