INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25916554427', 'rire seasalt scalp scrub 200g', 'Esfoliante de couro cabeludo de salto rire da coreia 💛Água do mar rica em minerais para couro cabeludo e cabelo saudável Esfoliante capilar com sal marinho. 💛Dead Sea sal 35% e água do mar ajudam a resíduos no couro cabeludo e cuidados com o óleo. 💛O ingrediente patenteado fornece couro cabeludo e cabelo com nutrição e umidade. 💛Teca-biome dá ao couro cabeludo um cuidado calmante confortável. 💛5 tipos de óleo fermentado e 10 tipos de nutrição capilar proteica. 💛Fórmula ácida fraca de pH4,5 ~ 5,5 para couro cabeludo sensível. 💛A textura úmida e macia da textura úmida e macia cria bolhas quando enroladas. 💛Frescura do mar e aroma de frutas frescas. 💛Produto funcional de alívio de sintoma de perda de cabelo para perda de cabelo. [Como Usar] 1. Molhe o cabelo e o couro cabeludo com água em abundância e aplique uma quantidade adequada. 2. Role suavemente o conteúdo aplicado e massageie em 5 minutos. 3. Enxágue bem com água morna. Capacidade do produto] 200g #Korean Cosméticos Cosméticos #K-Beleza #good Produto comestível #good Preço do produto ————————————————————————————————————————————————————————————————————————————————————————————————— ❤Três promessas de koksara.kbeauty 1.Realizamos desinfecção três vezes por semana.√ 2.Vendemos 100% genuíno.√ 3.Tempo portátil: Todo o tempo [24/7].√', 120.84, 91.5, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134207-7rcep-lsgdstngg0if00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F457864097%2F25916554427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
