INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593189369', 'Par de Caixas JBL Control SA-6 PRO Passiva Preta - 100 Watts RMS', 'Par de Caixas JBL Control SA-6 PRO Passiva Preta - 100 Watts RMS As caixas JBL Control SA-6 PRO são ideais para quem procura qualidade sonora superior em ambientes profissionais. Com potência de 100 Watts RMS, elas proporcionam um som claro e potente. Seu design compacto e elegante se integrem facilmente a qualquer decoração. Além disso, estas caixas são passivas, o que significa que precisam ser conectadas a um amplificador externo para funcionar. São perfeitas para uso em bares, restaurantes, salas de conferências e outros espaços que necessitam de um áudio de alta qualidade. Especificações Técnicas: • Marca: JBL • Modelo: Control SA-6 PRO • Tipo: Caixas acústicas passivas • Cor: Preto • Potência RMS: 100 Watts • Impedância: 8 Ohms • Sensibilidade: 88 dB (1W/1m) • Resposta de Frequência: De 75Hz a 18kHz. • Peso: O peso líquido de cada caixa é de 3,12 kg. • Conexão: Utiliza borne de pressão. • Uso: Interno e externo (resistente às intempéries) • Aplicações: Ideal para instalações comerciais, bares, restaurantes, lojas e ambientes corporativos. Conteúdo da Embalagem: • 01 Par de Caixas JBL Control SA-6 PRO • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor do Par.', 1356.06, 1274.7, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdy8-ly6w9tkl5ibfd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F22593189369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
