INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29342195493', 'Devocional Café Com Deus Pai | Porções Diárias De Amor | Junior Rostirola | Edição 2026', 'Devocional Café Com Deus Pai | Porções Diárias De Amor | Junior Rostirola | Edição 2026 Imagine parar por alguns instantes e desfrutar de um momento intimo com alguém que lhe ama e tem a resposta para todas as suas aflições. Esta é a experiência que você encontrará no decorrer destas páginas: uma jornada para todo o ano com devocionais diários, nos quais você é convidado a um encontro com Deus Pai que, alem de proporcionar um novo modo de apreciar uma xícara de cafe, mostrara como a vida tambem pode ser saboreada. DEUS DESEJA TOMAR CAFÉ COM VOCÊ. Título: Devocional Café Com Deus Pai | Porções Diárias De Amor Autor: Junior Rostirola Números de Páginas: 400 Acabamento: Capa BrochuraDimensões: 14 cm larg. x 21 cm alt. Editora: Velos', 54.9, 27.51, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mffnb4oqbn5w77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F29342195493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
