INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42452353400', 'A República | Edição comentada por Benjamin Jowett | Platão', 'A República | Edição comentada por Benjamin Jowett | Platão Apresentado na forma de um diálogo entre Sócrates e três diferentes interlocutores, este texto clássico é uma investigação sobre a noção de uma comunidade perfeita e o indivíduo ideal dentro dela. Durante a conversa, outras questões são levantadas: O que é o bem? O que é realidade? O que é conhecimento? A República também aborda o propósito da educação e o papel das mulheres e dos homens como guardiães do povo. Com notável lucidez e hábil uso da alegoria, Platão chega a uma representação de um estado limitado pela harmonia e governado por reis filósofos. Esta versão, traduzida da língua inglesa e comentada por Benjamin Jowett, é inédita no Brasil e traz uma análise bastante completa da obra de Platão. SOBRE O AUTOR: Platão é um filósofo grego clássico, matemático, aluno de Sócrates, escritor de diálogos filosóficos e fundador da Academia de Atenas, a primeira instituição de ensino superior no mundo ocidental. Junto com seu mentor, Sócrates, e seu aluno, Aristóteles, Platão ajudou a lançar as bases da filosofia e da ciência ocidentais. Considerado um dos filósofos ocidentais mais importantes, exerceu influência sobre praticamente todas as figuras da filosofia depois dele. Seu diálogo A República é conhecido como o primeiro trabalho abrangente sobre filosofia política. Título: A República | Edição comentada por Benjamin Jowett Autor: Platão Páginas: 640 Capa: Brochura Dimensões: 16 x 23 cm Editora: Ciranda Cultural', 24.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rav8-maa80gs5tfzobb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F42452353400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12747083777', 'Par Farol Milha Auxiliar Crv 2010 2011', 'Código do produto: 72236 VALOR ANUNCIADO REFERENTE AO PAR - DIREITO + ESQUERDO. O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente em vidro que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Honda - CRV 2010 - CRV 2011 Especificações Técnicas: - Lente Lisa - Material da Lente em Vidro - Material da Carcaça em Plástico - Encaixe de lâmpada H11 ATENÇÃO Garantia - 3 Meses O valor anunciado é referente ao par. A Empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 242.83, 242.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/073753ec82ea385e0d7027f2e398a389', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F12747083777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
