INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697813567', 'Vença em silêncio | Como ganhar batalhas sem precisar falar | Diego Menin | Editora Vida', 'Vença em silêncio | Como ganhar batalhas sem precisar falar Vença em silêncio aborda a importância do silêncio em nossa vida espiritual e emocional. Com base em exemplos bíblicos, como o de Daniel — que enfrentou grandes batalhas espirituais em silêncio, por meio da oração —, Diego Menin argumenta que o verdadeiro guerreiro não é aquele que grita mais alto, mas o que sabe conter suas palavras e esperar o momento certo para agir. Através desta obra, você compreenderá os perigos de falar demais, especialmente quando movido pela raiva, tristeza ou desespero. Além disso, receberá conselhos práticos sobre como cultivar o silêncio em uma sociedade que valoriza o barulho e a constante comunicação. Uma leitura essencial para quem busca uma vida mais equilibrada e consciente, longe da superficialidade e da agitação do mundo moderno. Autor: Diego Menin Editora: Vida Acabamento: Capa brochura Dimensões: 16 cm largura x 23 cm altura Número de páginas: 160', 42.97, 42.97, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-m0bzfr9yiuh532', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F21697813567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
