INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193986109', 'Kit Reparo Rolamento Roda Traseira Mercedes 180 D 2.4 (1993 - 1996) - IRB013N', 'Os Kits de Rolamentos contam com rolamento interno, rolamento externo, graxa e retentor para aplicação! Especificações Técnicas: • Marca: IRB Automotive • Posição: Roda Traseira Aplicações: - Mercedes Benz 180 D 2.4 (1993 – 1996) Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. IRB é uma marca que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar ano, modelo e se o veículo é com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 129.9, 114.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9j6wkdlwncpb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F22193986109', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
