INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294646182', 'Kit 300 Peças Ferramentas Jogo De Brocas e Buchas Para Concreto Madeira Metal', 'Distribuído por Ismafer Ferramentas Descrição JOGO DE BROCAS BITS E BUCHAS COM 300 PEÇAS O Jogo de brocas bits e buchas com 300 peças é ideal para uso doméstico e hobby, conta com as brocas e bits e buchas com as medidas mais comuns. As Broca de concreto são feita de aço carbono com uma placa de metal duro feita de material VK8, brocas para metal de aço rápido (HSS), brocas para madeira são de aço-carbono. Bits de aço cromo vanádio, instrumentos embalados em caixa de plástico. ACOMPANHA: - 7 Brocas para metal: 2, 3, 4, 5, 6, 8 e 10 mm - 5 Brocas para madeira: 4, 5, 6, 8 e 10 mm - 5 Bocas para concreto: 4, 5, 6, 8 e 10 mm - 1 Prolongador - 2 Bits fenda - 4 Bits phillips - 120 Buchas 4mm - 65 Buchas 5mm - 50 Buchas 6mm - 25 Buchas 8mm - 16 Buchas 10m Garantia do fabricante: 3 meses Distribuído por Ismafer Ferramentas', 99.0, 54.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lx-mq4vgft7l7gg12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617570446%2F22294646182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42304316548', 'Engate Mult Engates Para Moto Yamaha 125/150 Factor Fazer Com Alta Durabilidade', 'Engate Rabicho Reboque Fixo Brucke 300kg Tração Aço Carbono Yamaha Factor 125 150 Fazer 150 2016 2017 2018 2019 2020 2021 2022 2023 2024 Moto Motos YBR Cromado Pintura Anticorrosiva Resistente Forte Pino Esfera Certifique-se de escolher o modelo correto para sua moto. Engate referente à motos Yamaha Factor 125/150 e Fazer 150 de 2016 até 2024 Os engates Brucke são fabricados em aço carbono de alta resistência, garantindo durabilidade e confiabilidade em diversas condições. O kit completo inclui pino bola, tomada de engate, em acabamento cromado. Contendo uma tração máxima de 300kg, sendo assim o melhor custo benefício do mercado nacional. Recomendações de Uso: • Verifique as especificações do seu veículo antes de realizar a instalação. • Certifique-se de que o peso total da carga esteja dentro dos limites de tração e peso sobre esfera especificados para este engate. • Recomenda-se que a instalação seja feita por um profissional qualificado para garantir o perfeito funcionamento e evitar danos ao veículo. Características e especificações do engate: • Engate fabricado em Aço Carbono • Estrutura moldada em uma única peça, sem solda na cabeça do engate, garantindo maior resistência • Sem necessidade de furar a moto para instalação • Pintura Eletrostática (anticorrosiva) e epóxi resistente a corrosão, umidade e produtos químicos • Acabamento em cromado • Carga Máx sobre a esfera: 20kg • Carga Máx de tração: 300kg • Modelo Compatível: Yamaha Factor 125/150 / Fazer 150 de 2016 até 2024 • Produto regularizado de acordo com a resolução Nº 197 do Contran • Homologação Certificada pelo INMETRO 012587/2022 Conteúdo da embalagem: • 1 Engate YH-1000 - Yamaha Factor 125/150 / Fazer 150 • 1 Bola cromada (pino esférico de 50mm) • 1 Tomada plástica (fêmea) • 1 Fio de 1,2 metros (4 vias) • Kit parafusos para instalação', 429.9, 380.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-7rau9-max1yckob2iec4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1273324128%2F42304316548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
