INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694176309', 'Micro Stick CarXParts - 1mm', 'Micro Stick CarXParts - 1mm 🧹✨ O Mini Stick CarXParts é a ferramenta ideal para limpar os espaços mais difíceis nos veículos, com cabeça de 1mm, permitindo atingir os menores detalhes com precisão. Perfeito para quem se dedica ao detalhamento automotivo e sabe que cada pequeno detalhe faz a diferença na qualidade do trabalho. ✨ Características: ✅ Precisão: Cabeça de 1mm para alcançar os menores detalhes. ✅ Higienização Completa: Ideal para espaços de difícil acesso em veículos. ✅ 🧽 Eficiente: Limpeza de detalhes que passam despercebidos com ferramentas convencionais. ✅ Versatilidade: Perfeito para profissionais e para quem deseja um acabamento impecável. 🔧 Modo de Uso: 🧼 Use o mini stick para alcançar e limpar áreas pequenas e difíceis de acessar. 💨 Passe suavemente nos locais desejados, sem danificar as superfícies. ✨ Remova o excesso de sujeira e finalize a limpeza com um pano de microfibra. 📊 Informações Técnicas: 🧳 Tamanho: 1mm 📦 Embalagem: Vendido em unidades 🛠️ Uso: Ideal para detalhes de difícil acesso e acabamentos minuciosos O Micro Stick CarXParts é a ferramenta que você precisa para garantir que nada passe despercebido e oferecer o melhor serviço de detalhamento automotivo. Perfeito para quem valoriza acabamentos impecáveis! ✨', 8.99, 8.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra3x-mbfnpzh7ob65f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1510588915%2F22694176309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
