INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12046341023', 'Spray Antimicrobiano Furanil Vetnil 60ml', 'Furanil solução é indicado para cães e gatos na profilaxia e tratamento das infecções bacterianas e fúngicas da pele e mucosas, órgãos genitais, piodermites, foliculites, pododermatites e micoses. Também estão indicados para a assepsia de feridas, cortes, escoriações, abscessos, fístulas e ulcerações de decúbito. Modo de usar Fazer a assepsia das regiões afetadas com a utilização do Furanil, deixar agir durante 10 minutos e enxaguar. Repetir a aplicação do produto, deixando uma camada recobrindo o local. As regiões afetadas podem ser recobertas com gaze ou outros curativos. Repetir o tratamento diariamente até a cura. A frequência de aplicação poderá ser alterada de acordo com a orientação do Médico Veterinário.', 85.9, 83.33, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/67ebdc15121da36e95c07f3b02b1d26a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F12046341023', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
