INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259465558', 'Energético Natural SEDE com Cafeína Microencapsulada', 'SEDE é um energético natural e funcional que combina bem-estar, foco e disposição em uma fórmula 99,72% natural, com apenas 55 kcal por lata e adoçado com suco de maçã. Sem conservantes nem aditivos artificiais, com 100mg de cafeína microencapsulada, garante energia limpa, gradual e sustentada. Lata de 250ml.', 10.49, 10.49, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mqxn6j13dqtif6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555142%2F58259465558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40075839153', 'Bomba D''água Submersa Suja/limpa BSV450 Vonder', '***PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL Conteúdo da Embalagem: 1 Bomba submersa. Com capacidade de até 7.000 litros por hora, transporta com eficiência água limpa ou suja com partículas em suspensão de até 20 mm (mangueira de 1.1/4") e 16 mm (mangueira de 1"). Possui chave boia, que liga e desliga automaticamente de acordo com o nível da água, evitando funcionamento a seco, além de cabo de alimentação com 10 metros de comprimento. Ideal para esgotamento, drenagem, transferência de água de reservatórios, caixas, cisternas, água de piscinas, pequenos lagos e tanques. Não utilizar para transferência de água salgada. Temperatura máxima da água: 35°C. Garantia legal: 90 dias + Garantia contratual: 3 meses Potência da bomba submersa:450 W Altura manométrica máxima da bomba:7,0 m Vazão máxima da bomba:7.000 litros/hora Medida da saída de água da bomba:1" e 1.1/4" Altura da bomba submersa:360 mm Largura da bomba submersa:155 mm Cor da bomba: Preto e amarelo Classe de proteção de choque elétrico: Classe l Tensão (V):127 V~ Frequência:60 Hz Massa aproximada (peso):5,75 kg', 645.9, 645.9, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820lk-mm90h50mdibo1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F40075839153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198815647', 'Kit Máscara Labial Noturna (2 Produtos)', 'Máscara Hidratante Labial Noturna, É Um Poderoso Antioxidante, Que Possui Textura de Bálsamo. Seus Ativos Promovem Hidratação, Combatem As Células Mortas e Ainda Promovem Maciez Intensa para Os Seus Lábios. Especialmente Desenvolvido para Cuidar Dos Seus Lábios Durante a Sua Noite de Sono, a Máscara Labial Noturna Océane, Revigora e Rejuvenesce a Região e Ajuda a Eliminar As Peles Soltas. Produzida Na Coreia do Sul, Referência em Skincare, a Máscara Labial Noturna Océane Traz em Sua Essência Toda a Tecnologia Testada e Validada Pelas Coreanas. com a Máscara Hidratante Labial Noturna o Seu Skincare Ficará Mais Completo! Veja Como Ela Pode Ajudar a Recuperar a Saúde Dos Seus Lábios com Poucas Aplicações. Uso Diário e de Fácil de Aplicar, a Máscara Labial Noturna É Livre de Parabenos e Silicones. Ela Possui Uma Embalagem de Bisnaga com Bico Dosador, Que Facilita a Aplicação Nos Seus Lábios. Com Óleo de Grapefruit, a Máscara Labial Noturna É Produzida com Óleo de Grapefruit e Mel de Abelha, Que Ajuda a Combater o Ressecamento e a Prevenir o Aparecimento de Peles Soltas Nos Seus Lábios. Lábios Brilhosos e Macios, o Uso de Hidratante para Lábios Deixa a Sua Boca com Um Toque Bem Macio, Pois Possui Uma Textura de Bálsamo, Proporcionando Uma Melhor Absorção Dos Seus Ingredientes Nutritivos. Dica: com o Uso Contínuo, Os Lábios Ficam Mais Saudáveis e com o Contorno Mais Definido. O Kit Máscara Labial Noturna Contém: - 2 Máscara Labial Noturna - Lip Sleeping Mask 15g', 109.9, 109.9, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134201-82584-mqnt5nhcw4qze5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F18198815647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
