INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194232151', 'Cranberry com Vit. C e Zinco em Cápsulas - 60 Cápsulas - 3 Unidades', 'Cranberry + Vitamina C + Zinco – Suporte Imunológico e Antioxidante O suplemento Cranberry + Vitamina C + Zinco combina três ingredientes reconhecidos por suas propriedades nutricionais. É ideal para quem busca complementar a alimentação com nutrientes que auxiliam na imunidade, proteção antioxidante e na manutenção da integridade da pele. Benefícios com alegações permitidas pela Anvisa (IN nº 28/2018): Vitamina C Auxilia no funcionamento do sistema imune Auxilia na absorção de ferro dos alimentos Auxilia na formação do colágeno Atua como antioxidante, protegendo as células contra os radicais livres Zinco Auxilia no funcionamento do sistema imune Auxilia na manutenção da pele, cabelo e unhas Contribui para o processo de cicatrização Atua como antioxidante Auxilia na síntese de proteínas e divisão celular Por que incluir Cranberry + Vitamina C + Zinco na sua rotina? Fórmula prática e completa para quem busca reforço imunológico e proteção antioxidante no dia a dia Apoio à manutenção da integridade da pele e à cicatrização Combinação estratégica de nutrientes essenciais em uma cápsula diária Como usar? Uso oral: tomar 1 cápsula ao dia, com 200 ml de água, preferencialmente após o almoço ou jantar, conforme indicação da embalagem. Ingredientes: Cranberry em pó (Vaccinium macrocarpon), ácido ascórbico (Vitamina C), bisglicinato de zinco, amido e antiumectante dióxido de silício. Ingredientes da cápsula: Gelatina e dióxido de titânio. NÃO CONTÉM GLÚTEN. ALÉRGICOS: PODE CONTER LEITE, SOJA, PINOLI (Pinus spp.) E CRUSTÁCEOS (CARANGUEJO).', 107.73, 105.58, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mby6lqntxys96c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543591764%2F22194232151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
