INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53554686011', 'Strogonoff de Frango 250G Só Aquecer Vapza', 'LINHA:Só aquecer INGREDIENTES: Carne de frango, creme de leite, água, cogumelo champignon, catchup, amido modificado de mandioca, molho mostarda, sal, cebola e alho. Contém glutén? Não Info. complementar alérgicos: Contém Lactose. Prazo de validade:12 meses Condições de armazenamento:Armazenar em temperatura ambiente (até 30°C) em local seco e arejado. Não consumir se a embalagem estiver danificada. Após aberto, manter sob refrigeração e consumir em, no máximo, 2 dias ou congelar por até 1 mês.', 32.12, 24.9, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Hotpot', 'https://cf.shopee.com.br/file/sg-11134201-8261i-mjhk7rxwa8zq51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F53554686011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250371895', 'Kit Volante e Pedal T98 Ferrari para PS4, PS5 e PC - Thrustmaster', '"Uma dose de prazer em cada volta com o T98 Ferrari 296 GTB! Conduza como um(a) autêntico(a) piloto de corridas com este volante licenciado pela Ferrari inspirado no Ferrari 296 GTB real e mergulhe em corridas empolgantes. A tecnologia de recentragem e o ângulo de rotação de 240° com resistência linear permitem o controle preciso do veículo, para executar trajetórias vencedoras e ultrapassar os rivais. O aro de volante e as patilhas de velocidades em imitação de carbono fornecem uma manobrabilidade excelente, para sensações de condução desportiva! O seletor inspirado no emblemático Manettino da Ferrari permite-lhe alternar entre os 3 perfis de apoio à condução (desde o mais realista até ao mais fácil de utilizar) para se adequar a todos os níveis de condução, quer seja um(a) principiante ou um(a) piloto experiente. O T98 Ferrari 296 GTB irá tornar os seus jogos de corridas de automóveis mais imersivos e intensos, para corridas inesquecíveis – sozinho(a), ou com a família e amigos!" Características Tipo: Kit Volante e Pedal Compatibilidade: PS4, PS5 E PC Especificações Técnicas Modelo: 4160880 Cor: Preto e Cinza Voltagem: 110V Garantia: 12 meses Dimensões e Peso Dimensões do produto sem embalagem (AxLxP): 288x340x270 mm Dimensões do produto com embalagem (AxLxP): 330x260x275 mm Peso do produto sem embalagem: 3,34 Kg Peso do produto com embalagem: 3,00 Kg Itens Inclusos 01 Kit de Volante e Pedal', 1558.7, 1558.7, NULL, 'Computers & Accessories > Peripherals & Accessories > Mouse Pads', 'https://cf.shopee.com.br/file/sg-11134201-821df-mgpko3b13024c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F854082976%2F58250371895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52607581071', 'Santa Helena Pasta Amendoim Caramelo Salgado 500g', 'A Santa Helena Pasta Amendoim Caramelo Salgado 500g possui textura cremosa e sabor intenso do amendoim. É uma opção prática para o dia a dia, ideal para quem busca um alimento versátil para diferentes momentos. Pode ser consumida no café da manhã, lanches ou utilizada no preparo de receitas, combinando bem com pães, torradas, frutas, vitaminas e outras preparações. Produzida pela Santa Helena, marca tradicional em produtos à base de amendoim, oferece qualidade e sabor em uma pasta com textura suave e fácil de espalhar. Sem Glúten. Sem Lactose. Sem adição de açúcares.', 57.39, 57.39, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Jam & Spread', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mm6enllf045r59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F52607581071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193068228', 'Motoca Triciclo Infantil Completa Certificada INMETRO - Modelos Roxo/Rosa/Vermelho e Azul', 'Descubra a Motoca dos Sonhos para as Pequenas Aventureiras! A Motoca Mais Vendida do Brasil com o Melhor Custo-Benefício - Modelo 2024 Pronta para Levar Sorrisos e Diversão! Perfeita para Meninas de 12 a 36 Meses Disponível nas encantadoras cores Tiffany, Rosa, Azul e Vermelha, nossa motoca é certificada pelo INMETRO e suporta até 16 kg, garantindo segurança e qualidade. Especificações: Dimensões: Comprimento: 88 cm Largura: 42,5 cm Altura: 88 cm Inclui: 1 Motoca completa 1 Protetor de corpo removível 1 Suporte para os pés 1 Assento anatômico 1 Haste removível Benefícios para o Desenvolvimento Infantil: Atenção e Concentração: A diversão que também ajuda a focar em tarefas e detalhes. Compreensão de Causa e Efeito: Aprendizado divertido sobre a relação entre ações e consequências. Coordenação Motora: Estimula as habilidades motoras finas e grossas. Imaginação e Criatividade: Incentiva o pensamento criativo e a expressão individual. Garantia de Diversão e Desenvolvimento Transforme o dia a dia da sua pequena com uma motoca que não só oferece momentos inesquecíveis de diversão, mas também contribui para seu crescimento e aprendizado. Seja na calçada, no parque ou no quintal, cada passeio será uma nova aventura. Adquira agora a motoca mais amada do Brasil e veja o sorriso no rosto da sua pequena!', 139.9, 120.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7jdvacyubhuea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F22193068228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197785595', 'Confeito Figuras Coração Mil Cores 120g Mavalério', 'Decoração de brigadeiros, docinhos, bolos, tortas, pães de mel e cupcakes; Ideal para pistas de sorvetes; Ideal para colorir massas de bolos e cupcakes. ALÉRGICOS: PODE CONTER DERIVADOS DE LEITE E SOJA. NÃO CONTÉM GLÚTEN. INGREDIENTES: Açúcar, farinha de arroz, óleo vegetal de palma, glicose em pó, fécula de mandioca, umectante glicerol (INS 422), espessantes goma arábica (INS 414), goma xantana (INS 415) e carboximetilcelulose sódica (INS 466), glaceante talco (INS 553iii), extrato de cacau e corante vermelho 40 (INS 129). Armazenar fechado em local fresco, seco, limpo e inodoro. Evitar exposição ao sol. Após aberta a embalagem, recomenda-se o consumo do produto em até 30 dias e que ela seja guardada bem fechada em local fresco, seco, limpo e inodoro. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 17.99, 17.99, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcm2d0ee1e7m35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F22197785595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
