INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10587256511', 'Kit p/ Porta Correr Trilho Alumínio 35x35 1,80m Branco - RDA-2', 'Os kits de instalação para portas de correr suspensas da marca ALFER, é forma mais fácil e barata para se instalar uma porta de correr. Todos os produtos da marca são testados por profissionais para garantir o melhor resultado aos consumidores, visando a facilidade e praticidade para instalação sempre zelando qualidade final. A ALFER já possui anos de experiência no mercado de ferragens e a ELETTRO é especialista em vendas online, prezando pelo melhor produto e atendimento para você fazer uma compra segura e de alta qualidade. ATENÇÃO: - Kit NÃO acompanha porta, NÃO acompanha fechadura e nem batente. - Devido os Correios aceitarem apenas embalagens até 70cm, os trilhos são enviados dividos. Não se preocupe, os trilhos desenvolvidos para que na instalação se encaixam perfeitamente e a porta trabalhe normalmente. Características Gerais do Produto: • Cor: Branco • Guia Inferior: Escova 5x7cm • Largura Indicada para Porta: 90cm • Marca: Al-Fer • Material: Alumínio • Medida Trilho Total: 1,80 metros • Peso Suportado: 60kg • Roldana: RDA-2 - 2 Rodinhas Côncava 28mm Rebitadas - Eixo Injetado • Tipo Trilho: Com Suporte Côncavo 35x35mm Acompanha o produto: • Trilho • 2 Roldanas • 2 Freios p/ Roldanas • 1 Guia Escova 5x7cm • Suportes para Fixar Trilho na Parede • Parafusos e Buchas para Aplicação • Manual de Instalação Garantia: • 3 meses', 131.9, 131.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/395d161f92f965ad23f9bdb703210635', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429425876%2F10587256511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
