INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199307106', 'Kit 20 Painel Led Pop De Embutir Quadrado 6500K Branco Frio 18w Avant', 'Painel Led Pop de Embutir Quadrado 6500W 18W Avant A linha PAINEL POP EMBUTIR QUADRADO é versátil e pode ser usada em ambientes residenciais, comerciais e corporativos, proporcionando uma iluminação homogênea com design clean e moderno. - Corpo e difusor em policarbonato - Fluxo luminoso constante em toda faixa de tensão. - Baixo consumo de energia. ATENÇÃO: - Na instalação do transformador eletrônico, certifique-se de que o mesmo não ficará em contato com a luminária, pois toda a base da luminária funciona como dissipador de calor, o que pode causar danos e interferências no funcionamento do transformador. - Para melhor fixação do painel POP de embutir, a espessura do forro deve ser de pelo menos 1cm. - Para garantia da vida útil do painel POP, recomenda-se uma distância de pelo menos 10 cm entre o forro e a laje. Referencia: 0775 - Código: 903011374 - Modelo:PAINEL POP QUADRADO EMBUTIR - Marca: Avant - Potência: 18w - Fluxo Luminoso: 1080 Lumens - Eficiência Luminosa: 70lm/w - Ângulo de Abertura: 120 Graus - Temperatura da Cor: 6500K - Emissão de Luz: Branco - Tipo de instalação: Embutir - Temperatura ambiente: -5C a 40C. - Tensão nominal: 100V a 240V. - Fator de Potência: 0,50 Dimensões Aproximadas do Produto: - Altura: 210mm - Largura: 210mm - Comprimento: 16mm *** GARANTIA DE 1 ANO CONCEDIDO PELO FABRICANTE ***', 299.99, 176.99, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-ly2fkv3w71vgfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F19199307106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
