INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397928782', 'Brinquedo Infantil Bloco de Montar Fazenda Pomar 135 Peças Xalingo - 68154', 'Explore o encanto do campo e crie aventuras emocionantes com o Conjunto de Blocos Fazenda Pomar de 135 Peças! Este emocionante conjunto oferece uma experiência de construção única, trazendo toda a diversão e alegria de uma fazenda diretamente para as mãos das crianças. Com 135 peças coloridas e detalhadas, este conjunto permite que os pequenos construtores criem sua própria fazenda em miniatura. Destaque para o pomar, uma peça central que acrescenta realismo e charme ao cenário rural. Além das peças de construção, o Conjunto de Blocos Fazenda pomar apresenta um personagem articulado, pronto para embarcar em aventuras pela fazenda junto ao seu carrinho de mão. As crianças podem imaginar e encenar uma variedade de atividades agrícolas, desde alimentar os animais até colher frutas e legumes frescos. Características: - Marca: Xalingo - Modelo: 68154 *Imagens Meramente Ilustrativas* Ficha Técnica: - Idade: 5 - 7 anos, 8 - 11 anos, 12 anos ou mais - Dimensões Aproximadas (AxLxC): 19,5 X 5X 25,5 cm - Quantidade de peças: 135 Conteúdo da Embalagem: - 1x Brinquedo de Montar Xalingo 135 Peças', 61.28, 55.15, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdxd-m1d6furxlj0e42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F22397928782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44021672380', 'Micro Retífica 1/8'''' 135W 40 Peças c/ Maleta RMI-0135 Ranger', 'MICRO RETÍFICA 135W 40 PCS COM MALETA (RMI-0135) A Micro Retífica Ranger RMI-0135 é uma ferramenta versátil e indispensável para trabalhos de precisão. Compacta e eficiente, é ideal para cortar, esculpir, gravar, lixar, polir e muito mais, atendendo tanto profissionais quanto hobbistas que buscam praticidade e qualidade. Com motor de 135W, a RMI-0135 oferece rotação variável entre 8.000 e 32.500 rpm, adaptando-se a diferentes aplicações. Acompanha 40 acessórios e uma maleta para facilitar o transporte e organização. Seu cabo com dupla isolação e 1,8 m proporciona segurança e mobilidade durante o uso. Características: - Potência: 135W - Rotação variável: 8.000 a 32.500 rpm - Acompanha 40 acessórios - Maleta para transporte e organização - Cabo com dupla isolação - Comprimento do cabo elétrico: 1,8 m - Encaixe: 1/8” Informações Técnicas: - Modelo: RMI-0135 - Potência nominal: 135W - Faixa de rotação: 8.000 a 32.500 rpm - Encaixe: 1/8” - Cabo elétrico: 1,8 m - Cabo: Dupla isolação - Acessórios inclusos: 40 peças Conclusão: A Micro Retífica Ranger RMI-0135 combina potência, precisão e praticidade, sendo perfeita para projetos detalhados e multifuncionais. Com seus acessórios e maleta, garante organização e versatilidade em qualquer ambiente de trabalho. Marca: Ranger Modelo: RMI-0135 Garantia de fábrica: 12 meses', 294.0, 191.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gw-mf42erw1m13hec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406223656%2F44021672380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
