INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397172271', 'Kit Mochila Escolar Lequeen Gatinho Infantil Lancheira Rodinha Carrinho', 'Ficha Técnica Mochila Medidas (AxLxC): 40x30x18 Material: Poliéster Capacidade: 21 Litros Peso: 3,40kg Ficha Técnica Lancheira Medidas: (AxLxC): 25x24x9 cm Peso: 0,50kg Capacidade: 5 Litros Ficha Técnica Estojo Medidas (AxLxC): 13x20x15 cm Peso: 0,12g Capacidade: 3 Litros Características Mochila Alças acolchoadas Alças guardáveis Etiqueta de identificação Rodinhas em gel Zíper reforçado de ferro Haste de alumínio Não cai pra frente com peso Bolso para agenda Bolsos para canetinhas Bolso para notebook Bolso telado ao lado Características Lancheira Térmico: Sim Alça de mão reforçada Etiqueta de identificação Zíper reforçado de ferro Características Estojo Amplo Espaçoso Resistente Cuidados de conservação: Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro Evite carregar excesso de peso Embalar objetos cortantes para não perfurar *3 meses de garantia* Sobre a Marca: Pensada para atender as mais diversas ocasiões a frasqueira Lequeen é resistente e reforçada, além de possuir bastante espaço interno e um estilo moderno. Este produto é perfeito para sua próxima viagem e organizar seus itens.', 999.9, 799.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0xew49l5cg01b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F345061139%2F23397172271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898017083', 'Escapamento Titan 160/ Start 160/ Fan Modelo Turuna Fortuna', '🚀 Escapamento Turuna Fortuna 🏍️ | HB Moto Peças 🔥 🎧 Estrala bonito, chama atenção e deixa sua moto com presença! 👉 Compatível com TITAN / FAN / START 160cc – modelos de 2016 a 2025 🔧 Pronto pra instalar — encaixe perfeito sem adaptação! 💥 Som nervoso 💣 e acabamento cromado que brilha na pista ✨ 🛠️ Feito em aço carbono, resistente e estiloso 🏁 Modelo Turuna original (não é mini!) ✅ Com selo INMETRO, pra rodar com segurança e confiança 🛒 Já disponível na HB Moto Peças & Acessórios! 💯 Produto oficial da Fortuna — qualidade reconhecida 📦 Envio rápido, compra segura e atendimento top 😎 ⏳ Garantia de 30 dias pra você ficar tranquilo 🎤 Se liga, parceiro: Esse escapamento é pra quem curte estilo, som marcante e quer marcar presença. 🔥 Não vacila... garanta o seu e vem pro time dos que aceleram com atitude! 😈🏍️💨 #VibesDePiloto #MotoÉEstilo #EscapamentoTuruna #HBMotoPeças #FortunaNoComando', 289.99, 275.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-7rdvm-mcs51vy003k0f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235796208%2F18898017083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27980961126', 'Livro Feminina | Karine Rizzardi', 'Feminina | Karine Rizzardi Sem culpa, sem pressa, simplesmente feminina.Ao observar tantas mulheres sobrecarregadas, tentando equilibrar uma rotina exaustiva de trabalho com a plenitude de suas famílias — provendo amor, cuidado e atenção —, senti o chamado para fazer algo a respeito. Decidi criar grupos de feminilidade, espaços onde mulheres pudessem vivenciar, juntas, o caminho de volta à sua essência. Um retorno à verdadeira feminilidade, respeitando a singularidade de cada uma ao longo dessa jornada transformadora.Esses grupos me proporcionaram muitas descobertas, que agora compartilho com você nestas páginas. Elas têm uma característica muito especial: são como uma “mãe” que acolhe, compreende e acompanha, mas também sabe corrigir com amor quando necessário. Respeita suas conquistas e seu modo de ser, mas sonha em vê-la transbordando em sua feminilidade.Portanto, eu a convido a embarcar nesta jornada que lhe revelará como a vida pode ser muito mais leve. Seja jovem ou madura, casada ou solteira, do lar ou profissional, algo nos une profundamente — somos mulheres.', 49.81, 49.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd4e-m7tqczai1jht46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F27980961126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
