INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20052453955', 'Bíblia Sagrada Cristo Vive | NVI | Letra Normal | Capa Flexivel', 'Bíblia Sagrada Cristo Vive Capa dura ilustrada bíblia que pode ser usada para evangelismos. Bíblia Sagrada com a linguagem na versão NVI (Nova Versão Internacional). Dentre as versões da bíblia ela se torna uma das mais modernas e preservando a clareza do texto permanecendo fiel aos Escritos originais. Uma exclusividade Plenitude Distribuidora. Recurso Palavras de Jesus em vermelho Título: Bíblia Sagrada Capa Dura Linguagem: Nova Versão Transformadora Ano de edição: 2022 Acabamento: Capa Dura Cor: Ilustrada Borda: Branca Índice: Não Palavras de Deus e Jesus em destaque: Vermelho Harpa: Sem harpa Páginas: 768 Letra: Normal Formato: Altura 21 cm Largura 14 cm Profundidade 2 cm Peso: 0.480 kg ISBN: 7898379480393', 23.9, 23.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma9uaegvxkl5c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20052453955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093884281', 'Joico K-PAK Shampoo 1L Condicionador 1L Hidratação 250ml', 'Kit de tratamento para cabelos finos e danificados. Joico K-Pak Liquid Reconstruction Kit limpa suavemente, desembaraça e condiciona além de proporcionar hidratação e elasticidade aos fios. Desenvolvido para recuperar os danos, Joico K-Pak Liquid Reconstruction Kit restaura intensamente, fortalece a fibra capilar e sela as cutículas. Com Joico K-Pak Liquid Reconstruction Kit seu cabelo fica macio, saudável, brilhante e muito mais resistente! Contém Joico K-Pak To Repair Damage - Shampoo 1L: shampoo para cabelos danificados, tanto finos quanto grossos. Limpa suavemente, restaurando, fortalecendo e protegendo os fios. Joico K-Pak To Repair Damage Conditioner - Condicionador 1L: condicionador para cabelos danificados. Condiciona e desembaraça enquanto hidrata e reconstrói, além de fortalecer os fios. Joico K-Pak Intense Hydrator Smart Release - Mascara Capilar 250ml: para cabelos danificados e ressecados, oferece tratamento de hidratação profunda e auxilia na reconstrução dos fios. Conselho de Aplicação Aplique o shampoo no cabelo molhado, massageie até formar espuma. Depois, enxágue. Depois, aplique o condicionador no cabelo limpo e úmido. Deixe agir por cerca de 1 minuto e enxágue. Aplique a mascara capilar nos cabelos limpos e úmidos. Pause por 5 minutos e enxágue completamente.', 1452.05, 739.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7renk-m8ajqvu9f0yfbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23093884281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698395477', 'Redken Extreme - Máscara 500ml', 'Redken Extreme - Máscara 500ml Máscara de condicionamento profundo para cabelos danificados. Possui ação fortalecedora que promove fios 15x mais fortes. Desenvolvida para garantir o máximo poder de reconstrução aliado ao condicionamento profundo dos fios. Contém strength complex, enriquecido com proteína e ácido lático, ativos que restauram a força e equilíbrio do pH dos cabelos, promovendo maciez intensa. Repõe aminoácidos, recuperando a força e resistência dos fios. Conselho de Aplicação Após lavagem com shampoo, aplique a máscara nos cabelos úmidos. Deixe agir de 3 a 5 minutos e enxágue bem.', 231.4, 231.4, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7repq-m8aiwdfyr0rtc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22698395477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
