INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42501740199', 'Livro Deus Está Em Sua Casa? | Mac Anderson', 'Deus Está Em Sua Casa? | Mac Anderson 2º Edição Mac Anderson Em Deus Está em Sua Casa?, mergulhamos em um oceano de fé e renovação, onde apenas Cristo tem o poder de transformar vidas. Com base nos milagres de Marcos 2, esta obra revela não apenas a essência sagrada que habita cada lar, mas também o impacto radical da luz de Jesus ao dissipar as trevas. Através de narrativas inspiradoras e meditações profundas, o livro nos desafia a reconhecer — e revitalizar — a presença d’Ele em nossos corações e lares. Uma casa com Jesus é diferente: transborda alegria, propósito e torna-se um santuário de cura, esperança e refúgio. Prepare-se para ver seu lar sob uma nova perspectiva. Páginas:72Dimensões:12,5 x 0,7 x 18 cm', 18.06, 18.06, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rasy-ma1sc71nrbxo8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42501740199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693072264', 'Violão Eletrico Hofma Hmf 240 Mini Jumbo Red+ Capa Reforçada', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual é o nosso diferencial? Buscamos sempre oferecer qualidade com excelência por isso todos os nossos produtos são de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletrônica e garantia de fabrica. Você é bem vindo para fazer parte da nossa história ACOMPANHA: -01 CAPA REFORÇADA EM NYLON 600 -03 PALETAS Violão Mini Jumbo Eletroacústico Cutway HMF240 Vermelho Satin Violão desenvolvido para atender um público que busca um produto versátil, com acabamento excepcional e tocabilidade incomparáveis para a categoria. Por ser um modelo cutaway, garante fácil acesso às notas mais agudas da escala com bastante conforto. Ideal para ser utilizado nos estudos de violão independente do estilo, para animar roda de amigos e em apresentações musicais, seja solo ou em conjunto. Um instrumento elétrico de cordas D''addario, madeiras e acabamentos de alta qualidade, é um ótimo investimento para estudantes. Seus violões estão crescendo cada vez mais, possuindo um som amplo, bem encorpado e com características únicas, principalmente para os amantes de músicas Folk, Rock, Sertaneja e similares. A Hofma é a marca de referência no mercado de instrumentos musicais no Brasil. Características: - Marca: Hofma - Modelo: HMF 240 - Cor: Vermelho Satin - Acabamento: Acetinado - Marcação: Diamond - Tampo / Fundo: Sapele - Laterais: Sapele - Braço: Mogno Oriental - Escala e Cavalete:: Jacarandá - Trastes: 22 em Alpaca - Tarraxas: Die-cast Cromadas - Cordas: D''Addario Leve - Sistema de captação: Piezo - Equalizador: Hofma AUDISYS', 1255.45, 1255.45, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rd60-lvq3rk5a24pz4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22693072264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
