INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19798186246', 'Océane Edition The Lipstick Red Kiss Vermelho - Mini Batom 2g', 'Océane Edition The Lipstick Red Kiss Vermelho - Mini Batom 2g Na cor Red Kiss, esse batom vermelho intenso combina perfeitamente com visuais mais ousados e personalidade forte. Enriquecido com óleo de oliva, vitamina e e lecitina de soja, que conferem textura e maciez ao seu batom. Possui pigmentação poderosa e duradoura, com cobertura semi-matte, super confortável. Conselho de Aplicação Aplique diretamente nos lábios.', 79.95, 47.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rau2-ma46wbzqj2emae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F19798186246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698188246', 'Kit K.Pro S.O.S. Summer Shampoo e Máscara (2 produtos)', 'Kit K.Pro S.O.S. Summer Shampoo e Máscara (2 produtos) Esse Kit Contém K.Pro S.O.S. Summer - Shampoo sem Sulfato 240ml: sem sal e sem sulfato para cabelos expostos ao sol, mar e cloro, com ou sem química. limpa suavemente e ajuda a manter os fios saudáveis e macios. Ainda protege os cabelos sensibilizados e ressecados. K.Pro S.O.S. Summer - Máscara de Reconstrução 165g: para cabelos expostos ao sol, mar e cloro. Hidrata e protege os fios, evitando o ressecamento. ajuda na reconstrução fios danificados e proporciona maciez e brilho. Com alta concentração de Queratina Hidrolisada a Catiônica, para reconstrução interna e externa dos fios. Os Extratos de Pérola e Seda proporcionam maciez e brilho, devido ao seu poder de hidratação. O pH ácido (3,5 - 4,5) sela as cutículas e protege a cor dos fios. Conselho de Aplicação Shampoo: aplique sobre os fios molhados, massageando até fazer espuma. Enxague em seguida. Condicionador: aplique mecha por mecha nos cabelos úmidos e limpos. Massageie e penteie com um pente de dentes largos para distribuir melhor o produto. Deixe agir de 3 a 5 minutos e enxague completamente.', 245.25, 245.25, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7raua-macw93zson4376', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F19698188246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
