INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799451598', 'MINIATURA WHISKY CHIVAS 12A 50ML KIT 2 UNIDADES', 'Miniatura De Whisky Chivas Regal 12 Anos. O Chivas Regal 12 anos é uma combinação de diferentes tipos de maltes e grãos, todos maturados por no mínimo 12 anos. Essa combinação rica e suave consegue equilibrar estilo com conteúdo e tradição com um toque moderno. Seu sabor multifacetado revela um aroma de maçã e de frutas, seguido do adocicado do mel, notas de baunilha, amêndoas e uma suavidade que perdura no paladar. Pode ser consumido puro ou em drinks. O Chivas Regal é reconhecido mundialmente como o melhor dos premium blended scoth whiskies, constituindo-se em um padrão de excelência para todos os destilados. Com seu aroma complexo, mas ainda suave, e seu sabor esfumaçado, balanceado por sua qualidade harmonizada, Chivas Regal é o predileto entre os apreciadores de whisky, vendendo aproximadamente 03 milhões de caixas por ano. Miniatura legítima de vidro direto do fabricante com lacre de inviolabilidade, garantia de origem, procedência e qualidade. Garrafa de Vidro. Graduação 40%. Contém 50ml. Whisky Importado da Escócia. Obs: Produto Proibido Para Menores De 18 Anos! Conteúdo Embalagem: 1x Miniatura De Whisky Chivas Regal 12 Anos.', 46.66, 29.98, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134201-820lh-mqxzo3khtyboaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22799451598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
