INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194664360', 'Caixa de Som Philco Extreme PBS35 BT Flash Light', 'Leve o som para onde quiser com a Philco Extreme PBS35! Com conexão Bluetooth, entrada USB, cartão SD e auxiliar P2, você reproduz suas músicas de diversas formas. Seu design moderno conta com iluminação Flash Light que cria um show de luzes vibrante, ideal para festas e momentos de lazer.A bateria recarregável garante horas de reprodução contínua, enquanto a potência do som proporciona graves marcantes e alta qualidade de áudio. Compacta e portátil, é perfeita para qualquer ambiente. Destaques: Bluetooth, USB, Cartão SD e Auxiliar P2 Flash Light com efeitos de iluminação Bateria recarregável de longa duração Som potente e equilibrado Design moderno e portátil', 249.0, 199.0, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-821fz-mgpjdubqvklp6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509845472%2F23194664360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17760505830', 'A Isca De Satanás - Devocional', 'Escape da armadilha mortal do inimigo. A Isca De Satanás expõe um dos laços mais enganosos que satanás utiliza para tirar os crentes da vontade de Deus – a ofensa. A maioria das pessoas que é presa pela isca de satanás nem sequer percebe isso. Não se deixe enganar! A ofensa o alcançará, mas a forma como ela afetará o seu relacionamento com Deus depende de você. A sua reação determinará o seu futuro. Se a ofensa for tratada da forma correta, você se tornará mais forte em vez de se tornar uma pessoa amarga. O Devocional complementa o livro, oferecendo um material de estudo e reflexão para seus momentops devocionais com Deus. Este guia de estudos devocional o ajudará a mergulhar mais fundo nas verdades biblicas relacionadas ao livro, capacitando-o a resistir a receber uma ofensa e a se arrepender e se libertar das ofensas que possam ter afetado sua vida no passado. Queremos ajudá-lo a descobrir o plano de Deus para lidar com as ofensas!', 54.46, 54.46, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdp09v0me1g1f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F17760505830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997022337', 'Cilindro Mestre Freio Ford Escort 1992 a 1994 - 1102168 - C2038', 'Cilindro Mestre Freio Ford Escort 1992 a 1994 1102168 C2038 1.8 8V (DUPLO) SEM RESERVATÓRIO (15/16" OU 23,81mm - SISTEMA VARGA) Inicia Hidráulica do Freio, introduzindo e controlando o processo de frenagem. Injetando e comprimindo o óleo (fluído), gerando a pressão p/todo o sistema de freios. Cilindro Mestre Simples - A tampa do reservatório possui um respiro responsável por igualar as pressões internas, evita a formação de vácuo no caso do fluído de freio baixar. Cilindro Mestre Duplo - É a união de dois cilindros simples, esse conj. foi dirigido para dois circuitos de freio, podendo ser montado em paralelo ou diagonal.', 225.28, 225.28, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbnb-lmrje88rxkwz3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22997022337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
