INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794072919', 'Desodorante Adidas Masculino Aerossol Antitranspirante Power Booster 150ml', '#html-body [data-pb-style=X33QLPF]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O desodorante aerossol Adidas Power Booster masculino oferece máxima proteção durante situações intensas. Sua fórmula vegana, sem álcool e sem silicone respeita o pH da pele e tem ação ultrasseca, além de possuir a exclusiva tecnologia Smart Body Response, que responde às necessidades do corpo ativada pelo calor, protegendo você por 72 horas, mesmo em altas temperaturas. Modo de Uso:Agite antes de usar. Aplique a uma distância de 15cm das axilas. Espere secar antes de se vestir.', 19.37, 19.37, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rav1-maojk9h3c6ira0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23794072919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992822366', 'Clareador Natural Biondina Plus 140Ml', 'Pensando em cabelos claros e sem química, a Anaconda Cosméticos têm uma fórmula de sucesso presente no mercado. A linha Biondina clareia os fios e acentua a cor do loiro, deixando as madeixas com mais brilho. O produto é natural e não agride os fios. O extrato de camomila contribui no clareamento dos fios. Para um efeito mais duradouro, o ideal é usar a linha completa da Biondina, o spray, shampoo, condicionador e creme. Modo de uso : É só lavar os cabelos com o shampoo da linha Biondina e logo após aplicar o condicionador. Aplique o creme e penteie os cabelos, após esse passo borrife a Biondina Líquida nos fios e seque diretamente no sol ou utilize o secador.', 70.47, 70.47, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcdh-lr62wv57pxvlc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23992822366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899075153', 'Henna Pó Surya Castanho', 'AHenna Pó Surya Brasil 50gr é uma coloração semi-permanente com 100% de ingredientes naturais e vegetais, extraídos de plantas e ervas secas originárias da Índia, que colorem, restauram, nutrem e tratam os fios além de cobrirem os fios brancos. Surya Henna Pó não é uma coloração permanente. Sai gradativamente à medida que os cabelos são lavados, sem manchá-los. Pode ser utilizada também em cabelos com tinturas e outros procedimentos químicos como, por exemplo: Alisamento, relaxamento, escova progressiva, escova definitiva, luzes, entre outros. Modo de uso: Adicionar a Henna Pó em 140ml de Água, dissolver o produto e aplicar nos cabelos limpos. Não contém: Amônia, Metais Pesados, Parabenos, Conservantes, PPD, Óleo Mineral, EDTA, Resorcinol, Cloreto de Sódio, Perborato de Sódio (Oxidante), Peróxido de Hidrogênio (Água Oxigenada) e Fragrância Sintética. Produto não testado em animais. Sem ingredientes de origem animal. Produto Hipoalergênico e Dermatologicamente testado. Atenção:Henna não é Henê! Henê é alisamento com química agressiva. Henna Pó é uma coloração semi-permante com propriedades de tratamento cosmético capilar. #html-body [data-pb-style="646BA646BAFCF"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA646BAFE3"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 50.84, 50.84, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-lp6i2mfpjdt1ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19899075153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22896995778', 'Escova De Cabelo Belliz Wood Retangular Com Cerdas De Madeira', 'Escova de madeira Belliz com base almofadada que permitem mais conforto na escovação e pinos de madeira que são antiestáticos e evitam o frizz no cabelo, além de possuirem as pontas com bolinhas que massageiam o couro cabeludo. Indicada para pentear e desembaraçar e todos os tipos de cabelo. Modo de uso: Separe o cabelo por mechas e passe suavemente as cerdas pelo cabelo. #html-body [data-pb-style="646BA64FC5D50"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64FC5D65"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 53.5, 53.5, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbkk-lmgimas0s0uxaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22896995778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798994770', 'Leite Colônia Tempo De Amar 100ml', 'A Loção de Limpeza Leite de Colônia Tempo de Amar 100ml foi desenvolvida para auxiliar na limpeza profunda da pele, mantendo-a protegida contra agressões externas. Possui ação adstringente, que ajuda no controle da oleosidade e fecha os poros temporariamente. Modo de Uso: Pode ser usado para retirar maquiagem. Não aplique na aréa dos olhos, mucosas ou partes íntimas.', 17.48, 17.48, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rbk9-lmhz2qzs40f7dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21798994770', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
