INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297686383', 'Capa de Máquina de Lavar Plast-Leo Flanelada Lisa Grande - Item Sortido', 'A Capa de Máquina de Lavar Plast-Leoé ideal para proteger o seu eletrodoméstico contra poeira, arranhões e respingos de água. Flanelada em sua parte interna para não haver quaisquer danos ao aparelho, como riscos, a capa é produzida em 100% polietileno acoplada a manta 100% poliéster, impermeável e fácil de limpar. O tamanho G tem dimensões aproximadas de 69x66x91cm (LxPxA). Este tamanho de capa para máquina de lavar é compatível para os modelos:-Consul 8kg-Electrolux Turbo Limpeza LT 12kg-Electrolux Turbo Rápido 12kg-Electrolux Turbo Secagem 12kg-GE 10kgGE Digital Luxo 11kg-GE Digital Maxxi 11kg-GE Digital Quente 12kg-GE King Capacity-GE Super Fria 12kgComo aumentar a vida útil do eletro com a capa para máquina de lavarA Capa de Máquina de Lavar Plast-Leo é perfeita para garantir a vida útil do seu equipamento, visto que protege contra poeira e respingos de água que poderiam causar ferrugem. Outras dicas que podem contribuir para a manutenção da sua máquina são a limpeza correta do equipamento (confira no manual de instruções), deixar o eletrodoméstico em um local arejado e utilizá-lo corretamente.', 59.99, 59.99, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-8259o-mqqqswa5wxse8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F19297686383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
