INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28127624973', 'Kit 6 Cuecas Boxer Reebok Masculina Original Lisa Microfibra', 'As cuecas boxer masculinas Reebok Classic são uma ótima opção para homens que procuram boa qualidade. Cintura em elástico reforçado com logotipo da Reebok. Modelagem Boxer com formato anatômico que proporciona total aderência, e se adapta perfeitamente ao corpo. Produto original Reebok. Uma cueca masculina perfeita, que conta com as tecnologias premium Reebok, porém em um modelo clássico. O material com mistura de poliéster é macio, leve e respirável. Possui um ajuste confortável, evitando que as pernas subam e sejam desconfortáveis. Cintura elástica não dobra ou enrola e permanece no lugar, oferecendo conforto extra com design sem etiqueta. A Cueca Box Reebok são fáceis de cuidar. São feitas de material durável de mistura de poliéster e elastano. Tecido respirável com tecnologia de absorção conveniente manterá você seco e fresco durante todo o seu treino e tempo na academia. Guia de Tamanhos: P - Serve 38 M - Serve 40 G - Serve 42/44 GG - Serve 46/48 Composição: 93,89% Poliéster 6,11% Elastano Marca: Reebok Idade: Adultos Gênero: Masculino Tecido: Microfibra Tipo: Boxer Cor: Sortido O Kit é enviado de forma sortida, podendo haver repetição de cores. SOBRE A REEBOK: A Reebok oferece vestuário premium a preços acessíveis. A renomada marca Reebok destaca-se como uma das líderes indiscutíveis no universo esportivo e de moda. Com um legado marcado por inovação e estilo vanguardista, a Reebok assegurou seu lugar de destaque na indústria de calçados e vestuário esportivo. Desde sua fundação em 1958, a Reebok assumiu a vanguarda na produção de tênis de corrida e, ao longo dos anos, expandiu sua linha de produtos para abranger uma vasta seleção, chegando a moda íntima como cuecas e meias, além de incluir roupas fitness até acessórios como mochilas e bonés. Tem alguma dúvida? Nos faça uma pergunta!', 119.9, 69.99, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6ppwq7siog783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F28127624973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
