INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40619079421', 'Bicicleta De Equilíbrio Infantil Andador Sem Pedal 4 Rodas Aprender a Andar Azul Rosa Vermelho Bebê Presente Bike', 'Este anúncio contém: 1 Bicicleta Equilíbrio Infantil Sem Pedal 4 Rodas. Disponível em 3 cores: Rosa, Azul e Vermelho SELECIONE A COR NA HORA DA COMPRA! Bicicleta de Equilíbrio para Bebês – Diversão e Desenvolvimento desde o 1º Ano! Indicada para crianças de 1 a 3 anos, essa bicicleta sem pedais estimula o equilíbrio, a coordenação e a autonomia de forma segura e divertida. Possui assento ergonômico, guidão adaptado para mãos pequenas e rodas largas que garantem estabilidade. Seu design com base plana facilita o movimento natural da criança. Fabricada com materiais duráveis e bordas arredondadas, é o presente ideal para o primeiro ano de vida! Características do produto: Marca: Kparts Importadora Material da Estrutura: Metal resistente com pintura automotiva Assento: Anatômico, com acabamento acolchoado e altura fixa Rodas:4 rodas (duas frontais e duas traseiras) para maior estabilidade, Rodas largas em material EVA ou PVC, com centro em plástico reforçado Guidão: Limitador de giro para maior segurança Empunhadura com acabamento emborrachado antiderrapante Idade Recomendada: A partir de 1 ano até 3 anos Peso Suportado: Até 20 kg. Dimensões aproximadas: Altura: 33,5 cm Profundidade: 48,1 cm Largura: 20,5 cm Peso: 1,15kg Dimensões da embalagem: Largura: 15,3 cm Altura: 20,5 cm Comprimento: 50,3 cm Peso: 1,30kg Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, com garantia de 3 meses. 2 - Produto a pronta entrega. 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 159.9, 79.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-824hl-meomtued12iped', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F762383390%2F40619079421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693689356', 'Faca Cutelo 6.7" Inox Coleção Isa Scherer Prata Mimo Style', 'Descrição do Produto Eleve a experiência gastronômica com a Faca Cutelo 6.7" da Coleção Isa Scherer. Inspirada na prestigiada chef vencedora do MasterChef 2021 e destaque na categoria gastronomia da lista “Forbes Under 30", a linha desenvolvida em colaboração com a Mimo Style oferece qualidade gourmet e uma excelente experiência culinária. A Faca Cutelo é produzida com uma lâmina em Aço Inox resistente à corrosão, prolongando as características originais, enquanto o cabo é de madeira Pakka, oferecendo um visual elegante e proporcionando um manuseio confortável e seguro, permitindo um excelente controle durante o corte de diferentes tipos de carnes e ossos. Especificações: Marca: Mimo Style Material: Madeira Pakka e Aço Inox Dimensões: — Lâmina: (C) 18 cm x (L) 2,5 mm — Cabo: (C) 31,5 cm x (L) 5 cm x (A) 2 cm Peso: 250 g', 148.21, 123.02, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5ug25n66lj9c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1368997878%2F22693689356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
