INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22133798587', 'Ventosa Dulpa Para Vidro Mármore Chapas Piso Cerâmica 90kg Fertak 9012', 'Ventosa Dulpa P/ Vidro, Mármore E Chapas 90kg Fertak Se você está procurando por uma maneira segura de fixar objetos em qualquer superfície, então a Ventosa Dupla da Fertak é a solução para você! Esta solução versátil e moderna oferece suporte a objetos de até 90kg, proporcionando segurança e resistência. A Ventosa Dupla da Fertak é a escolha ideal para quem precisa de uma fixação robusta e duradoura. É fácil de instalar, e a sua vedação estável garante que os objetos se mantenham firmes e seguros. A Ventosa Dupla da Fertak é a solução ideal para quem busca resistência, segurança e fixação duradoura. Por isso, escolha a Fertak e não se arrependa! Benefícios: > Indicada para elevar e transportar peças planas com superfície lisa, como: - Vidros; - Espelhos; - Cerâmicas; Características Técnicas: > Material: Plástico (ABS) e Borracha; > Apoio de Ação: Duplo; > Tempo máximo de fixação da ventosa na peça: 15 minutos; > Sucção: Borracha; > Capacidade de Aspiração Vertical: 90kg; > Aplicação: Vidro, Mármore e Chapas; > Dimensões da Ventosa: 31,8cm x 12,4cm x 9,4cm; > Peso Bruto: 490g; - Marca: Fertak - Garantia: 90 dias contra defeito de fabricação. Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica. - Produto novo, com garantia de fábrica. - Produto a pronta entrega. - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 45.9, 44.95, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-loybxyovhxsl29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22133798587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097696904', 'Cortador Ralador Triturador Manual Multifuncional Para Legumes Vegetais 13 Peças Plástico E Aço', 'Ralador E Fatiador Multifuncional Kala Conheça o Ralador E Fatiador Multifuncional da Kala, o utensílio que vai transformar sua experiência na cozinha! Com design inteligente e lâminas afiadas, ele permite que você rale e fatie com rapidez e precisão, tornando o preparo das suas receitas muito mais eficiente. É equipado com várias lâminas diferentes, além de uma variedade de outros utensílios que irão atender todas as suas necessidades culinárias. Características: > Produzido em aço inox e plástico ABS; > Ideal para fatiar, cortar e triturar verduras, legumes e frutas em geral; > O ralador acompanha: - 1 moedor de alho; - 1 prato de pressão; - 1 protetor para as mãos; - 1 escorredor de alimentos; - base cortadora anatômica; - 1 lâmina de corte ondulada; - 1 separador de clara e gema; - 1 lâmina de corte raladora fina; - 1 lâmina de corte raladora grossa; - 1 lâmina de corte (fatias) em inox 2mm; - 1 lâmina de corte em inox (picador) 6x6m; - 1 lâmina de corte (picador) em inox 12x12mm; - 1 escovinha de limpeza para o prato de pressão; - 1 recipiente em acrílico com base antiderrapante. - Marca: Kala - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 152.11, 117.92, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-lyfko349gab0ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22097696904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897845628', 'Kit Para Pintura Multiuso Antirrespingo Econômico Com Rolo + Bandeja Plástica Resistente Tigre', 'Kit Econômico Antirrespingo 3 Peças Tigre O Kit Econômico Antirrespingo 3 Peças da Tigre é a solução ideal para quem busca eficiência em trabalhos de pintura. Composto por uma bandeja e um rolo de pintura de alta qualidade, minimiza respingos e garante uma aplicação uniforme da tinta. Perfeito para reformas e outros projetos, é a escolha ideal para quem deseja resultados profissionais sem gastar muito. Características: > Ideal para qualquer tipo de superfícies; > O suporte é composto por aço galvanizado; > A bandeja é ideal para todos os tipos de tinta e é resistente a solvente; > O rolo antirrespingo é ideal para tinta látex e acrílica, em superfícies como paredes lisas e teto. Especificações Técnicas: > Material: plástico; > O kit acompanha: - 1 bandeja; - 1 rolo antirrespingo. - Marca: Tigre - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 35.75, 29.17, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-m0m236hfg8hq94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22897845628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499358204', 'Fita Veda Fresta 3M SCOTCH 19MM X 5M', 'Fácil de aplicar Fabricada com espuma flexível de PVC e adesivo com alto poder de adesão 19 mm de largura e 5 mm de espessura A Fita Veda Fresta é o produto ideal para vedar a passagem de ar, gás e umidade, diminuindo ruídos indesejáveis e amortecendo choques e vibrações. Fácil de aplicar, ela é especialmente indicada para janelas, portas, salas acústicas e dutos de ar-condicionado. A Fita Veda Fresta é o produto ideal para vedação de ar, gás e umidade, diminuindo ruídos indesejáveis e amortecendo choques e vibrações. Fácil de aplicar, ela é especialmente indicada para janelas, portas, salas acústicas e dutos de ar-condicionado. Fabricada com espuma flexível de PVC de densidade média e adesivo com alto poder de adesão, a Fita Veda Fresta possui 19 mm de largura e 2 mm de espessura. Para utilizar o produto, a superfície deve estar limpa, seca e isenta de gorduras. Corte a fita no tamanho desejado e remova a proteção de papel. Depois, aplique, pressionando a parte com adesivo na superfície. Aplicações sugeridas Ideal para vedação de ar, gás e umidade, diminuindo ruídos indesejáveis e amortecendo choques e vibrações Especialmente indicada para janelas, portas, salas acústicas e dutos de ar-condicionado', 76.9, 76.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-lyy2i30eq0fefa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F21499358204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
