INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7186345263', 'Borracha De Porta Tipo Original Fiesta Sedan 2002 Até 2013', 'Detalhes do Produto: Borracha De Porta Tipo Original Fiesta Hatch e Sedan 2002 Até 2013 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Fiesta Hatch e Sedan 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha de porta (02 anos de garantia)', 98.02, 98.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/165c863c177e1453c886cdefdf90d178', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F7186345263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899149469', 'Interruptor Cebolinha Óleo Gol Parati Saveiro Original Vw', '0309190811 Interruptor Cebolinha Óleo Gol Parati Saveiro Original Vw. LOJA OFICIAL VOLKSWAGEN CONCESSIONÁRIA LUSON Escolha sempre Peças Originais Volkswagen e garanta o melhor desempenho do seu veículo. Somos uma concessionária Volkswagen, aqui você encontra total garantia de qualidade e procedência. Nossos produtos são novos, originais e possuem garantia de 90 dias após a emissão da Nota Fiscal. Antes de efetuar a compra, deve ser informado no campo de perguntas, o número completo do chassi do veículo ou a placa, para consultarmos no catálogo de peças originais Volkswagen a aplicação correta da peça, e assim evitar o envio de peças não compatíveis com o veículo. HORÁRIO DE ATENDIMENTO De segunda à sexta-feira das 8h às 18 horas. Sábado das 8h às 12h. NEGÓCIO BOM, É NA LUSON! Aguardamos a sua compra.', 46.77, 46.77, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rdye-mbwb2007v3ed75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632974116%2F23899149469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8036135422', 'Kit 4 Borrachas De Porta Lateral Fiesta 2009 2010 2011 2012', 'As Borrachas RINOFLEX tem as Qualidades deste fantástico animal que é o Rinoceronte. Agilidade na entrega e atende diversas aplicações de veículos e a grandeza de uma marca são características essenciais para um produto de Sucesso. ---------------------------- -Ágil -Múltiplas Aplicações -Marca Forte -Atende mais de 90% dos Carros! ---------------------------- Código do produto: Comprimento: 4 Metros Marca: RINOFLEX -Com Aba ---------------------------- Principais Aplicações: -FrdFiesta 02/12 -Ka 13/ -Fusion -Peugeot 206/207/208 -Renault Megane/Scenic/Clio/Laguna -Citroën Berlingo/Xsara/Xsara Picasso -Hafei Towner Junior', 369.9, 369.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/798c71aadd23a436b74c4207257814ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F8036135422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699160401', 'Jogo Juntas + Retentores Motor Titan 125 Fan 125 2003-2008', 'Jogo De Juntas Cg 125 Titan 2003/08 Completo Com Retentor SERVE SOMENTE NA TITAN 125 ANO 2003 ATE FAN 125 2008 RETENTOR PINHAO RETENTOR CAMBIO RETENTOR EMBREAGEM RETENTOR VALVULA RETENTOR PARTIDA GUARNICAO TAMPA VALVULA MARCAS, VEDAMOTOS E TRILHA', 77.9, 77.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-821gf-mgsa3x4gkhzj67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1410324431%2F23699160401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398854544', 'Aditivo Limpeza Rapida Valvulas Admissao Intake Stp 200ml', 'O Intake Valve Cleaner STP 236ml é um aditivo especialmente desenvolvido para motores FLEX. Ele atua na limpeza do sistema de injeção, restaurando a potência do motor e reduzindo o consumo de combustível.Benefícios:- Redução do consumo de combustível e emissão de gases poluentes: Mantém o motor mais eficiente, resultando em menor consumo de combustível e emissões reduzidas.- Manutenção da limpeza do sistema: Forma uma película protetora nas válvulas de admissão, prevenindo a formação de depósitos prejudiciais.- Restauração da potência e melhoria da aceleração: Contribui para um desempenho mais suave e potente.- Proteção contra oxidação e corrosão: Preserva as partes metálicas do sistema de injeção.- Tratamento super concentrado: Eficaz na limpeza dos bicos injetores e do sistema de injeção de combustível.- Eliminação de falhas na partida: Minimiza problemas causados por mau funcionamento dos injetores.- Indicação para motores a gasolina: Recomendado apenas para motores movidos a gasolina.Modo de usar:- Despeje todo o conteúdo do frasco no tanque de combustível.- Um frasco trata até 50 litros de combustível.- Se necessário, repita a operação.- Não prejudica catalisadores nem sondas lambda.O Intake Valve Cleaner STP é uma excelente escolha para manter seu motor limpo e funcionando com eficiência.', 42.9, 42.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-820l4-mptdiv0e5ate84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1464009232%2F22398854544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698961852', 'Bíblia 3 Palavrinhas MINI | Ilustrada | Capa Dura', 'A Bíblia 3 Palavrinhas Mini é uma obra inspiradora que oferece uma abordagem acessível e envolvente para compartilhar as mensagens atemporais e a sabedoria contida nas Escrituras com as crianças.Esta versão condensada e cativante da Bíblia é cuidadosamente projetada com ilustrações coloridas e texto adaptado para tornar as histórias bíblicas compreensíveis para os pequenos leitores.O principal objetivo da Bíblia 3 Palavrinhas Mini é introduzir as crianças ao mundo da fé de uma forma única, facilitando a leitura e compreensão das histórias bíblicas.Algumas características notáveis desta Bíblia incluem um texto adaptado especificamente para crianças, ilustrações envolventes que prendem a atenção e a praticidade de ser uma opção perfeita para levar em viagens, usar em cultos religiosos e compartilhar momentos de devoção em família.É uma maneira maravilhosa de transmitir valores e ensinamentos bíblicos às novas gerações, contribuindo para o enriquecimento espiritual das crianças. 20x17cm 215 Páginas', 65.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7r99b-lloc9x8hdvk348', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20698961852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897908916', 'Cooktop Itatiaia Electra Plus 4 Bocas Mesa Vidro Temperado Acendimento Superautomático Preto Bivolt', 'Cooktop Itatiaia Electra 4 Bocas Com Mesa de Vidro Temperado e Acendimento Superautomático Preto Bivolt Quando se trata de desempenho, o Cooktop Itatiaia Electra não decepciona. Com quatro queimadores potentes, você terá o poder necessário para cozinhar de forma rápida e eficiente. Com uma potência total da mesa de 8,25 kW, seja utilizando gás GLP ou GN, você terá uma chama potente que irá acelerar o processo de cozimento dos seus pratos favoritos. O controle integrado na mesa proporciona praticidade e facilidade no manuseio, permitindo que você ajuste a chama com precisão. Além disso, o Cooktop Itatiaia Electra foi projetado com materiais de alta qualidade. O vidro temperado de 6mm confere durabilidade e resistência, enquanto o acabamento esmaltado brilhante na capa do queimador e o acabamento polido brilhante na câmara do queimador garantem um visual luxuoso e fácil limpeza. O Cooktop Itatiaia Electra 4 Bocas Preto é a escolha perfeita para quem busca qualidade, beleza e funcionalidade na cozinha CARACTERÍSTICAS: - Cor: Preto - Tensão: Bivolt - Tipo de gás: GLP/GN - Quantidade de Queimadores: 4 - Potência total da mesa: GLP/GN (kW): 8,25 - Classe de isolação: 1 - Pressão de gás GLP (kPa): 2,75 - Pressão de gás GN (kPa): 1,96 - Controle integrado na mesa: Sim - Grafismo na mesa: Sim - Tipo do grafismo: Duas cores: mesa preto com escrita cinza claro - Acabamento capa queimador: Esmaltado Brilhante - Acabamento câmara queimador: Polido Brilhante - Material: Vidro Temperado 6mm - Manípulos: "Injetado na cor preto, texturizado com polimento no chanfro lateral" - Trempes: Individuais - Material da trempe: Arame Redondo / Chapa de Aço - Classificação energética: A - Acendimento: Superautomático Dimensões do produto: (A) 15,8 X (L) 56,5 X (P) 45 Peso: 6,7 - Garantia: 12 meses', 699.9, 429.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhklo99mb11fb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F23897908916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43127239148', 'Scottini Cruzadas | N. 2193 | Médio', 'Os Caça-palavras contêm assuntos diversos relacionados à Cultura, Tecnologia, Ciência e Arte. As questões exercitam o cérebro, abordando temas da atualidade e do passado. Isso faz com que nosso córtex trabalhe toda a área da memória. Essa dinâmica de construção traz benefícios de longo prazo, contribuindo para o rejuvenescimento do cérebro. 21x14 cm 32 Páginas', 8.9, 3.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822wq-mi9lvfus3j7l3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F43127239148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693247703', 'Aparador Kappesberg 4 Portas Canela 156cm', 'Transforme sua sala de estar com a beleza e a qualidade do Aparador 4 portas R262 da Kappesberg. Com um design clássico, ele se encaixa perfeitamente em todos os espaço. São 74cm de altura, 1,56m de largura e 45cm de profundidade, produzido com estrutura em MDP de 15mm e portas MDF de 18mm, o que garante mais robustez, firmeza e qualidade ao seu produto, além de um acabamento lindo. E com sete camadas de pintura, tanto na parte interna quanto na externa, e sua pintura touch na cor canela, com a textura dos veios da madeira, é perfeita para quem busca por um ambiente clássico e aconchegante. Remetendo aos tons da natureza, você terá o espaço ideal para receber sua família e amigos com conforto e beleza. Com quatro portas, e quatro prateleiras, você terá amplo espaço para guardar seus itens com praticidade, deixando sua sala de estar sempre organizada. A base e os pés completam o design e a qualidade do produto, garantindo seu acabamento clássico e rústico. Nas portas, o destaque fica para o sistema de amortecimento, garantindo um fechamento suave e sem ruídos, além de mais durabilidade, e o puxador cava embutido proporciona o toque de beleza que faltava, deixando sua sala de estar perfeita. Medidas: • 52,5 cm de altura • 156 cm de largura • 42 cm de profundidade Itens inclusos: • Três (3) portas tradicionais (portas de bater) • Duas (2) divisórias • Duas (2) prateleiras • Pés em MDP de 25mm Código do produto: R262-CN Informações importantes: • As imagens são ilustrativas. • A Kappesberg não disponibiliza serviço de montagem (recomendamos a contratação de um profissional qualificado). • O manual de montagem acompanha o produto. • 3 meses de garantia para defeitos de fabricação.', 1049.04, 629.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820m8-mpcix9rj8d8h51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F23693247703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693511240', '28 Tubo Ressonância Lax Vox Exercício Vocal Silicone 35 Cm', '28 TUBOS DE RESSONÂNCIA SILICONE - PROMOCIONAL ESTOQUE LIMITADO APROVEITE!!! CORES VARIADAS CONFORME DISPONIBILIDADE DE ESTOQUE!!! TUBOS DE RESSONANCIA PARA EXERCICIOS LAX VOX (SILICONE) Dimensões 13,00 X 09,00 X 350,00 mm Descrição: O Tubo de Ressonância Lax Vox é um método simples e eficaz para terapia e treinamento da voz, contra sobrecarga e rouquidão. O procedimento de Lax Vox ou também conhecido como Voz Livre, não é agressivo, é direto, holístico e cognitivo, sendo usado para aquecimento vocal, para relaxamento após os exercícios vocais, diagnóstico para músicos, cantores, atores e professores. Indicado para tratamento de eventuais distúrbios funcionais e orgânicos da voz, dentre elas as disfônicas funcionais. - Aumento da propriocepção vocal - Menor esforço vocal - Menos fadiga vocal - Maior controle da respiração costodiafragmática - Ajuda no controle da estabilidade da laringe Indicações: -Cantores -Palestrantes -Locutores -Professores de Canto -Preparadores Vocais -Vocal Coach -Fonoaudiólogos, etc. Conteúdo: 28 Tubo La Vox NÃO ACOMPANHA A GARRAFINHA Procure sempre orientações com profissionais adequados.', 355.92, 355.92, NULL, 'Health > Sexual Wellness > Sex Toys', 'https://cf.shopee.com.br/file/sg-11134201-7repm-m28fv9e3jfzq53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1048444153%2F23693511240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55402105608', 'Agente Swateens | Joelson Lemos da Silva', 'O livro Agente SWATeens é um treinamento direto, prático e transformador para quem deseja entender e cuidar da nova geração com sabedoria e propósito. Com linguagem envolvente e recursos estratégicos, este livro é o guia que todo agente da fé precisa para enfrentar os desafios urgentes e emergentes da adolescência. 13x18cm 142 Páginas', 27.9, 22.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8225k-mhi5rkggm2v5c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F55402105608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793841420', 'Estojo Escolar Duplo 0732232', 'Estojo de nylon 0732232 Seu percurso diário para o trabalho requer uma mochila para notebook resistente e segura. Versáteis e equipadas com recursos para proteger seus pertences pessoais, além de propiciar uma perfeita organização interna, as mochilas para notebook Republic.Vix By Chenson são perfeitas para qualquer profissional, estudante ou viajante. A nova linha de mochilas para notebook foi criada com base nos seguintes valores: Ø Designer moderno e arrojado; Ø Tecido de alta qualidade com substrato impermeável, à prova de umidade e fácil de limpar; Ø Zíperes de alta qualidade, correias, fivelas e outros acessórios funcionais, fortes e duráveis; Ø Bolsos duplos, que podem proteger e guardar telefones celulares e carregadores portáteis, passagem para fone de ouvido ou cabo de alimentação de energia; Ø Cada ponto da peça que exige maior tenção, foi estrategicamente reforçada com linhas de alta densidade utilizada na confecção de cinta para amarração de cargas (linha vermelha visível na peça), que é firme, forte e durável; Ø Alças e costas almofadas ergonômica para maior conforto e protegem o corpo; Tactel Fechamento em Ziper 2 Bolsos Amplos Medidas Aproximadas 10 Altura 24 Largura 8 Comprimento Polegadas Volume Informações Adicionais Tamanho: Único Modelo: Estojo Escolar Duplo 0732232 Material:Tactel Marca: Republic.Vix By Chenson CUIDADOS: -Guarde em um local seco e arejado evitando locais úmidos. - Evite colocar excesso de peso no produto para não forçar os zíperes e costuras. - Proteja os objetos cortantes e/ou pontiagudos evitando o contato direto com o produto. - Evitar altas temperaturas. DICAS DE LIMPEZA: - Para a limpeza utilize apenas pano úmido com sabão neutro. - Não mergulhar na água e não utilizar componentes químicos, solventes ou alvejantes. - Não deixar de molho e secar a sombra.', 86.4, 86.4, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-7rd5s-m7mp26dfitgnd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F22793841420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897633547', 'Ventilador de Coluna Britânia Turbo Silencioso 160W BVT466', 'Calor não será um problema com o Ventilador de Coluna Britânia Turbo Silencioso 160W BVT466! Para que você tenha um melhor conforto térmico, a Britânia desenvolveu o BVT466 Maxx Force, com uma hélice de 6 pás com 40 cm que garante um altíssimo poder de ventilação. O ventilador de coluna Britânia BVT466, é muito flexível! Possui 3 opções de uso: ventilador de parede, mesa ou coluna. Já o sistema com ajuste da inclinação vertical e da oscilação horizontal automática e coluna telescópica com altura ajustável em até 42 cm, garante que o ar será melhor distribuído, deixando seu ambiente muito mais fresquinho. Tudo isso com 160W de potência! Não se preocupe com a montagem, desmontagem e limpeza, pois as peças de fácil encaixe e de simples montagem, tornam tudo muito prático e rápido. Supere o calor com estilo, flexibilidade e conforto com o Ventilador de Coluna Britânia Turbo Silencioso 160W BVT466! • 3 velocidades • Hélice com diâmetro de 40 cm e 6 pás • Oscilação horizontal automática • Inclinação vertical regulável • Grade removível - facilita a limpeza • Baixo consumo de energia elétrica • Baixo nível de ruído • Novo sistema de articulação para ajuste da inclinação vertical (sem borboleta).', 269.9, 269.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-823r2-morddkf4wu1756', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F18897633547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893229567', 'Tampo Para Balcão Kappesberg Branco 20cm x 52cm', 'O Tampo para Balcão de Madeira é bonito, resistente e durável. Perfeito para completar a sua Cozinha com muita praticidade, fabricado em MDP com acabamento BP, é fácil de limpar e montar. É a escolha ideal para quem procura o melhor para a sua Cozinha. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); Ferragens não acompanham o tampo; O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 164.59, 129.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rcea-m6cjl1sh9z28e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F23893229567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45107401054', 'Lixeira de Lavabo e Cozinha Inox com Pedal e Cesto Removível 5L - Powermaid', 'Lixo Lixeira Cesto com Pedal 5L - PowerMaid As lixeiras são objetos indispensáveis e muito utilizados em cozinhas, banheiros e áreas de serviço. Pensando nisso, a PowerMaid desenvolveu uma linha de lixeiras que, além de elegantes, são práticas e funcionais. O recipiente externo é feito em aço inox, um material resistente e não poroso, que evita o acúmulo de resíduos e facilita a limpeza. Além disso, o produto possui um balde interno removível em plástico, que pode ser facilmente retirado através de uma alça. O pedal, localizado na parte inferior da lixeira, facilita a abertura e fechamento da peça e a alça exterior simplifica o seu transporte. Dimensões aproximadas: Lixeira 5L – 28cm (A) x (D) 20,5cm Cesto Interno: Largura 19cm x Altura 21cm Características: Marca: PowerMaid Referência: 1.26051.02.1000 Material: Inox Capacidade: 5 Litros Quantidade: 1 peça Cor: Inox Imagens Ilustrativas.', 104.9, 64.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-825zm-mlza8ui1mfb5a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402076848%2F45107401054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499253481', 'O Filho Rico: 11 Lições Para a Riqueza e o Sucesso, por Felipe Miranda e Ricardo Mioto - Intrínseca', 'O Filho Rico: 11 Lições Para a Riqueza e o Sucesso, por Felipe Miranda e Ricardo Mioto - Intrínseca Descrição do Livro: Felipe Miranda, da Empiricus, compartilha lições para uma vida mais rica, bem-sucedida e feliz Felipe Miranda, fundador da Empiricus e sócio do BTG Pactual, tem muito a ensinar sobre crescimento pessoal e financeiro. Filho de uma família empobrecida por uma falência, ele construiu seu percurso na base da tentativa e do erro, acumulando fortuna e experiência ao longo dos últimos quinze anos. Como um presente para os três filhos, nesse livro Felipe buscou responder a uma pergunta: quais princípios guiam as pessoas bem-sucedidas em sua jornada? A partir das próprias histórias e de curiosidades sobre figuras tão diversas quanto George Soros, Mick Jagger, Bernardinho e Buzz Lightyear, o economista compila 11 lições que vão servir como um mapa para conduzir o leitor à satisfação de todo o seu potencial. Escrita ao lado de Ricardo Mioto, essa obra é uma defesa leve e divertida de que o melhor caminho para o sucesso e a riqueza é o desenvolvimento da mentalidade correta. A jornada até uma vida melhor não é linear, e o leitor equipado com as ferramentas oferecidas por esse guia estará muito mais preparado para enriquecer tanto sua conta bancária quanto suas relações pessoais. Sobre o Autor: Felipe Miranda é economista e mestre em finanças. Fundador da Empiricus, é sócio do BTG Pactual, o principal banco de investimentos do país. Ricardo Mioto é jornalista e diretor de comunicação da Empiricus. Foi repórter e editor da Folha de S. Paulo e, como sócio da FSB, consultor de comunicação de clientes multinacionais como McKinsey e Twitter. É autor do livro Breve história bem-humorada do Brasil, publicado pela editora Record. Detalhes do livro: Tradutor: Livro brasileiro Número de Páginas: 208 Gênero: Administração, Negócios e Economia Dimensões do livro: 13,8 x 21 x 1,1 Peso do livro (Kg): 0,26 Tipo de capa: Livro brochura (paperback) Data de lançamento: 19/05/2022 Idioma do livro: Português Traduzido do: Português', 69.9, 69.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luw5e934g6sg9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F21499253481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50306069170', 'Esmerilhadeira Angular Profissional 1100W Motor de Cobre 115mm 4.1/2 Cortador Lixadeira Eletrica Kit Completo Desoon', '🏷️Olá a todos! Esta é a loja DESOON, onde você encontrará uma grande variedade de produtos e estilos! Esperamos que você encontre as ferramentas que melhor atendem às suas necessidades!🏷️ 🪷POTÊNCIA REAL E SEGURANÇA PARA O SEU TRABALHO! Você está cansado de ferramentas que prometem potências absurdas, mas param no primeiro corte? Nossa Esmerilhadeira Angular foi projetada para profissionais que buscam fatos, não apenas números. Com 1100W de potência real, ela entrega a força necessária para cortes precisos e desbastes pesados sem superaquecer. Rotação de 12.000 RPM: Alta velocidade para um acabamento profissional e menor esforço do operador. Construção Robusta: Rolamentos blindados e sistema de ventilação eficiente que prolongam a vida útil do motor, evitando queimas precoces comuns em máquinas "maquiadas". Motor de cobre puro: Possui enrolamentos internos de cobre puro de alta qualidade, proporcionando excelente dissipação de calor e condutividade elétrica. Mesmo sob operação de alta intensidade, o motor mantém um baixo aumento de temperatura, oferecendo uma vida útil prolongada em comparação com os motores padrão. Engrenagens premium: O sistema de transmissão emprega engrenagens de precisão fabricadas com materiais superiores, combinadas com um eixo balanceado de alta precisão que opera a 12.000 rpm. Isso resulta em redução da vibração (minimizando a fadiga das mãos), menor ruído operacional e maior eficiência de transmissão. Design ergonómico: Possui uma proteção de esmerilagem ajustável e reforçada para minimizar eficazmente os respingos de detritos durante a operação. A alça auxiliar ergonomicamente projetada reduz a fadiga durante o uso prolongado, maximizando a segurança operacional. Tensão: 220 V ~ 60 Hz / 127 V ~ 60 Hz Potência: 1100 W Velocidade sem carga: 12000 rpm Tamanho da proteção de esmerilagem: 115 mm Bloqueio do eixo Interruptor LIGADO/DESLIGADO Acessórios: 1 proteção de esmerilagem (ajuste da ferramenta) 1 alça auxiliar 1 chave inglesa Comprimento do cabo: VDE 2 m Código HSCODE: 84672910 📚Obrigado por comprar em nossa loja. Siga-nos para mais promoções atualizadas! 📚Se você tiver algum problema com o produto, entre em contato conosco a tempo! 📚Para devoluções e reembolsos, envie-nos vídeos ou fotos de unboxing para nossa análise. Obrigado novamente por sua compra e desejo a você uma vida feliz!', 400.0, 139.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81zue-mkkd6gucm4g2e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1491062490%2F50306069170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18357830078', 'Prato Quadrado Casual Coza Cozy Preto', 'Seja Bem-Vindo(a) à Mimorada! Apresentamos o Prato Quadrado Pequeno Coza Cozy. A coleção é produzida em diferentes cores e cai muito bem em decorações temáticas, compondo e combinando com o cenário. DIFERENCIAIS: Deixar uma refeição simples mais especial é fácil, basta cuidar dos detalhes como a apresentação e a decoração. Para facilitar a hora de compor a mesa, o prato quadrado pequeno tem design diferenciado e está disponível em cores sóbrias e vibrantes. Prático, o recipiente pode ir ao micro-ondas e à máquina de lavar. MATERIAL: O Prato Quadrado Pequeno Coza Cozy é fabricado em polipropileno de alta qualidade. Tudo isso com o compromisso de sustentabilidade, pois as peças são 100% recicláveis, BPA Free e fabricadas com energia de fontes renováveis. Fabricada em plástico transparente com acabamento brilhoso, possui textura ondulada ao seu redor. DIMENSÕES: As dimensões do Prato Quadrado Pequeno Coza Cozy são de 16 cm de comprimento, 16 cm de largura e 2,5 cm de altura. INSTRUÇÃO DE USO E LIMPEZA: Para limpeza e manutenção, basta utilizar um pano macio e umedecido (ou o lado macio da esponja) com água e sabão neutro. Evite o uso de materiais abrasivos que possam danificar a superfície do produto. INFORMAÇÕES ADICIONAIS: Descubra a versatilidade da Linha Cozy! A Linha conta com uma diversidade de itens para organizar e servir. Essa coleção combina funcionalidade, durabilidade e resistência, sendo a solução ideal para servir e compartilhar bons momentos. A Coza preocupa-se com o meio ambiente e por isso, suas principais fontes de matéria-prima utilizadas na produção dos itens, é 100% reciclável. Fabricados com os mais rigorosos padrões técnicos e de segurança para você e sua família, os produtos são pensados para todas necessidades, oferecendo o que há de mais tecnológico, moderno e elegante para organizar e decorar sua casa. Conheça também os demais produtos da marca Coza para organizar e deixar a sua casa ainda mais bonita, com soluções completas de organização. Eleve o nível no hora de servir com o Prato Quadrado Pequeno Coza Cozy, oferecendo uma combinação única de funcionalidade e durabilidade, tornando-a uma peça essencial para a sua casa.', 13.99, 12.75, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lp9nhz708kg585', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F18357830078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250219322', 'Esteira Ergométrica Elétrica E41 Compacta Motor 1,5HP com Painel LCD Multifunções Sensor Cardíaco Ideal p/Treinos Acte', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: Esteira Elétrica E41 Acte Sports com Painel Multifunções - Acte Conteúdo da Embalagem: - 01 Esteira Elétrica E41 Acte Sports com Painel Multifunções - Acte Transforme seus treinos em casa com a esteira elétrica E41 da Acte Sports. Compacta, resistente e equipada com tecnologias que otimizam sua performance, ela oferece o equilíbrio ideal entre conforto, praticidade e segurança para quem busca qualidade de vida sem sair de casa. O modelo E41 é a solução perfeita para manter a rotina de exercícios eficiente, mesmo em espaços reduzidos. Destaques do Produto: Alta performance com mobilidade e segurança - Painel LCD multifunções: Monitore tempo, velocidade, distância e calorias em tempo real com clareza e praticidade. - Motor potente e silencioso: Com 1,5 HP, atinge velocidades de 1 a 10 km/h, ideal para caminhadas e corridas leves. - Sensor de batimentos cardíacos: Acompanhe sua frequência cardíaca para treinos mais seguros e controlados. - Mobilidade facilitada: Rodas de transporte integradas que garantem fácil deslocamento da esteira. - Design funcional: Com suporte para garrafas, estrutura em aço e acabamento em ABS, combina durabilidade e conforto. Por que escolher a Esteira Elétrica E41 Acte Sports? Se você busca praticidade para se exercitar em casa, a esteira E41 oferece um excelente custo-benefício. Seu design compacto atende perfeitamente quem tem pouco espaço, mas não abre mão de tecnologia, conforto e segurança. É ideal para quem deseja manter a saúde em dia sem depender de academias ou clima favorável para treinos ao ar livre. Ficha Técnica: - Marca: Acte Sports - Modelo: E41 - Tipo: Esteira Ergométrica Elétrica - Medidas: 128 x 113 x 65 cm - Material: Aço, ABS, Ferro e PP - Peso máximo suportado: 120 kg - Garantia: 6 meses contra defeito de fabricação - Painel: LCD multifunções - Velocidade: 1 a 10 km/h - Motor: 1,5 HP - Bivolt - Sensor de batimentos cardíacos - Suporte para garrafa - Rodas de transporte Importante - Garantia de 06 meses; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico. - Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor', 2103.9, 1999.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-821df-mgi4e91mvle23f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F58250219322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42558749565', 'Livro Wuthering Heights W.Books', 'A timeless tale of passion, betrayal, and vengeance, Wuthering Heights by Emily Brontë is a masterpiece that continues to captivate readers with its intense emotions and unforgettable characters. Set against the hauntingly beautiful moors of Yorkshire, the novel unravels the tumultuous love story of Heathcliff and Catherine Earnshaw, a bond so profound that it defies life and death._x000D_ Brontë’s only novel is a bold exploration of human nature, where love intertwines with hatred, and loyalty battles against revenge. With its gothic atmosphere and psychological depth, Wuthering Heights remains one of the greatest works of English literature, offering readers an enduring and transformative experience._x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Emily Bronte_x000D_ Idioma: Inglês_x000D_ Páginas: 368_x000D_ Dimensões: L 12.80 x A 19.70 x E 1.00_x000D_ ISBN: 9786552940483_x000D_ Coleção: Classics Collection_x000D_ Linha Editorial: W. Books - Clássicos_x000D_ Faixa Etária: + 16 anos_x000D_ Assuntos (tags): Inglês, Romance, Amor, História_x000D_ BISAC: Ficção / Ficção / Romance / Ação e Aventura_x000D_ Linha de Produto: W. Books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 29.9, 29.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-mc9q7x7thk8xc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42558749565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18810540522', 'Controle Alarme Positron Pxn72 Cyber Ex Fx Px Tx 300 330 360', '# Auto Equip # Bem-vindo! * Produtos de Qualidade * Postagens até 24h * Pagamento Facilitado Descrição Controle remoto alarme Pósitron PXN72 Cyber 300 330 360 Duoblock G6 G7 G8 Função Convencional e Presença - Pósitron: O PXN72 da Pósitron vai te surpreender em qualidade e eficiência, e além dele possuir um desing mais tecnológico mantendo a originalidade do seu veículo. É sempre bom ter um controle reserva não é mesmo? E agora, você pode cadastrar demais controles no seu carro! Os controles foram criados com a mais recente e tecnologia do mercado! Confira já! Controle de alarme PXN72 é bom e em quais modelos de alarme o controle é compatível? É bom e os controles compatíveis com os alarmes da linha cyber EXACT, FX, PX e TX Linha 300, 330 e 360 e *DuoBlock (G6, G7 e G8 ) **Somente para ativar/desativar não possui função presença Especificações Técnicas: - Marca: Pósitron - Modelo: PXN72 - Design Exclusivo Pósitron - Possui LED indicador de ativação e desativação - Modo econômico (desliga o controle automaticamente após 25 minutos de inatividade) - Tecnologia Anticlonagem New Flex Code - Compatível com os alarmes EXACT, FX, PX e TX Linha 300, 330 e 360 e *DuoBlock (G6, G7 e G8 ) – Somente para ativar/desativar não possui função presença Conteúdo da Embalagem: - 01 Controle Importante: Garantia de 3 meses. A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 78.9, 78.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/91b83bccb43bcf9f2f568fbda7abdfbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F18810