INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18178265697', 'Sapato Vegas Alth 3269 Rafarillo', 'O Sapato Social Rafarillo Alth é confeccionado em couro e traz design detalhado. Seu solado em borracha e sua palmilha elevada proporcionam estabilidade e aderência ao caminhar, possibilitando o aumento de até 7 cm de altura. O modelo conta também com bico quadrado alongado e ajuste em elástico, inspirando sofisticação e conforto no calçar. Clássico, aposte em produções formais, festas e eventos evangélicos, com combinações de calça alfaiataria, sendo ideal para homens de baixa estatura. ESPECIFICAÇÕES TÉCNICAS Material: Couro Solado: Borracha Tipo de Bico: Quadrado Material Interno: Poliuretano (PU) Indicado para: Dia a dia Estilo: Sociais Tipo de calçado: Oxfords Ano de lançamento: 2020 Temporada de lançamento: Outono-inverno Fechamento: Elástico Estilo da Peça: Com textura Ocasião: Conforto Importante: Confeccionado em material antitranspirante e solado de borracha, oferecendo mais conforto e segurança ao caminhar Complemento da Descrição: Com salto interno que, somado ao solado, atinge até de 7 cm Garantia do Fabricante: Contra defeitos de fabricação INFORMAÇÕES ADICIONAIS A limpeza do calçado pode ser feita com sabão neutro e pano úmido e não deve ficar de molho. Lavar a palmilha separadamente. Não usar nenhuma fonte de calor para secar. Guardar em local sem umidade e deixar descansar na sombra por 12 horas após o uso', 399.9, 338.99, NULL, 'Men Shoes > Oxfords & Lace-Ups', 'https://cf.shopee.com.br/file/sg-11134201-7qvfm-lfiudk1sftalda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F865304201%2F18178265697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
