INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197485499', 'Fonte De Alimentação Pc Gamer Cowboy Atx 600w Leds Rgb', 'Fonte de Alimentação PC Gamer Cowboy ATX 600W Leds RGB A fonte de Alimentação Cowboy ATX 600W foi desenvolvida para atender às principais exigências dos fanáticos por games, esta fonte não só fornece uma energia estável, mas também adiciona um toque de estilo ao seu setup com seus LEDs RGB integrados. Com 600W de potência, essa fonte proporciona energia estável necessária para suportar configurações de PC gamer de médio a alto desempenho. E conta com ventiladores silenciosos que garantem uma operação eficiente e resfriamento adequado, mesmo em sessões de jogos intensas e leds em RGB integrados para dar uma experiência visual incrível, adicionando um toque de estilo e personalização ao seu sistema. Dimensões: 15x14cm (CxL) Peso: 1,006kg Especificações: - Modelo: KP-535RGB - Potência: 600W - Fonte Bivolt - MTBF de 100.000 horas 25°C - Proteção contra curto circuito OVP/OCP/SCP - Chaveamento manual 100/230Vac - Cooler de 120mm ultra silencioso - Cabos com capa de proteção - Normas técnicas IEC60950 (Segurança elétrica) IEC61000 (Segurança eletromagnética) - 1 Conector ATX 20+4 Pinos - 1 Conector ATX 12V - 3 Conectores SATA - 3 Conectores IDE - 1 Conector FDD - Compatível com placas mãe de 20 e 24 pinos - Chave Seletora de tensão Itens inclusos: 1 Fonte de Alimentação 1 Cabo de Energia', 330.0, 231.09, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-7rbmk-m5lnj46mvetc6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23197485499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692925116', 'Rádio Automotivo FM KP-C18BH USB Com Bluetooth Cartão SD', 'O MP3 Player KP-C18BH transforma sua experiência de dirigir, oferecendo a possibilidade de curtir suas músicas favoritas diretamente do carro, seja em um pendrive, cartão de memória, ou até mesmo via Bluetooth com o seu smartphone. Além de tocar suas playlists, o aparelho permite atender chamadas com facilidade graças à tecnologia Bluetooth integrada. Compatível com as principais tecnologias de áudio, o KP-C18BH garante som de qualidade e praticidade no uso diário. Com sintonizador de rádio FM, entradas para cartão SD/MMC e USB, ele é a escolha ideal para quem busca versatilidade e funcionalidade em um único aparelho. ESPECIFICAÇÕES: Entradas para Cartão SD/MMC e Pendrive USB (até 32 GB). Entrada Auxiliar P2. Suporte para arquivos de áudio nos formatos MP3 e WMA. Conectividade Bluetooth para streaming de música e atendimento de chamadas. Função Relógio. Rádio FM com sintonizador eletrônico estéreo e memória para até 18 estações. Tela LCD colorida. Controle remoto incluso. Potência de saída: 4 x 60W. Equalizador com modos: POP/CLASS/ROCK/LOUD. CONTEÚDO: 1x MP3 Player Automotivo KP-C18BH. 1x Controle remoto. 1x Cabo de instalação. 1x Manual em português.', 150.0, 110.9, NULL, 'Audio > Media Players > Radio & Cassette Players', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-m5lnlo5caldsf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23692925116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
