INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250180613', 'Body Polo para Bebê Menino em Suedine Up Baby', 'Body polo para bebê menino, une estilo e praticidade para o dia a dia do bebê. Confeccionado em suedine (algodão), garante conforto térmico e maciez ao toque. Conta com peitilho com botões de pressão e caseados, mangas longas com punhos, bordado com ícone da marca e abertura por botões de pressão entre as pernas. Perfeito para compor looks versáteis, seja para momentos casuais ou ocasiões especiais.Tecido: SuedineComposição: 100% algodãoModelagem: JustaComprimento Mangas: LongaComprimento: CurtoForro: NãoCintura: MédiaDecote/Gola: Gola polo', 109.9, 65.94, NULL, 'Baby & Kids Fashion > Boy Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-821fy-mggss94o13ig24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58250180613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251677544', 'Conjunto Bebê Menino Body e Bermuda Up Baby', 'Este conjunto para bebê menino é composto por um body de algodão com estampa de dinossauros e dupla abertura com botões de pressão, pensada para facilitar o vestir e as trocas. Acompanhado por uma bermuda de moletom sem felpa, que conta com cós elástico, cadarço e bolso falso, completando o look, assegurando liberdade total para brincar.Tecido: Body: Meia Malha (Algodão) / Shorts: Moletom Sem Felpa (Algodão e Poliéster)Composição: BERMUDA: 50%algodão 50%poliéster,BODY: 100%algodãoModelagem: JustaComprimento Mangas: CurtaComprimento: CurtoForro: NãoCintura: MédiaDecote/Gola: RedondoFechamento: Botões de pressão', 164.9, 82.45, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-822y2-mi1nasfidsliad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58251677544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57057274652', 'Ração GoldeN Formula Cachorros Adultos Salmão e Arroz 15,0kg', 'Ração GoldeN Formula para Cães Adultos (Sabor Salmão e Arroz) 15 kg A embalagem de quinze quilos da GoldeN Formula Cães Adultos (Salmão e Arroz) é a escolha premium para tutores que buscam um suporte nutricional diferenciado para seus pets. Desenvolvida pela PremieRpet, esta versão se destaca por utilizar o salmão como fonte de proteína de altíssima qualidade, o que proporciona uma palatabilidade excepcional — ideal para cães que são um pouco mais exigentes com o sabor da ração — além de um perfil rico em ácidos graxos essenciais para a saúde da pele e da pelagem. O formato de 15 kg é o investimento certo para garantir um suprimento de elite por um período prolongado, mantendo a consistência na dieta do seu cão. Por ser um alimento de alta digestibilidade, o organismo do pet consegue absorver os nutrientes de maneira eficiente, o que se reflete em mais energia, disposição e, claro, fezes com volume e odor reduzidos. É a opção ideal para quem deseja oferecer um "toque especial" no cardápio diário, garantindo saúde, beleza e bem-estar em um único produto. Por que escolher a GoldeN Formula Adultos Salmão e Arroz? Proteína Nobre: O uso de salmão de alta qualidade oferece um sabor irresistível e uma excelente fonte de aminoácidos para a manutenção muscular. Saúde da Pele e Pelos: Naturalmente rica em Ômegas 3 e 6, a fórmula promove brilho intenso, maciez e ajuda a manter a pele protegida. Digestão Eficiente: O arroz selecionado e ingredientes de alta biodisponibilidade garantem um trânsito intestinal equilibrado. Ambiente mais Limpo: Enriquecida com extrato de yucca, a fórmula reduz consideravelmente o odor das fezes, facilitando a convivência em ambientes fechados. Nutrição Sem Compromissos: Livre de corantes e aromatizantes artificiais, focada puramente na saúde e longevidade do seu cão. Clique no botão de compra e proporcione ao seu cão uma experiência gastronômica superior, unindo todo o sabor do salmão à tecnologia nutricional da linha GoldeN Formula!', 355.38, 355.38, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mlw1j0appgcl11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F57057274652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494695055', 'TOP FITNESS FEMININO COM PESPONTO OASIS DLK', 'Top Fitness Feminino Com Pesponto Oasis O Top Fitness Feminino Com Pesponto Oasis é a peça ideal para quem busca desempenho, conforto e proteção em seus treinos. Esse top tem um design moderno e é ideal para suas atividades físicas, garantindo conforto e estilo. Tecido de Alta Performance O Top Fitness é feito em tecido super macio. Ele é confortável e proporciona sensação agradável à pele, enquanto seu decote elevado reforça a segurança, ideal para treinos intensos. A tecnologia de secagem rápida mantém você seca e confortável, permitindo que o suor evapore rapidamente durante suas atividades. Além disso, este top oferece proteção solar UV 50+, protegendo sua pele durante treinos ao ar livre. Design e Funcionalidade Com esse Top Fitness você tem o melhor em tecnologia de tecidos e design funcional. Seja na academia, corrida ou ioga ao ar livre, ele oferece a combinação perfeita entre estilo, proteção e conforto!', 110.99, 110.99, NULL, 'Women Clothes > Tops > Tube Tops', 'https://cf.shopee.com.br/file/sg-11134201-821fq-mh0y0j7fjimhee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F22494695055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40931473805', 'Degrau Infantil Duplo Branco Antiderrapante p/ Banheiro e Cozinha Zippy Toys - 10419', 'O Degrau Infantil Duplo Zippy Toys foi desenvolvido para proporcionar autonomia e segurança para os pequenos. Com duas alturas ajustáveis, ele ajuda as crianças a alcançarem pias, prateleiras e outros locais de difícil acesso, como banheiros, cozinhas e quartos. Segurança é garantida pela superfície antiderrapante, que proporciona maior estabilidade, mesmo com os pés molhados. O design robusto, com estrutura de plástico (PP) e ferro resistente, oferece durabilidade e resistência, enquanto o acabamento elegante se adapta perfeitamente a qualquer ambiente doméstico. Com dimensões compactas (20x30,5x34 cm), o Degrau Infantil Duplo é leve (1,2 kg), tornando-o fácil de transportar e manusear. É o acessório ideal para o dia a dia das crianças, promovendo independência ao realizar atividades como escovar os dentes ou lavar as mãos. Especificações Modelo: Degrau Infantil Duplo Zippy Toys Material: Plástico (PP) e ferro resistente Superfície: Antiderrapante para segurança extra Altura Ajustável: Duas alturas distintas Medidas: Altura: 20 cm Largura: 30,5 cm Comprimento: 34 cm Peso: 1,2 kg Idade recomendada: A partir de 2 anos (sempre com supervisão de um adulto) Uso: Ideal para banheiros, cozinhas, quartos. Destaques do Produto Superfície antiderrapante para mais segurança Estrutura robusta com plástico (PP) e ferro resistente Altura ajustável para atender diferentes necessidades Leve e fácil de transportar (1,2 kg) Ideal para promover independência nas crianças Características: - Marca:ZIPPY TOYS - Modelo:10419 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1 Degrau Infantil Duplo Zippy Toys', 65.0, 57.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-823oz-mp42crl2vqx908', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F40931473805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999039364', 'BERMUDA FITNESS FEMININA COM ELÁSTICO ESTREITO LATERAL ACTIVITY DLK', 'A bermuda ganha sofisticação com os elásticos finos nas laterais, que elevam o design da peça. Possui compressão média e conforto anatômico, ideal para qualquer atividade física ou para looks do dia a dia. BENEFÍCIOS - Elásticos finos nas laterais para visual marcante - Tecido de poliamida com proteção UV e toque macio - Cós firme que proporciona segurança - Comprimento perfeito para quem não gosta de modelos curtos INFORMAÇÕES ADICIONAIS Nível de compressão da peça: Médio Sobre a cor do produto: Pode haver variação na cor do produto final de acordo com o brilho do monitor ou tela do celular. Garantia: Contra defeito de fabricação MEDIDAS DA MODELO Altura: 1,64 cm Busto: 93 cm Cintura: 67 cm Quadril: 100 cm A modelo está vestindo tamanho P SOBRE A MARCA - Somos uma das maiores marcas de moda fitness do Brasil. - Entregamos as melhores roupas esportivas há mais de 8 anos. - Já chegamos a mais de 5 mil cidades em todo o país. - Contamos com mais de 2,6 milhões de DLK Lovers no Instagram.', 110.99, 110.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-822zh-mo73jz83gxdv67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F23999039364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48306875181', 'Motor De Partida Ford Courier Fiesta Escort Ecoesport Ka 10 Dente 12v', 'MOTOR DE PARTIDA (MOTOR DE ARRANQUE) FORD - KA, FIESTA, ECOSPORT, ESCORT, COURRIER - 10 DENTES. APLICAÇÕES: • Ford Courier 1.0 1999 Até 2002 • Ford Courier 1.4 1997 Até 2000 • Ford Courier 1.6 Zetec Rocam 1999 Até 2002 • Ford Fiesta 1.0 Zetec Rocam (aspirado / Flex) 1999 Até 2012 • Ford Fiesta 1.6 Zetec Rocam (aspirado / Flex) 1999 Até 2012 • Ford Ka 1.6 Zetec Rocam 1999 Até 2014 • Ford Ka 1.0 Zetec Rocam (Normal / Supercharger turbo) 1999 Até 2014 • Ford Ecosport 1.0 Zetec （aspirado / Supercharger） 2003 Até 2012 • Ford Ecosport 1.6 Zetec （aspirado / Supercharger） 2003 Até 2012 • Ford Escort 1.6 Zetec Rocam 2000 Até 2003 Sistema 10 dentes - COM PLANETARIA CARACTERISTICAS: KW: 1.1 DENTES: 10 VOLTS: 12V SUBSTITUI O MOTOR COM 9 DENTES REFERÊNCIAS: ORIGINAL: 3S6511000AA 3S6511000BA 3S6511000CA VALEO: 438180 D6RA92 D7E33 D7E34 D7E37 INDICAMOS QUE SEJA INSTALADO POR UM PROFISSIONAL DA ÁREA, PARA NÃO PERDER GARANTIA CONTRA MAL USO. ✨ Por que escolher JDMSPEED? Produtos idênticos aos originais. Marca nacional localizada em São Paulo. Suporte total ao cliente antes e depois da compra. Envio rápido e seguro. 🛒 Compre Agora e Garanta a Performance do Seu Veículo! Peça de reposição de ALTA QUALIDADE, com padrão de fabricação JDMSPEED. Produto idêntico ao original, garantindo encaixe perfeito e durabilidade para o seu veículo. Somos a JDMSPEED: Sua marca de confiança em São Paulo. ⚠️ ATENÇÃO IMPORTANTE – ANTES DE COMPRAR: Para garantir a satisfação total e evitar transtornos com trocas, pedimos a gentileza de: CONFERIR BEM TODOS OS DETALHES da peça nas fotos e na ficha técnica do anúncio. Verificar a aplicação correta (modelo, ano e motor) compatível com o seu veículo. Recomendamos comparar o produto anunciado com a peça que já está instalada no seu carro. Em caso de incerteza, utilize o campo de perguntas! Oferecemos atendimento completo para a resolução de quaisquer dúvidas. 🔄 Política de Troca e Devolução (Condições Obrigatórias): Priorizamos a transparência e a qualidade. A devolução ou troca do produto será aceita SOMENTE mediante o cumprimento rigoroso das seguintes condições: O produto deve estar sem marcas de uso e em perfeito estado. Devolução com a Embalagem Original intacta. Obrigatório o envio da Nota Fiscal (DANFE). Com o Selo de Garantia da JDMSPEED intacto e visível. Defeito de Fabricação: Em caso de alegação de defeito, a peça será enviada para análise técnica antes de qualquer ressarcimento ou troca, conforme as normas do CDC. Como sei que o produto é compatível com meu carro? Verifique atentamente os carros listados na aplicação acima, confira a lista de códigos de referência e compare as fotos com o produto que tem em mãos. Deve ser instalado por um profissional? Sim, sempre recomendamos que a instalação seja feita por um profissional especializado, não nos responsabilizamos pelo mau uso ou instalação indevida, isso pode causar a perda da garantia. Garantia do vendedor: 90 dias.', 890.0, 375.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-825az-mqmzjpdyjoct57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1550959167%2F48306875181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19652480844', 'Kit 2 Câmara de Ar MTB Pirelli Aro 29 48mm Schrader Bico Fino + 2 Fita Anti Furo', 'ATENÇÃO - CONFERIR TABELA DE MEDIDAS Se o seu produto não requerir nenhuma medida, ignore este aviso ;) Caso a tabela de medidas não esteja aparecendo, nos mande uma mensagem no Chat avisando, é rapidinho :D Temos o melhor tempo de resposta de lojas de Ciclismo da Shopee. SOBRE O PRODUTO Pensando no seu conforto e também na sua segurança, a Pirellli lançou o Kit 2 Câmara de Ar MTB Pirelli Aro 29 48mm Schrader Bico Fino + 2 Fita Anti Furo, justamente para você que quer curtir toda a sua trilha sem interrupções. Construída em material elástico de alta resistência, deve ser inflada a fim de manter os pneus sempre em boas condições, além de oferecer mais conforto ao ciclista. O Kit 2 Câmara de Ar MTB Pirelli Aro 29 48mm Schrader Bico Fino + 2 Fita Anti Furo é a melhor alternativa para ciclistas que buscam proteção em terrenos severos, que podem apresentar elevações, buracos e outros tipos de obstáculos. É leve e fácil de carregar, para prevenir, você pode levar uma câmara reserva na bolsa, assim, nada poderá interromper sua diversão! ESPECIFICAÇÕES Fabricante: Pirelli Material: Borracha Bultyl Sintética, Cobre, Níquel Marca das Fitas: SafeTire Dimensões embalagem: 16 x 11 x 2 cm Peso bruto: 0,29 Kg ITENS INCLUSOS 2x Câmaras de Ar 2x Fitas Anti Furo SOBRE A ROUPAS PARA CICLISMO Temos mais de 10 anos de história no mercado, distribuindo produtos de ciclismo de qualidade para todo o país e presentes nas maiores plataformas de vendas. Nossoprazo de expedição é de 1 dia útil após a confirmação do pagamento, e nossa equipe de expedição está ligada no 220v de segunda à sexta para que seu pedido chegue rapidinho. - Todos os produtos são a pronta entrega - Itens originais, nacionais/importados e de qualidade - Envio em até 1 dia útil após a data da confirmação do pagamento - Participamos do programa de FRETE GRÁTIS da Shopee, que te dá um baita descontão para TODO O BRASIL Nosso slogan também não deixa a desejar! Você está comprando com a ROUPAS PARA CICLISMO, a WebStore do Ciclista😎', 88.68, 88.68, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-22120-ag2c3jpxmtkv68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F19652480844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998049076', 'Short Masculino Tamanho Grande Bolso Esportivo Casual Elite Grafite', 'O Calção Comfort, confeccionado em malha Cacharrel dupla, é o aliado perfeito para suas atividades de esporte e lazer. Com zero transparência, este short esportivo oferece a privacidade que você precisa sem sacrificar o conforto. Possui dois bolsos laterais práticos e uma modelagem europeia, ligeiramente mais comprida para um estilo sofisticado. A cintura conta com elástico e cordão regulador para um ajuste personalizado. Feito de 100% Poliéster, este calção é durável e fácil de cuidar. MATERIAIS: Malha (100% Poliéster). BENEFÍCIOS DE USO: Melhora a mobilidade para a prática de esportes e exercícios. Flexibilidade e conforto para a rotina diária. Elegância e estilo para seu lazer e tempo livre. INDICADO PARA: Treinos na academia e exercícios intensos. Atividades ao ar livre como caminhada e corrida. Momentos de lazer, unindo conforto e estilo. PERGUNTAS FREQUENTES: P: Como escolho o tamanho ideal do meu calção masculino? R: Para encontrar o calção perfeito para o seu corpo e garantir o ajuste ideal, siga estas dicas de medição: Comprimento: Coloque a ponta da fita métrica na sua cintura até onde você deseja que o calção termine, considerando as curvas do seu corpo. Cintura: Encontre o ponto mais estreito da sua cintura, geralmente logo acima do umbigo. Envolva a fita métrica em volta dessa área. Novamente, certifique-se de que a fita esteja reta. Não puxe a fita métrica muito apertada - deve haver espaço suficiente para você respirar confortavelmente. Quadril: Envolva a fita métrica em volta da parte mais larga do seu quadril, que normalmente está alinhada com a parte inferior das nádegas. Certifique-se de que a fita esteja reta. Aqui estão as correspondências de tamanho: EG1 - Comprimento 55 cm / Cintura 90-108 cm / Quadril 130 cm / Manequim 54 EG2 - Comprimento 56 cm / Cintura 96-114 cm / Quadril 136 cm / Manequim 56 EG3 - Comprimento 57 cm / Cintura 102-120 cm / Quadril 142 cm / Manequim 58 EG4 - Comprimento 58 cm / Cintura 108-126 cm / Quadril 148 cm / Manequim 60 P: O calção é transparente? R: Não, o calção masculino Elite é feita com tecido zero transparência. P: Quais são as principais características do calção masculino Elite? R: As características do produto incluem: Zero transparência, a malha cacharrel dupla garante privacidade e conforto. Praticidade, pois possui dois bolsos laterais e ajuste personalizado na cintura. Durabilidade, confeccionado em 100% Poliéster, garantindo resistência e facilidade de cuidado.', 54.9, 46.67, NULL, 'Men Clothes > Shorts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m32d6mm849392a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557320114%2F22998049076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42215203359', 'Rack Bancada Tucupí 180cm para TV até 75" com Pés de Metal', 'Transforme sua sala com o Rack Bancada Tucupí 1.8! Com design moderno em MDF 15mm e pés de metal, suporta TVs de até 75”. Com 2 portas, 1 prateleira e 2 nichos, organiza seus eletrônicos com praticidade. Elegância e funcionalidade reunidas em um só móvel! Não perca a chance de elevar seu espaço a outro nível! Modelo : Rack Bancada Tucupí 1.8; Material da estrutura: MDF 15mm com pés em metal; Dimensões: 183 cm(L) x 54,5 cm(A) x 42 cm(P); Tamanho máximo de TV: até 75” Polegadas; Tamanho do espaço para TV: 183 cm x 42 cm; Quantidade de portas: 2 (dobradiças metálicas); Com puxador: Sim, metal; Quantidade prateleiras: 1; Com nichos: Sim, 2; Com rodízios: Não; Peso suportado: até 20 kg distribuídos; Requer montagem: Sim (kit montagem incluso); Embalagem do envio: Papelão, plástico, isomanta e Isopor; Tonalidade das Cores: Off White: semi-brilho; Nature: semi-brilho; Dourado: semi-brilho; Bronze: semi-brilho; Preto: semi-brilho; Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 632.98, 588.68, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-824h6-mdw9ll4vu2o149', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401986069%2F42215203359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
