INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22813580899', 'Livro - Guilherme Tell', 'Herói lendário do século XIV, Guilherme Tell era incrivelmente habilidoso com arco e flecha. Sua coragem teria ajudado a sociedade da Suíça a se tornar independente e livre do domínio de um governante tirano._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2022_x000D_ Autor: Donaldo Buchweitz_x000D_ Idioma: Português_x000D_ Páginas: 24_x000D_ Dimensões: L 25.00 x A 25.00 x E 0.20_x000D_ ISBN: 9786526100349', 14.9, 14.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-22120-k4kxmv61xelva6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22813580899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
