INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893254412', 'CAPA PROTEÇÃO CORREIA DENTADA ZAFIRA 2.0 8V MANUAL 2001.. - 97819 - 106122', 'CAPA PROTEÇÃO CORREIA DENTADA ZAFIRA 2.0 8V MANUAL 2001.. CAPA PROTEÇÃO CORREIA DENTADA ASTRA 2.0 8V MANUAL 2000O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria. O KIT pode variar conforme o modelo do veiculo, vem: Capa Interna;e Capa Externa. (Superior/Inferior).', 92.43, 92.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-m6u7yrqrjyfg6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23893254412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997669283', 'Pré Filtro Combustível Hyundai I30 2009 a 2012 - 1291738 - 1361', 'Pré Filtro Combustível Hyundai I30 2009 a 2012 1291738 1361 2.0 4Cil 16v - Gasolina O pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada._x000D_ Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento._x000D_ Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 39.69, 39.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd52-luh200d18ibu9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18997669283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393196376', 'Vela Ignição Mitsubishi Space Wagon 1997 a 2003 - 798994 - EVI518', 'Vela Ignição Mitsubishi Space Wagon 1997 a 2003 798994 EVI518 2.4 16v Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 59.53, 59.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lvpr2pa025jg16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23393196376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199498842', 'Poltrona Decorativa Amamentação + Puff Apoio Para Pés Várias Cores', 'A poltrona Decorativa Opalla proporciona um toque de charme e beleza em seu lar, feita com matéria prima de primeira qualidade, Revestida de Fibra e percinta no encosto e espuma no assento. ESPECIFICAÇÕES: - Estrutura: MDF e EUCALIPTO - Tecido: Suede - Pés: MADEIRA DIMENSÕES EXTERNAS: Altura : 88 cm largura: 78 cm Comprimento: 61 cm DIMENSÕES INTERNAS: Altura do chão ao assento: 48 cm Profundidade do assento: 45 cm Largura do assento: 43 cm Pés palito envernizados cor mel Puff Opala - Medidas Produto - Altura: 40 cm; - Largura: 47 cm; - Profundidade: 39 cm Peso Suportado: Até 120 Kg sem impacto, garantia de fábrica 90 dias para somente defeito de fábrica. * Atenção *Consultar o frete antes de finalizar a compra pois este anuncio não tem frete grátis. * Este produto é enviado através de transportadora dependo de cada região tem o seu prazo determinado pela a transportadora para ser entregue em dias úteis, em horário comercial. * Não nos responsabilizamos no ato da entrega por montagens, desmontagens, instalações de produtos, nem utilização de guinchos ou equipamentos similares para acesso a pisos superiores em apartamentos. - Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por escadas, elevadores, portas e corredores. Observando as orientações acima, evita-se futuros desagrado ou imprevistos com a entrega do produto. Havendo despesas adicionais, serão de responsabilidade do cliente;', 399.9, 299.93, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0vwgjezup35fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F646888142%2F19199498842', NULL, NULL, '2026-