INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498244638', 'Mangueira Respiro Óleo FIAT PALIO 1.0 8v FIASA 1996 A 1999 - 88271 - 3158', 'Mangueira Respiro Óleo FIAT PALIO 1.0 8v FIASA 1996 A 1999 MOTOR 1.0 8VEssa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 39.83, 39.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m6u5gx96spgyeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22498244638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592523481', 'Filtro Óleo Fiat Tipo 1992 a 1995 - 6312 - WO460', 'Filtro Óleo Fiat Tipo 1992 a 1995 6312 WO460 (EFI Importado) - Motor 1.6 8v /(MPI) - Motor 2.0 8v - Gasolina - (Mecânico) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 28.28, 28.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbki-lmqigwfd4j0r03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22592523481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899350890', 'Twotrees adequado para máquina de gravação a laser CO2 e máquina de corte 300/400/500/600/1000mm', '※ A linha de escala só pode ser riscada para a parte do favo de mel, os dados de tamanho são o comprimento total da placa!! ※ A linha de escala só pode ser riscada para a parte do favo de mel, os dados de tamanho são o comprimento total da placa!! ※ A linha de escala só pode ser riscada para a parte do favo de mel, os dados de tamanho são o comprimento total da placa!! ✅【ELEVE SUA EXPERIÊNCIA CRIATIVA】A placa de base laser em formato de colmeia e os painéis de alumínio oferecem dupla proteção para o seu ambiente de trabalho, enquanto o design em formato de colmeia facilita a evacuação da fumaça para um trabalho mais limpo. ✅【RÁPIDA DISSIPAÇÃO DE CALOR E FLUXO DE AR】Nosso produto possui um design uniforme com furos em formato de colmeia que aceleram a saída da fumaça e resolvem o problema do escurecimento da madeira e de outros materiais devido à fumaça. ✅【PROTEÇÃO ABRANGENTE】A mesa de trabalho em formato de colmeia vem com um painel de alumínio e quatro protetores de canto, evitando danos causados pelo laser e possíveis ferimentos nas mãos. ✅【AMPLA COMPATIBILIDADE】Tamanho grande, amplamente compatível com a maioria das máquinas de gravação e com outras máquinas de gravação, como máquinas de gravação a dioxigênio, fibra e CO2, como XTool D1, D1 Pro, Atomstack A20 Pro, SCULPFUN, ORTUR, etc., e com graduação precisa das bordas, este painel alveolar permite uma gravação fácil em objetos de madeira e metal. ✅【COMPROMETIDO COM 100% DE SATISFAÇÃO】Garantimos a qualidade dos nossos produtos. Se, por algum motivo, não estiver satisfeito com a sua compra, entre em contato conosco.', 599.0, 398.0, NULL, 'Computers & Accessories > Printers & Scanners > Others', 'https://cf.shopee.com.br/file/br-11134207-820m4-mn42ygf6e8e8b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1698912545%2F22899350890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598014579', 'Amortecedor de Porta Malas Para Tampa Traseira Fiat Palio Fire 1996 até 2016', 'O amortecedor de porta malas é um item de extrema importância para os veículos, tanto para sua comodidade ao colocar bagagens no porta malas, quanto para sua segurança. Não hesite em fazer a substituição desse item, pois sua instalação pode ser feita com muita facilidade. --------------------------------------------------------- *** AS MARCAS PODEM VARIAR ENTRE CINOY, APX E TIGER AUTO. SÃO ENVIADAS CONFORME A DISPONIBILIDADE EM ESTOQUE *** --------------------------------------------------------- Características do produto: - Compatível com Fiat Palio ano 1996 até 2011 - Comprimento: 49cm Especificações Gerais: - Fabricado em aço e ferro; - Mola (pressurização) a gás; - Força de expansão ou abertura 40 kg.', 42.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rav6-mb73p90qgocxcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421977782%2F23598014579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
