INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16830147004', 'Película de Nano Vidro para Samsung Galaxy A9 2018 - Gorila Shield', 'A Película de Nano Vidro é fabricada por um composto de polímeros reforçados. Ela é extremamente semelhante ao material da película de vidro, entretanto possui uma resistência 3x maior. Além disso, o acessório não se quebra ou se parte com os impactos. Todas as películas para celular da Gorila Shield possuem Certificação US Military, que garante que seu equipamento suportará condições ambientais difíceis.', 14.27, 14.27, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/3f3850e5a3eea1935bfccf7a65e9630f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F16830147004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
