INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499592227', 'Brinco Rommanel Mini Borboleta Infantil Banhado A Ouro Granitada - 526989 Original', 'Brinco em formato de borboleta com trabalho granitado nas asas maiores. Mede 0,60 cm x 0,60 cm A Rommanel é conhecida por ter as melhores jóias folheadas do Brasil, que não oxidam, não alteram a cor, não contêm níquel em sua composição e não causam alergias. As jóias Rommanel recebem três banhos de ouro, com acabamento semelhante ao ouro maciço. Há mais de 30 anos, a Rommanel oferece beleza e autoestima através de suas joias folheadas. Possui uma linha diversificada com mais de 3.000 modelos, onde o consumidor encontra joias para todos os momentos. A Rommanel está presente em todo o Brasil, com mais de 250 lojas e muitas consultoras independentes e em mais de 20 países, incluindo EUA e Canadá. As joias folheadas a Ouro 18k, Rhodium, Rhodium Negro e Paládio, joias em Aço e Prata 925 são produzidas uma a uma com a qualidade, carinho e diferencial já reconhecido por muitas pessoas. Algumas instruções de uso: - Evite contato das jóias com cremes, detergentes, protetores solares, sabonetes ou similares, pois seus resíduos podem deixar as pedras opacas ou leitosas; - Evite tomar banho de mar, piscina e/ou rios com as jóias; - Em qualquer procedimento estético, procure tirar jóias, evitando assim eventual contato com produtos químicos; - Evite lavar ouças ou fazer trabalhos manuais que possam gerar atrito com as jóias; - Para limpeza apropriada, dirija-se à distribuidora; - Apenas as jóias e aço aceitam gravação.', 130.0, 115.17, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Jewelry', 'https://cf.shopee.com.br/file/sg-11134201-7rblp-m5d0tvkjmle290', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F536715397%2F19499592227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
