INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10927371522', 'Jardineira Floreira de Madeira Ripada 30 x 16 cm Decorativa', 'Modelo que exalta as belezas naturais da madeira, trazendo um charme único para a sua decoração! Jardineira ripada de madeira envernizada para os amantes do toque rústico. O tom da peça mescla muito bem com o verde das folhas, mantendo a harmonia visual no seu jardim! Não recomendamos plantar diretamente nele, sendo necessário outro(s) vaso(s) ou fazer uma boa cobertura dentro da jardineira. Peças de madeira estão muito bem valorizadas no paisagismo atualmente, ótimas em ambientes modernos ou rústicos, as jardineiras de madeira para plantas irão valorizar o ambiente. Informações: - Feita inteiramente em madeira de eucalipto. - Duas demãos de verniz marítimo com tingimento mogno (cor padrão). - Marca: Alpe & Aritana. Tamanhos disponíveis: - 30 x 15 x 16 - 40 x 18 x 16 - 50 x 20 x 21 - 60 x 26 x 30 - 80 x 27 x 30 - 100 x 27 x 30 (comprimento x largura x altura)', 47.9, 47.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lg534ooxzn5q57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F10927371522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21714837333', 'Lixa D''água a Seco A275 Grana 400 NORTON', 'Lixa D''água a Seco A275 Grana 400 NORTON Indicada para lixamento à seco, em massas e primers. Garante alta remoção de material em toda sua faixa de grãos. Permite realizar lixamento após uso do primer com alto nível de acabamento evitando o acúmulo de material na lixa. Produzida com grão óxido de alumínio marrom com costado de papel leve com e camada especial No-Fil. DADOS TÉCNICOS: Modelo: A275. Grão: P400. Medida: 230x280 mm. Ref: 5539534931 Marca: Norton Garantia: 3 meses *Imagens meramente ilustrativas.', 22.9, 22.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/a03901769bba120c5bd18f5770cba2f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F21714837333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994206334', 'Manifold Manometro R12 R134 R22 R404A Mangueira 0,90CM', 'Manifold Manometro R12 R134 R22 R404A Mangueira 0,90CM Procurando um produto de QUALIDADE e que irá acabar com todos seus problemas? SOMENTE AQUI na loja OFICIAL Marca: ECOTOOLS Códigos: ET636 Sobre o produto: - Novo na caixa - Manifold para uso nos gases R12 R22 R404A e R134A - Mangueiras de 90cm 600-3000PSI - Registro de plastico - Modelo ANALOGICO - 90 dias de garantia Pode ser utilizado também para uso automotivo (R134a) DESDE QUE tenha uma mangueira apropriada de 150cm e também os engates rápido de alta e baixa (A mangueira inclusa neste KIT é de 90cm e NÃO SÃO inclusos os engates de alta e baixa). Para o uso automotivo temos o KIT ET60G. *Pode ser utilizado também para uso automotivo (R134a) DESDE QUE tenha uma mangueira apropriada de 150cm e também os engates rápido de alta e baixa (A mangueira inclusa neste KIT é de 90cm e NÃO SÃO inclusos os engates de alta e baixa). Para que serve o manifold? - possui a função de medir a pressão de gases especificos no sistema, analisa diferentes gases de acordo com a escala indicada no termometro Itens inclusos: - Manifold analógico - Mangueiras manifold 90cm (Azul ; vermelho e amarela)', 219.99, 187.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc2eo8pabjc766', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F587157147%2F23994206334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44375548455', 'Livro Back to Jerusalem | Eugene Bach', 'Back To Jerusalém | 30 Histórias reais para desafiar a sua fé! Eugene BachEste livro é um campo de treinamento espiritual que, esperamos, irá recondicionar sua vida para que você se concentre nos perdidos que nunca ouviram o nome de Jesus Cristo. "Back to Jerusalém" não é um programa de 12 passos para ajudá-lo a ter um relacionamento mais próximo com Jesus. Ele pode ser o único livro que você já tenha adquirido que não se dedica a fazê-lo pensar mais sobre sua vida, seu ministério, seu valor ou seus relacionamentos. Em vez disso, o foco é ajudá-lo a se identificar com a igreja perseguida na China e a aprender as lições dos santos sofredores ao redor do mundo. Infelizmente, identificar-se com a Igreja sofredora não se realiza através de uma dose diária de versículos açucarados e orações leves que fazem todos se sentirem intimamente aquecidos e felizes. Nós o encorajamos a extrair deste livro lições que o farão crescer, à medida que ler sobre os corações e vidas de cristãos perseguidos, ao longo da extensa e sangrenta estrada da China até Jerusalém. Que estes testemunhos e lições o desafiem a morrer para si mesmo e viver para a glória de Deus.', 28.81, 28.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82591-mg5h6r5hw6xa50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F44375548455', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
