INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259438015', 'Coca-Cola + Fanta Laranja Refrigerante Kit', 'A combinação perfeita para os amantes de Coca-Cola e Fanta Laranja! Um kit com 2 litros de cada, ideal para compartilhar com a família e amigos. * Coca-Cola Original: o sabor clássico e inconfundível que você já conhece. * Fanta Laranja: o delicioso sabor da laranja em um refrigerante refrescante. Sem glúten e sem lactose.', 18.99, 18.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mqnekj3dau4h70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259438015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259442957', 'Isotônico Natural Jungle Morango com Limao 500ml', 'Conheça o novo Jungle Low Carb: Bebida funcional para hidratação diária. Além de hidratar, Jungle agora é um Smart drink, enriquecido com Vitamina C e Magnésio e não contém conservantes, corantes ou adoçantes artificiais. O sabor Morango com Limão contém apenas 27 calorias por unidade. É feito com suco de frutas, água de coco e tapioca orgânica. Smart Hydration possui entregas fundamentais para uma hidratação completa, natural e que auxilia na manutenção da imunidade, além de auxiliar na recuperação muscular e fornecer energia para esportes de alta intensidade.', 8.79, 6.99, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8258v-mqnekh5t3i807a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259442957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
