INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293856175', 'Loção Hidratante CeraVe Pele Seca A Extra Seca Sem Perfume 50ml', 'Loção Hidratante CeraVe Pele Seca a Extra Seca Sem Perfume 50ml A Loção Hidratante CeraVe foi desenvolvida especialmente para proporcionar hidratação profunda e duradoura para peles secas e extra secas. Com uma fórmula leve e de rápida absorção, ajuda a restaurar a barreira protetora da pele sem deixar resíduos oleosos. Principais Características: - Hidratação prolongada: Contém ácido hialurônico e ceramidas essenciais que mantêm a pele hidratada por mais tempo. - Tecnologia MVE: Libera gradualmente os ingredientes ativos para uma hidratação duradoura ao longo do dia. - Fórmula livre de fragrância: Minimiza o risco de irritações e alergias, sendo ideal para peles sensíveis. Benefícios: - Hidrata e nutre profundamente a pele seca e extra seca. - Ajuda a restaurar e fortalecer a barreira natural da pele. - Sensção leve e confortável, sem deixar a pele pegajosa. - Dermatologicamente testado e desenvolvido com dermatologistas. Diferenciais do Produto: - Fórmula com ceramidas essenciais e ácido hialurônico para hidratação intensa. - Tecnologia MVE para liberação prolongada dos ingredientes. - Sem fragrância, ideal para peles sensíveis. - Textura leve e rápida absorção. Especificações Técnicas: - Conteúdo: 50ml - Indicação: Pele seca a extra seca - Fórmula: Não comedogênica, sem fragrância Instruções de Uso: - Aplique a loção hidratante sobre a pele limpa e seca, espalhando até completa absorção. Utilize diariamente ou conforme orientação do seu dermatologista. Avisos e Precauções: - Uso externo. - Evite contato com os olhos. Caso ocorra, enxágue abundantemente com água. - Suspenda o uso em caso de irritação e procure orientação médica. - Mantenha fora do alcance de crianças. O que está incluso? - 1x Loção Hidratante CeraVe Pele Seca a Extra Seca Sem Perfume 50ml ---- Dúvidas Frequentes ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 86.59, 65.89, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nttgj8yi9ubd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F23293856175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
