INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593822767', 'Cooler para Notebook Dell Vostro 3500 60.4ES18.001', 'Cooler para Notebook Dell Vostro 3500 60.4ES18.001 | Interno ste é um Cooler bringIT compatível com o notebook Dell Vostro 3500 60.4ES18.001. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.28A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL007-MLP-2', 52.87, 50.23, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8257t-mq5c3kqd1n2k70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22593822767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194202502', 'Conector DC Jack para Notebook Acer Part Number DD0ZHPAD001', 'Conector DC Jack compatível com Acer Part Number DD0ZHPAD001 Este é um DC Jack bringIT compatível com o notebook Acer Part Number DD0ZHPAD001. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Acer. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 5.5mm x 1.7mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC122-AC-0009', 34.75, 33.02, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-825a7-mqs15kxx52bvd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22194202502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
