INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893681275', 'Comoda Tonielque Mariah 4 Gavetas 2 Portas Com Chave', 'A Cômoda Mariah de 4 gavetas e 2 portas é a escolha ideal para quem busca organização, praticidade e elegância em um único móvel. Com design moderno e acabamento sofisticado, ela se adapta perfeitamente a diferentes estilos de decoração, agregando beleza ao quarto, closet ou ambiente desejado. Diferenciais da Comoda Mariah: • 4 gavetas com corrediças metálicas sendo 1 delas com chave, para abrir e fechar com facilidade; • 2 portas com1 prateleira interna, oferecendo mais organização; • Puxadores em MDF, resistentes e com design funcional; • Tampo reforçado de 25 mm, fabricado em MDP de alta qualidade; • Acabamento Premium, disponível em Touch Alto-Relevo ou Alto Brilho UV; • Suporta TV de até 50” no tampo; • Capacidade de carga: 7 kg por gaveta e 20 kg no tampo; • Manual de montagem incluso.; Medidas: Altura: 93,5 cm Largura: 120 cm Profundidade: 43,5 cm Peso: 49 kg Medida das gavetas: Gaveta com chave (1ª): 58,7 cm (L) x 14,5 cm (A) x 38 cm (P) Gavetas 2 a 4: 58,7 cm (L) x 19,8 cm (A) x 38 cm (P) Gaveta 5: 58,7 cm (L) x 28,3 cm (A) x 38 cm (P) Atenção: A montagem não está inclusa. Recomendamos a contratação de um montador profissional ou serviço especializado para garantir uma instalação correta e segura. (imagens meramente ilustrativas)', 549.0, 434.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meo82iuobchtea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842544500%2F23893681275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
