INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297994178', 'Limpador Universal Limpeza Pesada 5 Litros Vonder', 'Limpador universal limpeza pesada, 5 litros, VONDER Pode ser utilizado em uma vasta gama de materiais, possui pH neutro, além de ação profunda e alto rendimento. Composto orgânico, ecológico e verdadeiramente biodegradável. Contém tensoativo biodegradável. Limpador de uso geral utilizado para limpeza pesada. Remove óleo, gordura e fuligem. Ideal para pedras naturais ou sintéticas, azulejo, mármore, porcelanato, cimento, superfície pintada, metais em geral, cromado, madeira, vinílico, acrílico, PVC, lona, tecido e plástico. Pode ser utilizado diluído ou puro, dependendo do nível de sujidade. Efetue sempre um teste sobre uma pequena área na superfície a tratar. Especificações Técnicas: Rendimento aproximado: Desta embalagem de 25 m² a 125 m² (conforme porosidade e nível de sujidade) Inflamável (sim/não): Não Conteúdo da embalagem (ml ou L): 5 L Massa aproximada (peso) (kg): 5,17 kg Conteúdo Da Embalagem: 1 Limpador com 5 litros.', 106.24, 91.71, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rdyl-m1mvh6gzo1i6f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23297994178', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
