INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497323353', 'Óleo Lubrificante do Motor Mobil Super API SL 15W40 Semissintético 1L', 'Descrição do Produto Mobil Super™ 2000 X1 15W-40 é um óleo semissintético que proporciona longa vida útil ao motor e proteção contra a borra e o desgaste. Código do produto: 123039 ANP: 19669 Características e Benefícios Os produtos da linha Mobil Super 2000 têm desempenho comprovado pela Indústria para que você possa estar certo que obterá a performance que você espera de seu veículo Mobil Super 2000 X1 15W-40 proporciona: • Melhor prevenção da formação de lodo • Excelente limpeza do motor • Excelente proteção a altas temperaturas • Excelente proteção contra o desgaste • Bom desempenho em partidas a frio Aplicações Os produtos Mobil Super 2000 são formulados para dar a você a confiança de que seu motor está recebendo uma proteção que vai muito além do que os óleos convencionais podem oferecer. A ExxonMobil recomenda Mobil Super™ 2000 X1 15W-40 se você ocasionalmente vivencia condições de condução exigentes: • Motores a gasolina e etanol • Carros de passeio, SUVs, pick-ups e vans • Condução rodoviários em velocidades de cruzeiro e utilização no anda-e-para das cidades • Condições operacionais variando de normais a ocasionalmente severas Consulte sempre seu manual do proprietário para verificar as especificações e o grau de viscosidade recomendados para seu veículo em particular. Especificações e Aprovações Este produtoatende ou excede os requisitos de: API SL API SM API SN', 48.47, 48.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rasj-mam5n1cpkrps64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F641270782%2F23497323353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
