INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992214494', 'Coxim Amortecedor Palio Argo Mobi Traseiro Mobensani MB475', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FIAT ARGO 2017 a 2023 MOBI 2016 a 2023 PALIO 1996 a 2017 SIENA 1998 a 2016 UNO 2011 a 2021 Conteúdo Da Embalagem: 1 Coxim Amortecedor Atributos: Tipo de Veículo: para carros Ean: 7898261416806 Código do Fabricante: MB 475 Posição: Traseira Descrição do produto: O Coxim Amortecedor é uma peça metálica revestida de borracha, sua função é das apoio ao amortecedor no monobloco do veículo. Essa peça recebe todo o impacto do conjunto de suspensão, absorvendo os ruídos choques e vibrações. O Coxim Amortecedor possui também um rolamento cuja função é garantir o movimento giratório das rodas dianteiras. Garantia: 3 Meses', 13.09, 13.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rbmi-llxijo8jugkad3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22992214494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
