INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693420447', 'Kit Creamy Skincare Glicointense Peel e Sérum Hidratante (2 produtos)', 'Kit Creamy Skincare Glicointense Peel e Sérum Hidratante (2 produtos) Este Kit Contém Creamy Skincare Glicointense Peel - Gel Creme Noturno 30g: fórmula de textura leve para controle da oleosidade, clareamento de manchas, redução dos poros e cuidado da pele com acne. Creamy Skincare - Sérum Hidratante 30ml: traz uma combinação exclusiva de 3 tipos de ácidos hialurônicos associados ao ácido poliglutâmico, ingredientes com poderoso efeito hidratante que em conjunto agem em todas as camadas da pele. Sugestão de Aplicação Glicointense Peel: uso noturno. Aplique sobre a pele seca e hidratada, evitando a região dos olhos, do nariz e da boca. Alterne as noites. Aumentando a frequência, conforme a tolerância. É recomendado utilizar diariamente um filtro solar de alta proteção durante o uso do produto. Sérum Hidratante: aplicar sobre a pele completamente seca de 1 a 2 vezes ao dia, espalhando até absorção completa.', 350.7, 350.7, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-m18sdfwnxida90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23693420447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
