INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998416722', 'Kit de Viagem Multiuso com 3 Frascos 100 ml Plasútil', 'Kit de Viagem Multiuso com 3 Frascos 100 ml Plasútil Dimensao: (Comp x Larg x Alt): 15,2 x 14,2 x 4,2 cm O Estojo de Viagem Plasútil com 3 Frascos de 100 ml cada é o companheiro ideal para suas viagens, oferecendo organização e praticidade para seus itens essenciais. Composto por um estojo de plástico com textura frisada e três frascos de 100 ml cada, este conjunto é perfeito para manter seus produtos de higiene pessoal e objetos pequenos bem organizados. O estojo é versátil e multiuso, sendo ótimo para armazenar produtos como álcool em gel, shampoo, condicionador e outros itens de cuidado pessoal. Além disso, é uma solução conveniente para guardar objetos pequenos e de fácil perda, como eletrônicos e joias. -Detalhes do Produto: Estojo de plástico com textura frisada. Três frascos de 100 ml cada. Uso multiuso para viagens e organização. Perfeito para produtos de higiene pessoal e objetos pequenos. Estojo de Viagem Plasútil com 3 Frascos de 100 ml cada, você estará pronto para viajar de forma organizada e prática, mantendo seus itens essenciais sempre à mão..', 29.99, 29.99, NULL, 'Home & Living > Bathrooms > Soap Dispensers, Holders & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7req2-m8w2wplsn0kn19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F22998416722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694677102', 'Bicos injetores Volkswagen Gol G7 / G8 2017 a 2022', 'Jogo de bicos EA111 1.6 Bicos injetores Volkswagen Gol G7 / G8, 2017/2022, 1.6 Flex - 104cv Catálogo de Aplicações GoParts Concessionária Belcar Veículos ATENÇÃO: Antes de efetuar a compra, confirmar compatibilidade da peça mediante chassi do veículo. INFORMAÇÕES IMPORTANTES: *Trabalhamos apenas com produtos originais Volkswagen *Nosso maior objetivo é atendê-los com qualidade, respeito e satisfação. *Agradecemos a você, clientes online pelas visitas, perguntas, críticas e Sugestões, muito obrigado pela confiança. OBSERVAÇÃO!!! Todos nossos anúncios estão sujeitos a atualizações de valores pela Fábrica!!! Após a aprovação da compra a postagem do produto será realizada em até: 24 HORAS ÚTEIS. Antes de comprar forneça o número do chassi, Perguntem e tirem dúvidas. HORÁRIO DE ATENDIMENTO: SEG A SEX DAS 8:00 AS 18:00 Sábado 08:00 as 12:00', 799.94, 775.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-mbuhwuv3vfveb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1610275770%2F22694677102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16088360474', 'Filtro Ar Corsa Sedan Classic 1.0 2002 A 2005 Metal Leve', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação CHEVROLET CORSA SED.WIND 1.0/MILLENIUM/CLASSIC VHC 2002 até 2005 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca O Grupo MAHLE é um parceiro mundial, líder no desenvolvimento e fornecimento para a indústria automotiva. Uma empresa que trabalha há 100 anos, com a qualidade de equipamento original, atendendo grandes montadoras e o mercado de reposição. Com uma extensa gama de produtos, fornecemos desde componentes de motor até o arrefecimento e climatização, turbo compressores, filtros, alternadores e motores de partida, além de equipamentos de oficina e diagnósticos. MAHLE – há 100 anos mantendo as pessoas em movimento! O Produto O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Tempo de garantia: 3 Meses Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Imagem meramente ilustrativa Valor unitário EAN 7892415459350 Código do Fabricante LX523', 13.88, 13.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lltx7vex28q186', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F16088360474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
