INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8599771906', 'Retificador Alternador Novo Palio Uno 85a Diodo 6x35a Gauss', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação Aplicações FIAT Novo Palio 1.0 /1.4 2012 a 2017 Novo Uno (Vivace) 1.0/1.4 2012 a 2016 Novo Fiorino 2014 a 2016 Conteúdo Da Embalagem 1 Retificador Alternador Observação Parafuso B+ M8, Circunferencia: 111mm Tipo de Veículo para Carros Marca A Gauss iniciou nos anos 1990 como uma remanufatura de reguladores de voltagem. Ao longo dessa trajetória, a Empresa expandiu sua atuação geograficamente. Hoje,a empresa é especializada em eletrônica veicular, fornecendo um amplo portifólio de peças para injeção eletrônica, ignição, elétrica e arrefecimento, para os mercados de veículos leves, pesados, motocicletas, máquinas agrícolas e de construção. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 12 meses a partir da emissão da nota fiscal por defeito de fabricação Valor Unitário. Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. Código do Fabricante GA1302', 116.6, 116.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rbmd-llxil82i54yi08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F8599771906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593629787', 'Kit com 10 Cuecas Boxer Polo Star Sortida Microfibra Masculina', 'Kit 10 Cuecas Polo Star Boxer Sortida Microfibra Masculina Cuecas extremamente confortáveis, perfeitas para ocasiões do dia a dia. As cuecas possuem modelagem boxer e cada peça é confeccionada em microfibra de altíssima qualidade, que oferece ajuste perfeito ao corpo. Uma variedade de modelos para ter conforto em todos os momentos. Guia de Tamanhos: P - Serve 38 M - Serve 40 G - Serve 42/44 GG - Serve 46/48 Composição: 97% Poliamida 3% Elastano Este modelo não possui forro interno. O Kit é enviado de forma sortida, podendo haver repetição de cores. A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 199.9, 159.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4z2gayj9d8wae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F23593629787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
