INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892870713', 'Pelúcia Mickey Fantasia 40 cm Multikids Boneco Brinquedo Infantil Presente Disney Criança', 'Feito com materiais de alta qualidade, essa pelúcia é super fofa e macia ao toque, proporcionando momentos de diversão e alegria. Com aproximadamente 40 cm de altura, o Mickey Mouse ganha vida nessa pelúcia encantadora. Aperte a mão dele para suas bochechas ficarem vermelhas e reproduzir sons de beijos e frases. As crianças podem brincar e abraçar muito seu novo amiguinho de pelúcia, além de ficar lindo na prateleira como decoração e coleção. Recomendado para crianças a partir dos 2 meses de idade. Especificações: Utiliza 3 baterias tipo botão AG13 (LR44) de 1,5V. (Já incluídas) Feito com materiais de alta qualidade, essa pelúcia é super fofa e macia ao toque. Pelúcia produzida com poliéster. Com 40 cm de altura, o Mickey ganha vida nessa pelúcia encantadora. Equipado com um emocionante mecanismo de luz e som que traz à vida o mundo mágico do Mickey Mouse, proporcionando uma experiência interativa e encantadora. Características: - Marca: Multikids - Modelo: BR2197 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: 01x pelúcia Mickey Fantasia Som - Luz - Infantil - Multikids - Pelucia - Disney - Mickey - Fun - Brinquedo - 40cm', 162.4, 143.34, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-m01zbw3c9jg374', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F23892870713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093011736', 'Jogo de tabuleiro War Game of Thrones Grow - 04000', 'O inverno está chegando... E novos rivais surgem nesta instigante história medieval! O clássico jogo War se junta ao sucesso da série Game of Thrones com diversas batalhas, estratégias e desafios de tirar o fôlego. Cada exército defende a honra de sua família numa luta incessante pelo poder de reinar nos 36 territórios. Lannister, Stark, Targaryen ou Baratheon, quem chegará ao trono de ferro? Como jogar War Game of Thrones? No jogo War Game of Thrones, você precisa escolher a sua família e, claro, ser leal a ela até o fim, pois os eventos e suas consequências podem destruir seus objetivos. Use toda a sua inteligência e percepção neste jogo de estratégia para criar os caminhos que o levarão à conquista dos territórios. A família que chegar ao final da trilha e tomar posse do tão desejado trono de ferro será a grande vencedora! Ou seja, é emoção do início ao fim! Prepare-se para este eletrizante combate tático e faça as melhores escolhas rumo ao êxito! O jogo vem com duas regras: uma básica, para os jogadores batalharem ao estilo do War tradicional; e uma avançada, para aqueles que preferem lutar pelo trono assim como os guerreiros de Westeros! Todas as instruções do jogo de Game of Thrones estão no manual que acompanha o produto. A faixa etária indicada para os combatentes é a partir de 14 anos. E aí, você está pronto para liderar uma família até o trono? Idade: A partir de 14 anos Participantes: 2 a 4 jogadores Tempo estimado de jogo: Indeterminado Especificações Técnicas Faixa Etária : A partir de 14 anos Dimensões Aproximadas da embalagem: 38,0 x 27,3 x 5,4 cm Peso: 1,2Kg Participantes: 2 a 4 Características: - Marca:Grow - Modelo: 04000 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Bandeirinhas, 36 cartas território, 16 cartas eventos, 11 cartas objetivos, 4 símbolos casa, 6 dados, 4 brasões, 4 conj. exércitos, 1 tabuleiro e manual war game of thrones - jogo de tabuleiro game of thrones - jogo war - game of thrones - jogo war game of thrones - war - jogos de tabuleiro', 286.9, 246.9, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rd64-lveofpkjut7mf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F23093011736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
