INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597554876', 'Ivercanis 12mg 4 Comprimidos Para Cães World', 'A MANADA ANIMAL é um marketplace de produtos veterinários. É a escolha certa para tutores que prezam pela qualidade dos produtos que seu animal necessita. Tudo com o suporte de uma equipe de veterinários e gestores com mais de 10 anos de experiência no mercado. Fique tranquilo, todos os nossos produtos são originais, adquiridos através de distribuidores credenciados! Ah, e todas as vendas acompanham nota fiscal! MANADA ANIMAL, Tranquilidade pra você, cuidado para ele! __________________________________ Endectocida, Antiparasitário em comprimidos para Cães. Comprimidos Palatáveis de fácil administração. INDICAÇÕES: IVERCANIS, tem como componente ativo a Ivermectina, um agente ectoparasiticida,e também indicado para o tratamento da Sarna Sarcóptica causada por Sarchoptes Scabiei (var.canis) em cães. APRESENTAÇÃO: Embalagem de 12mg com 4 comprimidos. POSOLOGIA: Administrar por via oral, 1 (um) comprimido contendo 12mg de Ivermectina, para cada 45Kg de Peso Corporal ( Equivalente a 0,2mg/Kg/ dia ). FILHOTES : apartir de 1 mês e meio, com no mínimo 4 kg de peso, administrar 1/4 do comprimido. CONTRA INDICAÇÃO : é contra indicado pra raça Collie e outras consideradas raças de Focinho fino.', 42.28, 23.39, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-lw3ah1lpyfzi61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F23597554876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
