INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398204686', 'Tinta Acrilica Economica Fosco Aveludado Anti Mofo Parede 3,6 Litros Escolha A Cor Colortexx Velluto', 'Tinta Avrílica Velluto econômica Colortexx É uma tinta de Fácil aplicação, excelente nivelamento e ótima cobertura. Sua principal característica é o acabamento aveludado, proporcionando um toque de seda. Possui uma ampla variedade de cores para se adequar ao seu perfil e projeto. Base indicada: Alvenaria, emboço e paredes acabadas. Acabamento: Fosco Aveludado Demãos: 2 a 3 demãos Rendimento: Galão 3,6L: Com diluição: Até 40m²/ demão Sem diluição: Até 70m²/ demão Lata 18l Com diluição: Até 200m²/ demão Sem diluição: Até 250m²/ demãoSecagem: Ao toque: Até 1 hora Entre demãos: de 2 a 4 horas Secagem completa: 12 horas Aplicação: Rolo de lã baixa anti respingo, trincha ou pincel Ambiente indicado: Áreas Internas Diluição: Até 20% de água O produto possui baixo odor.', 80.9, 41.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg3rmi4me1ad92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F22398204686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
