INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494293668', 'Loção tônica clareadora Nupill Vitamina C', 'Loção tônica clareadora Nupill Vitamina C Com a finalidade de estimular a inclusão de um ingrediente tão valioso no ritual diário de beleza das brasileiras, a NUPILL inovou mais uma vez e trouxe para o mercado a loção tônica clareadora Nupill Vitamina C. O produto contém ingredientes suaves que tonificam, revitalizam e uniformizam o tom da pele, além de reequilibrar o PH. Vantagens e benefícios: · Palmitato de Ascorbila: Fonte mais estável da Vitamina C - contribui para formação do colágeno e da elastina, estimulando a renovação celular, o que ajuda a prevenir o envelhecimento. Melhora a distribuição da melanina, pigmento que dá cor à nossa pele, suavizando e prevenindo manchas. · Potencializa a hidratação e luminosidade da pele. · Nano-tecnlogia - A molécula de vitamina C nano-encapsulada fica mais protegida contra oxidação e e perdas de sua propriedade garantindo 30% a mais de performance em relação à vitamina C comum. · Fórmula sem parabenos · livre de corantes · não testado em animais Resultado: Pele macia, limpa e suave pronta para receber o creme hidratante NUPILL Vitamina C com maior poder de tratamento e hidratação da pele. Modo de usar: 1. Use pela manhã e à noite, após limpar o rosto com mousse de limpeza ou sabonete líquido facial Nupill como parte de sua rotina de cuidado facial. 2. Aplique o produto com algodão, fazendo movimentos circulares e ascendentes. 3. Em seguida use o creme clareador antirrugas Nupill Vitamina C para uma pele com menos rugas e manchas.', 31.9, 31.9, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134201-7rdx4-md26qccl181238', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1584908418%2F23494293668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
