INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23996990327', 'Desodorante Roll On Nivea Protect e Care 50ml', 'O Desodorante Roll On Nivea Protect & Care promove toda a proteção e cuidado de Nivea que você já conhece, em um só desodorante. Garante 48 horas de proteção antitranspirante com o melhor do Nivea . Cuidado intensivo e proteção eficaz. Modo de uso: Deslize a esfera aplicadora sobre as axilas e espere secar. #html-body [data-pb-style="646BA64FA6E3F"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64FA6E53"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 23.56, 23.56, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmgfujm809u876', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23996990327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298946160', 'Esmalte Risqué Marromvilhoso 8ml', '#html-body [data-pb-style=XCHMN7P]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Esmalte Risqué Marromvilhoso 8ml é um tom marrom escuro cremoso que transmite elegância, força e modernidade. Ideal para quem ama cores sóbrias com personalidade, ele deixa as unhas com um visual sofisticado, perfeito para o outono/inverno ou para compor looks neutros e estilosos o ano inteiro. Com fórmula hipoalergênica, o esmalte proporciona alta cobertura, brilho intenso e secagem rápida, além de excelente durabilidade. O pincel com formato especial "U" facilita a aplicação, garantindo acabamento uniforme mesmo com poucas pinceladas. Modo de Uso: Agite antes de usar. Aplique sobre as unhas limpas e secas. Para melhor acabamento, use uma base antes do esmalte e finalize com extra brilho. Espere secar entre as camadas.', 8.65, 8.65, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-824hv-mfa7vbsfjxn3e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23298946160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494520235', 'Moldura Painel 2Din Fox Spacefox Crossfox Grafite', 'A Moldura VW Crossfox Spacefox é o complemento perfeito para o seu Fox, Crossfox ou Spacefox. Além de dar acabamento ao painel depois de instalar um player, ela possui modelos japoneses e chineses e pode ser usada em aparelhos de 2 Din. Seja personalizar o seu veículo Volkswagen ou substituir os detalhes já desgastados, com a moldura do painel Volkswagen você pode ter um visual moderno e exclusivo. Fabricada em plástico rígido, esta parte possui alta durabilidade, resistência e acabamento perfeito na cor preta, deixando o interior do carro mais elegante. Está disponível nas cores preto com acabamento fosco e grafite. É compatível com o Volkswagen: – Fox 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020. – Crossfox 2013, 2014, 2015, 2016, 2017, 2018. – Spacefox 2013, 2014, 2015, 2016, 2017, 2018.', 159.9, 159.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mfu2kf71l1jd83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F735686176%2F23494520235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
