INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44012662694', 'Só a gente sabe o que sente', 'Só a gente sabe o que sente é uma coletânea de crônicas que falam sobre assuntos que muitas vezes temos pouca ou nenhuma coragem de expressar uma representação daquelas conversas que temos com o teto do nosso quarto antes de dormir. Nestas páginas, Fred abre o coração e a intimidade, expondo pensamentos que estavam guardados no cantinho mais profundo de sua mente e que, até agora, poucos conheciam. Se você também sofre com as incertezas da vida, o medo de errar e os amores perdidos, encontrará nessas páginas uma companhia acolhedora e a certeza de que não está sozinho.', 52.89, 52.89, NULL, 'Books & Magazines > Books > Parenting & Family', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-mddn3yptch1q31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F44012662694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
