INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793175314', 'Sensor De Fase Ford Fiesta 2007 A 2013 Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Sensor de Fase Ford Fiesta 2007 a 2013 Gauss O sensor de fase da GAUSS é responsável por informar a posição do eixo do comando de válvulas. Essa informação, com conjunto com o sensor de rotação, permite que o carro identifique o momento exato para fazer a injeção e ignição do motor, garantindo um maior rendimento para o veículo. Observação: Os sensores de fase da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes Veículos: Ford Fiesta 2007 Ford Fiesta 2008 Ford Fiesta 2009 Ford Fiesta 2010 Ford Fiesta 2011 Ford Fiesta 2012 Ford Fiesta 2013 Especificações tecnicas do Veículo: Veículo: Fiesta Montadora: Ford Ano: 2007 a 2013 Especificação Tecnica - Sensor de fase: Cod Produto: Gs9004 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 195.99, 195.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kislpr6m4lc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22793175314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47501269485', 'Braço Bandeja Suspensão Traseira Jac J3 1.4 1.5 16v 2011-2015/ Hyundai Accent 1.5 12v 1994-1999 2911070U8010 5521022000', 'Garanta a segurança e estabilidade da suspensão do seu veículo com o Braço Bandeja da Suspensão Traseiro Greenparts, compatível com Jac J3 1.4/1.5 16v (2011 a 2015) e Hyundai Accent 1.5 12v (1994 a 1999). Fabricado em aço de alta resistência, este braço bandeja oferece durabilidade superior e excelente desempenho, essencial para uma condução segura e confortável. Aplicações: JAC J3 1.4 16V 2011 A 2015 JAC J3 1.5 16V 2011 A 2015 HYUNDAI ACCENT 1.5 12V 1994 A 1999 Especificações: Tipo: Braço Suspensão Eixo de montagem: Traseiro Referência: GPS063147 Marca: Greenparts EAN: 7908374431488 Números Originais 2911070U8010 5521022000', 219.9, 216.38, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-821d6-mgzh2o9twavf8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F47501269485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
