INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299227372', 'JUJUTSU KAISEN: VOL 11', 'JUJUTSU KAISEN: VOL 11 Pessoas comuns e humanos modificados tomam conta da plataforma de metrô da estação shibuya. Preso nesse ambiente cruel, gojou consegue dominar as maldições, mas não sabe que a intenção do inimigo é confiná lo! Enquanto isso, um aliado inesperado contata itadori, que se apressa para chegar até seu professor! Informações Adicionais Autor: GEGE, AKUTAMI Tipo de capa: Brochura Condição do Item: Novo Idioma: Indefinido Páginas: 192 Edição: 2021 ISBN-13: 9786559608065 ISBN-10: 6559608069', 52.68, 52.68, NULL, 'Hobbies & Collections > Collectible Items > Anime & Manga Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-822za-mi61lsep61vsab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22299227372', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210859722', 'Moletom Masculino Puma Com Capuz Essentials Lançamento Original', 'Descubra o conforto e estilo do Moletom Com Capuz Masculino Ess Colourblock da Puma, uma peça essencial para o seu guarda-roupa. Este moletom é perfeito para quem busca um visual moderno e despojado, sem abrir mão do conforto. Feito com uma combinação de algodão e poliéster, ele proporciona um toque macio e aconchegante, ideal para o uso casual, lazer e dia a dia. A tecnologia dryCELL garante o controle da umidade, mantendo você seco e confortável em qualquer situação. Além disso, o design com capuz e bolsos traseiros oferece praticidade e funcionalidade, tornando-o uma escolha versátil para diversas ocasiões. No Galpão dos Esportes, você encontra produtos 100% originais, com foco em qualidade e performance. Nossa loja, com mais de 300 m², oferece uma seleção cuidadosa das melhores marcas do mercado, sempre priorizando o atendimento especializado e uma experiência de compra única. Compre com confiança e tenha a certeza de estar adquirindo o melhor para a sua prática esportiva. ESPECIFICAÇÕES TÉCNICAS - Marca: Puma - Composição: Algodão, Poliéster - Tipo de roupa: Capuz - Gênero: Masculino - Linha: Originals - Material principal: Algodão - Modelo: Moletom Puma Com Capuz - Tipo de manga: Longa - Tipo de gola: Redonda - Com capuz: Sim - Com bolsos: Sim CARACTERÍSTICAS E BENEFÍCIOS - Controle da umidade com tecnologia dryCELL - Design moderno e funcional com capuz e bolsos - Conforto e estilo para o uso diário - Sustentabilidade com uso de materiais reciclados Adquira já o seu Moletom Com Capuz Masculino Ess Colourblock e eleve seu estilo com a qualidade e originalidade que só a Puma oferece. Não perca tempo, adicione ao carrinho e garanta o seu agora mesmo!', 599.85, 399.9, NULL, 'Men Clothes > Hoodies & Sweatshirts > Hoodies', 'https://cf.shopee.com.br/file/br-11134207-820l5-modz0s7yvgn94d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F58210859722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
