INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899445861', 'Nissin Galinha Caipira Miojo', 'Nissin Lámen Galinha Caipira é o sabor preferido e o queridinho dos consumidores, aquele que não pode faltar em casa. Refeição prática pronta em apenas 3 minutos e com 11 variações de sabores. Modo de Preparo: Micro-ondas: Coloque 450ml de água e o macarrão em um recipiente próprio para micro-ondas. Leve ao forno micro-ondas em potência alta por 5 min, interrompendo na metade do tempo para mexer. Retire do micro-ondas, misture o tempero e sirva em seguida. Fogão: Ferva 450 ml de água. Junte o macarrão e cozinhe por 3 minutos. Retire do fogo e misture o tempero.', 3.49, 3.49, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Noodles', 'https://cf.shopee.com.br/file/sg-11134201-82598-mqnelllo9ogd48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555102%2F22899445861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252561028', 'Kit 2 Pneus Michelin Energy Xm2+ 195/60 R15 88V', '** PRODUTO NOVO ** GARANTIA DE FÁBRICA DE 5 ANOS (somente por defeitos de fabricação, ficando invalida em caso de danos por acidentes, buracos na pista, mau uso e má instalação) ** EMISSÃO DE NF **O FATURAMENTO É REALIZADO APENAS PARA CONSUMO, SENDO VETADO O FATURAMENTO PARA REVENDA. **SOBRE O PNEU: Quem pensa em segurança e economia, enxerga no Michelin Energy XM2+ a solução ideal para o veículo. Produzido com sílica de última geração, o modelo tem vida longa e resistência para enfrentar os obstáculos do dia a dia. Com durabilidade 25% maior do que os concorrentes, o Michelin Energy XM2+ também é resistente às irregularidades do solo, absorvendo impactos mais fortes e choques para se adaptar melhor à pista e garantir uma rodagem mais suave e duradoura. O Michelin Energy XM2+ proporciona segurança acima da média para motoristas e passageiros, uma vez que a formação inovadora de sua banda de rodagem, com tecnologia Long Last Performance, oferece frenagens mais curtas, no seco e molhado, até o final de sua vida útil. Esse Pneu Pode Ser Aplicado Nos Seguintes Carros: Chevrolet: Astra, Vectra, Onix Citroen: C3, C3 Picasso Fiat: Idea, Marea, Punto, Tempra Ford: Focus, Mondeo, Fiesta Honda: Accord Hyundai: Elantra Kia: Carens, Cerato Lifan: Lf 620, X50 Mazda: 626 Nissan: Primera, Sentra Peugeot: 208 Renault: Laguna, Scenic Subaru: Impreza, Legacy Toyota: Corolla, Corolla Fielder, Corona Volvo: S40, S70, V40 VW: Fox, Up Garantia de fábrica: 60 meses', 1543.0, 1388.7, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-81zu8-miw39zmymn0h62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081431407%2F58252561028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
