INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199125144', '10 Disco De Corte 115mm X 1,0mm X 22,23mm DCV Vonder', 'Conteúdo da Embalagem: 10 Disco de corte. Proporciona cortes rápidos e menor geração de calor e rebarbas. Indicado para cortar aços e suas ligas, inclusive aço inox. Ideal para operações de corte que necessitam excelente acabamento (corte fino). Para manutenções e reparos leves. Não utilizar em serra mármore. Detalhes Técnicos Modelo:DCV Diâmetro do disco de corte:115 mm Espessura:1,0 mm (+/-3/64") Tipo de disco:Tipo 41 Diâmetro do furo:22,23 mm (7/8") Grão:G 60 Número de telas do disco:2 Rotação máxima do disco (rpm):13.300/min Segue norma(s):ABNT NBR 15230 e ABNT NBR 16245', 36.04, 28.48, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mg71z5l2imff17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23199125144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097996445', 'Pistola Elétrica Para Pintura Pev 900 220 V~ Vonder', 'Pistola elétrica para pintura PEV 900, 220 V~ VONDER Possui corpo e caneca em plástico que proporcionam maior leveza à pistola. Seus principais benefícios são a mobilidade e a praticidade, pois dispensa o uso de compressores, reguladores, mangueiras extensas, entre outros acessórios ou equipamentos complementares. Possui jato com 3 opções de ajuste (vertical, horizontal e circular), chave de ajuste do volume de tinta e sistema HVLP (alto volume e baixa pressão), proporcionando maior rendimento e menor desperdício de tinta. Devido a forma construtiva deste modelo, em que o motor é separado da pistola, consegue-se maior mobilidade, proporcionando, principalmente, menor fadiga ao operador. Indicada para aplicações de tintas sem pigmentos metálicos, como tintas automotivas, látex, vernizes e esmalte à base sintética e à base de água tanto profissionais quanto domésticas. Ideal para pintura de portas, portões, janelas, cadeiras, banquetas, brinquedos, artesanatos, entre outros. Aceita líquidos com viscosidade inferior a 90 DIN/S (acompanha medidor de viscosidade). Modo de utilização do medidor: tampar o furo inferior do medidor, encher o medidor com o líquido que será utilizado, liberar a saída do líquido pelo furo inferior e marcar o tempo. O líquido deve escorrer totalmente em 90 segundos ou menos. Caso exceda o tempo previsto, significa que o líquido é mais espesso do que 90 DIN/S, o que acarretará no travamento e queima da pistola. Especificações Técnicas: Modelo: PEV 900 Tensão (V~): 220 V~ Frequência (Hz): 50 Hz / 60 Hz Diâmetro do bico: 2,6 mm Vazão de tinta: 800 ml/min Material da agulha da pistola: Plástico Capacidade do reservatório de tinta: 700 ml Material da caneca da pistola: Plástico Material do corpo da pistola: Plástico Comprimento da mangueira.: 1,8 m Comprimento do cordão elétrico: 2,00 m Massa aproximada (peso) (kg): 3,2 kg Conteúdo Da Embalagem: 1 Pistola elétrica. Acompanha: 1 caneca plástica e 1 medidor de viscosidade.', 712.88, 516.85, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rene-m1y5tigv41of8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23097996445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
