INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092997796', 'Macacão Pezinho Liso Diversas cores', 'DESCRIÇÃO Seu bebê merece esse conforto! O Macacão Pezinho Liso com Ziper e protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Pezinho • Ziper • Protetor de Ziper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade Ou em Centímetros. O tamanho em centímetros é entre a gola do macacão e o pezinho. RN - 48cm P - 50cm M - 55cm G - 60cm GG - 63cm ESPECIFICAÇÕES 1 Macacão Liso com Zíper A mercadoria é composto somente pelos produtos da descrição acima.', 39.9, 32.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3yvcvdwnd4ld2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F22092997796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
