INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18668799578', 'Açucareiro Com Colher Pearl de Cristal Incolor Mesa Posta - Wolff', 'Açucareiro Wolff Pearl de Cristal Incolor com Colher 200ml ✨ Sofisticação e delicadeza para sua mesa! O açucareiro da linha Pearl da Wolff é perfeito para servir açúcar com elegância. Produzido em cristal de alta qualidade, possui design refinado e acompanha colher delicada, garantindo praticidade e charme em cada detalhe. Ideal para compor mesas de café, chá ou ocasiões especiais. 🔹 Destaques: ✔ Cristal resistente e de alta qualidade ✔ Design sofisticado e elegante ✔ Acompanha colher delicada ✔ Perfeito para café da manhã, chá ou brunch 📏 Especificações: • Material: Cristal • Cor: Incolor • Capacidade: 200 ml • Dimensões: 9,45 x 7,70 x 7,40 cm • Peso: 0,50 kg • Conteúdo: 1 açucareiro com colher ⚠️ Recomendações de uso: • Não utilizar em lava-louças • Não levar ao micro-ondas, forno, fogão ou freezer 🧼 Cuidados: • Lavar com detergente neutro • Utilizar esponja macia • Secar imediatamente • Não usar produtos químicos 🛍️ Garanta já o seu e leve mais elegância para sua mesa!', 46.0, 28.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7ratr-mad3y89dl62r56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F18668799578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
