INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20125924444', 'Guia para Afiar Faca Tramontina Angulador Profissional Protetora Anti Risco Amolar Afiar Pro fio', 'A linha Profio foi pensada em quem ama cozinhar. Por isso, oferece o Guia para Afiacao Tramontina Profio de Facas em Ceramica e ABS, que ira permitir que as suas facas estejam sempre afiadas para realizar aquela receita que voce tanto gosta, alem de garantir um corte preciso dos alimentos. A peca e produzida com protecoes de ceramica para evitar o desgaste do dispositivo e evitar que a pedra seja danificada, ABS um material resistente. Protecoes de ceramica para evitar o desgaste do dispositivo e evitar que a pedra seja danificada. Adequado para laminas retas inferiores a 3,5 mm de espessura, com comprimento maior de 15 cm e largura de 3 a 5 cm. Nao e indicado para facas com laminas curvas ou geometrias complexas e que serao utilizadas para impactos. A escolha certa para todos os momentos! MEDIDAS Altura 3 cm Largura 11 cm Comprimento 17,5 cm ITENS INCLUSOS 01 Guia para afiacao Tramontina GARANTIA 90 dias para vicios ou defeitos de fabricacao.', 78.9, 69.9, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-lujandj55t1270', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F310274254%2F20125924444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994038531', 'Chuteira Umbro Blast Society Preta e Amarela', 'Composição cabedal (parte superior): Material sintético Palmilha: Em EVA e removível; facilita na higienização Solado: PVC com micro travas fixas e multidirecionais, colado Forro: Revestimento em material têxtil acolchoado Cor predominante: Preto Lingueta: Fina e flexível Indicado para: Society Origem: Nacional Ajuste: Cadarço Peso aproximado: 690g o par nº 40', 134.9, 134.9, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7rata-ma18jkfm6ee4ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22994038531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197596387', 'Cascola Extra sem Toluol,Cola de Contato Transparente,1x195g', 'A Cola de Contato Cascola Extra sem Toluol atua de maneira incrível, mantendo suas propriedades físicas inalteradas mesmo exposta à água, não sofrendo inchamento. A cola é transparente e te dá uma secagem de 5 a 10 minutos, podendo ser feita a segunda aplicação em materiais porosos após apenas 20 minutos. Modo de Usar: Agite antes do uso.Limpe as superfícies a serem coladas e garanta que não haja óleo, tinta ou cera. Em materiais porosos, lixe antes da aplicação.Faça um teste preliminar com o material desejado para determinar a quantidade necessária de adesivos e compatibilidade de substratos.Aplique uma camada uniforme de produto em ambas as superfícies com uma espátula dentada e aguarde a secagem (5 a 10 min). Para materiais porosos, é indicada uma segunda aplicação após 20 min da primeira.Alinhe e junte as peças, exercendo pressão do centro para as bordas, evitando a formação de bolhas.Temperatura recomendada para a aplicação: entre 18ºC e 25ºC.• Ideal para couro, folha de metal, MDF, lambris, linóleo, compensado, HDF, cimento, borracha, fibras, laminados decorativos, metais, entre outros*• Não sofre inchamento, evitando desprendimento das peças• Temperatura recomendada para a aplicação: entre 18ºC e 25ºC• Fórmula: resistente à água• Tecnologia: sem Toluol• Cor: transparente• Formato: 1x195g*Não adere materiais à base de Polietileno, Polipropileno e PTFE (resina antiaderente).', 55.26, 33.9, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/sg-11134201-82589-mqxoo7n1a424c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1270088146%2F22197596387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
