INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998325097', 'Sanduicheira e Grill HQ 750W Antiaderente Inox HQ-SG001 220V', 'Sanduicheira e Grill HQ 750W Antiaderente Inox HQ-SG001 Seja para começar o dia com um sanduíche quentinho ou uma refeição rápida no fim do dia, a Sanduicheira HQ-SG001 é a companheira perfeita. Com 750W de potência, ela garante rapidez e praticidade, tornando o preparo simples e gostoso. O revestimento antiaderente facilita na hora de limpar, e a trava de segurança, junto com os pés antiderrapantes, traz ainda mais tranquilidade. Compacta e eficiente, a HQ-SG001 se encaixa no seu ritmo e na sua cozinha. Afinal, com a HQ, tudo fica mais fácil, para todos os momentos. Design Compacto: Ideal para cozinhas pequenas. Fácil de Usar: Luzes indicadoras de funcionamento e aquecimento. Segura e Estável: Trava de segurança e pés antiderrapantes. Limpeza Facilitada: Chapas antiaderentes. Funcionalidades: - Controle de temperatura automático. - Luz indicadora de funcionamento (vermelha/verde). - Trava de segurança para maior estabilidade. - Pés antiderrapantes. - Cabo de energia ajustável para armazenamento prático. Ficha Técnica Marca: HQ Cor: Inox Modelo: HQ-SG001 Voltagem: 127V ou 220V (Não é Bivolt) Frequência: 60Hz Potência: 750W Dimensões e Peso do Produto (AxLxP): 8,5x 22,1x 22 cm Peso:1,6Kg Garantia 01 Ano (Sendo 3 meses de garantia legal e mais 9 meses de garantia para defeito de fabricação).', 121.11, 83.16, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7repo-m2sazg23mlty2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1388709282%2F23998325097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
