INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45706664827', 'Esquadro Alumínio Fundido 16 Pol. 400mm MTX', 'Este esquadro é fabricado em alumínio fundido, oferecendo resistência e leveza para medições e marcações precisas em trabalhos de carpintaria, marcenaria e construção. Com 16 polegadas (400 mm), proporciona uma referência de ângulo confiável para cortes e alinhamentos. Projetado para uso profissional e hobby, o produto garante durabilidade e facilidade de manuseio por ser em alumínio fundido. A peça única e o acabamento MTX facilitam o transporte e armazenamento em caixas de ferramentas. Características: Modelo: 324749 Referência: 324749 Material: Alumínio fundido Tamanho: 16 pol. (400 mm) Quantidade: 1 PC Marca: MTX Benefícios: Leve e resistente, facilita o uso prolongado sem esforço. Dimensão de 400 mm ideal para trabalhos em madeiras e estruturas médias. Garantia de ângulo preciso para cortes e montagens. Acabamento durável que reduz desgaste com o uso. Fácil de transportar e armazenar por ser peça única. Conteúdo da embalagem: 1 esquadro de alumínio fundido 16pol. (400 mm) - MTX', 53.79, 41.98, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mlc3wak0ubya88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F45706664827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
