INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697998917', 'Esmerilhadeira Reta 6'' Erv 1050 220 V Vonder', 'Esmerilhadeira reta 6", ERV 1050, 220 V~, VONDER Possui interruptor com trava de segurança, punho ergonômico que proporciona mais conforto e capa de proteção que garante maior segurança para a operação. Ferramenta portátil que oferece mobilidade para seu trabalho. Indicada para desbaste de peças em geral. Utilizar somente rebolos vitrificados (marrom, verde ou branco) de 127 mm (5”) ou rebolos tipo resinóide (resina) de 152 mm (6”). Não podem ser utilizados outros acessórios como, escova de aço, ponta montada, disco de corte, boina para polimento e outros que não seja o especificado, ou ainda fora das medidas indicadas. Especificações: Modelo: ERV 1050 Tensão (V): 220 V~ Potência: 1.050 W Diâmetro do eixo: 16 mm Rosca do eixo: M 16 Diâmetro do eixo (com bucha ): 31,75 mm Rotações por minuto (rpm): 5.000/min Frequência (Hz): 50 Hz / 60 Hz Diâmetro do rebolo indicado: 152,4 mm x 25,4 mm Espessura do rebolo: Máxima 25,4 mm (1") Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Aceleração transmitida nas mãos - braços do operador - ah: 5,6 m/s² Massa aproximada.: 4,09 kg Recomendações de segurança (avisos/alertas): Utilize equipamento de proteção individual (EPI) adequado para cada tipo de trabalho. Segue norma: ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-3 Massa aproximada (peso) (kg): 4,09 kg Conteúdo da Embalagem: 1 Esmerilhadeira reta. Acompanha: 1 chave de boca, 1 capa de proteção, 1 par de escova de carvão.', 717.34, 541.25, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m32974is89udb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22697998917', NULL, NULL, '2026-07-28T02:11:31