INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894217241', 'Kit Creamy Skincare Gel de Limpeza Calming Cream Vitamina C (3 produtos)', 'Creamy Skincare Gel de Limpeza Calming Cream Vitamina C - Limpeza, Hidratação e Luminosidade Este Kit Contém Creamy Skincare - Gel de Limpeza 200ml: realiza uma limpeza profunda, sem ressecar. Enriquecido com 3 tipos de ácido hialurônico e ácido poliglutâmico, este gel purifica, hidrata e mantém a pele equilibrada, fresca e com toque suave. Creamy Calming Cream - Creme Hidratante Facial 40g: hidratação calmante e reparadora. Ideal para peles sensibilizadas, reduz vermelhidão, desconforto e fortalece a barreira cutânea. Perfeito após o uso de ácidos ou agressões externas. Creamy Vitamina C - Sérum Facial 30g: com textura leve e ação antioxidante, o sérum reduz manchas, melhora a luminosidade e previne o envelhecimento da pele sem pesar. Conselho de Aplicação Gel de Limpeza: aplique 1 pump sobre a pele úmida e massageie até obter uma espuma leve, enxaguando em seguida. Pode ser usado de 1 a 2 vezes ao dia. Calming Cream: aplicar sobre a pele completamente seca, de 1 a 2 vezes ao dia, espalhando até absorção completa. Reaplicar conforme desejado. Vitamina C: diurno e/ou noturno. Aplique 1 ou 2 pumps sobre a pele completamente seca, espalhando até absorção completa. Pode ser utilizada no rosto, pescoço e/ou colo, antes ou depois do creme hidratante. De manhã, recomenda-se a aplicação antes do protetor solar.', 468.85, 244.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rdx7-mc9ld28zddkice', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22894217241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
