INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16089600367', 'Jogo Cabo Vela Ignição Palio Siena Strada 96 A 2004 Bosch', 'Aplicação FIAT Palio 1.0/1.5 8V Alcool/Gasolina - 1996 até 2004 Siena 1.0/1.5 8V Alcool/Gasolina - 1998 até 2004 Strada 1.5 8V Alcool/Gasolina - 1998 até 2004 Conteúdo Da Embalagem 1 Jogo de Cabo de Vela de Ignição Tipo de Veículo para Carros Marca O Grupo Bosch é um líder mundial no fornecimento de tecnologia e serviços. A empresa emprega mais de 390.000 colaboradores em todo o mundo, que trabalham juntos para oferecer soluções inovadoras para casas, cidades inteligentes,mobilidade e indústrias conectadas. A empresa utiliza sua expertise em tecnologia de sensores, software e serviços para oferecer um produto de ótima qualidade para seus clientes. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 6 meses Valor referente ao jogo. Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 4047025317214 Código do Fabricante F00099C058 Combustível ÁLCOOL GASOLINA', 56.81, 56.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rblz-llwc7c6walaya3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F16089600367', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17462845511', 'Kit de Utensílios de Silicone com 5 Peças Verde - Oikos', 'Esse é o Kit de Utensílios de Silicone com 5 peças Verde da OIKOS. Atire a primeira pedra quem nunca arranhou uma panela! por isso gostamos muito de utensílios de silicone para o preparo de alimentos, ele escorrega pela panela toda sem deixar nenhum arranhão! e você ainda pode bater a haste para tirar o excesso que ficou, sem amassar a beirada dela. o silicone também facilita e muito a limpeza, já que sua superfície lisa não retém cheiro, não prolifera bactérias e ainda não conduz o calor provocado pela chama do fogão. a linha de utensílios da oikos te ajuda nas mais diversas aventuras culinárias sem te dar o bolo. Esse Kit é composto por: 1 UNIDADE - ESPÁTULA DE SILICONE REDONDA PEQUENA Comprimento: 20,8cm Largura: 4,2cm 1 UNIDADE - PINCEL DE SILICONE PEQUENO Comprimento: 20,6 Largura: 3,5cm 1 UNIDADE - ESPÁTULA DE SILICONE RETA PEQUENA Comprimento: 20,7 Largura: 4,2cm 1 UNIDADE - ESPÁTULA DE CONFEITEIRO DE SILICONE PEQUENA Comprimento: 24cm Largura: 2,5cm 1 UNIDADE - PEGADOR DE SALADA DE SILICONE PEQUENO Comprimento: 21cm Largura: 3,5cm', 65.9, 59.9, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-82633-mlej6kqudpfp79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F17462845511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204371291', 'Neutrogena Purified Skin - Gel de Limpeza Facial 150g BLZ', 'Gel de limpeza para peles mistas e oleosas. Neutrogena Purified Skin Gel de Limpeza Facial faz limpeza purificante sem deixar a sensação de ressecamento. Gel de Limpeza Purified Skin Neutrogena Facial possui textura suave, reduz a oleosidade e proporciona frescor. Sua formulação com Ácido Glicólico promove a renovação celular da pele desde o primeiro uso. Com ele, seu rosto fica livre de impurezas e com aspecto saudável. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 56.9, 56.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-8261e-mk4020t5m5tw92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204371291', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254308466', 'Latika Whitening FPS 44 Bege Médio - BB Cream 30g', 'BB cream para todos os tipos de pele. Latika BB CreamWhiteningajuda a uniformizar o tom e a textura, reduz marcas e hidrata com um acabamento natural. O BB Cream Latika oferece proteção contra os raios solares, controla a oleosidade sem deixar aspecto oleoso por ser oil-free. E também é vegano e livre de Parabenos. Como usar: Aplique o BB Cream Latika sobre a pele com a ponta dos dedos ou com o auxílio de um pincel de maneira uniforme. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 94.9, 94.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mlm6dc3jmp73a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254308466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198228878', 'Fantasia Infantil da Moana 2 Carnaval pra Menina Vestido Havaiana Polinésio com Colar', 'Itens inclusos: 01 - Vestido Infantil inspirado na Princesa dos Mares 01 - Colar do Coração de Te Fiti Dimensões do produto: P:Numeração de roupa 2 a 4, para crianças que tenham até 99 cm de altura, dos pés a cabeça. M:Numeração de roupa 5 a 8, para crianças que tenham de 100 a 119 cm de altura, dos pés a cabeça. G:Numeração de roupa 9 a 12, para crianças que tenham de 120 a 140 cm de altura, dos pés a cabeça. Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações Técnicas Material:Fantasia 100% poliéster. Cor: Multicolorido Produto:Novo, na embalagem. Produto a pronta entrega! Transforme a brincadeira em uma grande jornada pelos mares com a Fantasia Infantil da Princesa dos Mares! Inspirada na corajosa navegadora, essa fantasia permite que sua pequena viva momentos mágicos de aventura e descobertas. O vestido reproduz fielmente os detalhes do traje tradicional polinésio da personagem, com uma parte superior branca decorada com padrões tribais em amarelo e vermelho. A saia vermelha traz estampas geométricas e uma barra com franjas, criando um visual autêntico e encantador. Para completar o look, o colar do Coração de Te Fiti acompanha o conjunto, proporcionando um toque especial à fantasia. O vestido é confeccionado em poliéster de alta qualidade, sendo confortável e leve, ideal para longos períodos de uso em festas, Carnaval e até mesmo para sessões fotográficas temáticas. Possui ajuste em laço nas costas, permitindo um caimento perfeito e confortável. Leve e Confortável Não Desbota Seca Rápido Estampa de Alta Qualidade', 69.99, 69.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-7rd53-m6nzpfmi4tp08e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F23198228878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27043700212', 'Extensão Flexível Articulada Para Bits 1/4 Parafusadeiras - Titanium', 'A Super Extensão Articulada Flexível Para Bits 1/4 - 295 mm, pode ser utilizada como um simples extensor manual, ou com uma parafusadeira elétrica, a sua ponta é um porta bits magnético podendo ser conectado a qualquer tipo de bits ou ponteiras como (fenda, philips, torx, allen, soquetes, etc.) desde que seu encaixe sejam de 1/4'', seu uso é indicado para computador, armários elétricos, móveis, aparelhos, motos, bicicletas, carros e qualquer situação onde o espaço seja tão estreito. Qualquer lugar que uma chave de fenda comum não pode trabalhar.Não acompanha bits ou parafusadeira, (a foto é somente demonstrativa)TERMOS DE COMPRA1 - Entrega via Shopee por transportadora.2 - Prazo de Postagem é de até 48hs, validos apenas para dias úteis após a compra.3 - O prazo de entrega informado no ato da compra é apenas um prazo estimado e não leva em consideração o prazo de postagem (item 2), podendo haver atrasos por parte da transportadora.O prazo de entrega informado é feito pela Transportadora da Shopee e não por nós. Faça o acompanhamento da sua compra para se certificar que nós postamos o seu produto no prazo informado no item 2.4 - Todas as imagens são meramente ilustrativas;5 - Caso o endereço esteja incorreto, o produto irá voltar e o pagamento será devolvido.6 - É importante que se for necessário escolher alguma variação, escolha o Tamanho/ Modelo / Cor / Voltagem imediatamente7 - Nossos produtos são originais e acompanham nota fiscalGarantia de 90 dias pelo fabricanteImagens meramente ilustrativas', 39.99, 22.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhkw1g3e8hdv9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshop