INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23491745412', 'Kit Rolamento Roda Traseira Volkswagen Kombi 1978 A 2014', 'Este anúncio contem: 2 x Rolamentos / 2 x Retentor / 1 x Cupilha / 1 x Graxa Aplicável nos seguintes veículos: Montadora: Volkswagen; Veículo: Kombi; Motor: 1.4, 1.6; Ano de fabricação: 1978, 1979, 1980, 1981, 1982, 1983, 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014. Sobre a marca: A Indústria Metalúrgica Alli – IMA nasceu em 1973 produzindo semieixos e cubos de roda. Para fortalecer sua presença no mercado nacional, incorporou outras peças em sua produção, como trizeta, tulipas e junta homocinética para veículos leves e pesados. Em 1995 já éramos referência no mercado de reposição de peças automotivas. Buscando sempre antecipar as necessidades de nossos clientes, a IMA investiu pesado na construção de um parque fabril com mais de 10 mil m2. Com isso, hoje em 2022 a IMA continua líder no mercado, com um portfólio completo de produtos na linha de reposição automotiva. A IMA Indústria Metalúrgica Alli, tem como comprometimento desenvolver, produzir e comercializar peças automotivas para o mercado de reposição com alta qualidade e segurança. Sobre nossa empresa: Estamos há mais de 30 anos no mercado de autopeças, buscando sempre a satisfação dos nossos clientes. Trabalhamos com as melhores marcas do ramo automotivo e aqui você encontrará as melhores peças para seu veículo, e contará com qualidade e o melhor atendimento. Nossos produtos são todos rigorosamente conferidos e embalados para que chegue até você da melhor maneira. A nossa empresa comercializa apenas produtor originais de fabricantes certificado pelo ISO 9001. Dúvidas frequentes: Nós trabalhamos apenas com produtos novos e com garantia. Nossos produtos são de qualidade original, respeitando todas as regras do fabricante. Produto a pronta entrega. Seus produtos serão enviados em até 24 horas úteis.', 186.11, 171.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj33uni2zibjba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F615444977%2F23491745412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497931903', 'Bicicleta Viking X Tuff25/30 Freeride Aro 26 Freio a Disco 21 Velocidades Preto Rosa', 'Bicicleta Viking X Tuff25/30 Freeride Aro 26 Freio a Disco 21 Velocidades Preto Rosa Foi projetada ;para quem quer uma bike de personalidade e estilo inigualável. Ela oferece ao ciclista quadro diferenciado e design arrojado e ;exclusivo. Com qualidade, ela vem equipada de com ;21 velocidades, permitindo ao ciclista a escolha da marcha ideal de acordo com o local. O design moderno pode ser observado no quadro da bike e os pneus são confeccionados em MTB com aro 26, garantindo segurança total a cada manobra em qualquer tipo de terreno. Especificações Técnicas: - Marca: Viking - Coleção / Sortimento: 2021 - Idade recomendada: Juvenil/Adulto - Gênero: Unissex - Aro: 26 - Quadro: Aluminio - Marcha: 21 Marchas - Garfo: Suspensão - Guidão: Aço carbono MTB - Freios: Disco - Rodas: X-wild - Cambios: Importados - Manoplas: MTB - Corrente: Index - Selim: MTB - Trocador: Rapid fire importado - Pedivela: Importado - Pneus: MTB 26" - Pedal: Plástico MTB - Conteúdo da Embalagem: 1 bicicleta', 1549.0, 1549.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1vt1hfkyfpk61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F18497931903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
