INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197556748', 'Jogo da Memória Sombras e Formas II em MDF com 32 Peças para Crianças a Partir de 3 Anos Xalingo - 17654', 'Com foco no bem-estar e no desenvolvimento infantil, a Xalingo Brinquedos criou uma linha voltada para crianças que precisam ampliar e desenvolver habilidades como concentração, criatividade, memória e autocontrole. O Jogo da Memória Sombras II, é um brinquedo que possibilita às crianças a desenvolverem a atenção e a percepção visual, além de distinguir semelhanças e diferenças. É composto por 32 peças grandes em madeira reflorestada, sendo possível identificar os animais e suas respectivas sombras, formando os seus pares. Indicado para crianças a partir dos 3 anos. Características: - Marca: Xalingo - Modelo: 1765.4 *Imagens Meramente Ilustrativas Características Principais: - Amplia e desenvolve habilidades como concentração, criatividade, memória e autocontrole - Possibilita às crianças a desenvolverem a atenção e a percepção visual, além de distinguir semelhanças e diferenças Especificações: - Material: Madeira Reflorestada - Dimensões (Tamanho do quadro): 24x8x15 cm - Quantidade de Peças: 32 - Idade Recomendada: A partir dos 3 Anos Conteúdo da Embalagem: - 1x Jogo da memória com 32 Peças em Madeira Reflorestada', 48.13, 41.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-lvm2nbchtr90b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22197556748', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
