INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594525924', 'Box com 3 Livros de Graciliano Ramos | Vidas Secas | Angustia | São Bernardo', 'Nascido no coração do sertão nordestino, em Quebrangulo, Alagoas, Graciliano Ramos possibilita ao leitor de sua obra uma compreensão diferenciada da realidade enfrentada em uma terra fustigada pela seca e assolada pela pobreza. Com personagens e situações complexas, insinuações e denúncias da crueldade e desigualdade das quais deriva o sofrimento retratado em seus livros, Graciliano mantém ainda hoje sua relevância, 71 anos após sua morte. Mais do que forçar seu leitor a encarar um mundo à parte, o escritor alagoano revela facetas da natureza humana pouco reconhecidas, mas presentes em cada um. Ler Graciliano é compreender melhor a si mesmo e ao Brasil, nussas origens e onde nos encontramos agora. É abrir os olhos para novos modos de enxergar a realidade, e nos mune de novas armas para cufrentá-la 14x21cm', 39.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mfp9efwrz9xl86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22594525924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54657502638', '52 Reflexões sobre Como desfrutar a vida e o trabalho | Dale Carnegie', 'EQUILÍBRIO, PROPÓSITO E GRATIDÃO: TRÊS PILARES DE UMA VIDA PLENA. Inspirado em Como desfrutar a sua vida e o seu trabalho, de Dale Carnegie, este livro traz 52 reflexões transformadoras sobre como encontrar alegria nas tarefas diárias, serenidade nas dificuldades e realização nas pequenas coisas. Com delicadeza e sabedoria prática, Sam Buttler mostra que felicidade não é destino, mas modo de viver, e que o sucesso nasce do entusiasmo e da simplicidade. Aprenda a viver com leveza, propósito e alegria: um dia, uma semana, uma reflexão de cada vez. 15x22cm 96 Páginas', 16.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mm3is8ozmoe900', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F54657502638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
