INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13275200533', 'Canela Vera 6 Cm Aa', 'Nome Científico: Cinnamomum cássia Família: Lauraceae Parte Utilizada: Casca Sinônimo Popular: Canela Pau Origem: Indonésia A canela vera 6 cm refere-se a paus de canela de alta qualidade, com cerca de 6 cm de comprimento, originados da casca interna da árvore de caneleiro. Tem um sabor doce e aromático, sendo ideal para dar sabor a doces, bolos, compotas, chás e até pratos salgados. Sua forma em pau conserva melhor o aroma e sabor, sendo utilizada em infusões ou moída conforme necessário. Ingredientes: Canela Vera. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 32.25, 32.25, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-820lo-mo136v49aby8e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F13275200533', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
