INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099542907', 'Jogo Educativo Alfabeto Casa Mágica da Gabby Mimo Toys - 2156', 'Este Jogo do Alfabeto é divertido e educativo. Cada peça do jogo representa uma letra do alfabeto e possui um personagem ou objeto estampado, cujo nome começa com a letra correspondente. O jogo do alfabeto mimo casa da gabby combina aprendizado e diversão, oferecendo uma experiência de aprendizado significativa e cativante para as crianças. Além disso, é seguro, fabricado com materiais não tóxicos e resistentes para resistir ao temperamento vigoroso das crianças. Prepare-se para ver seus pequenos brilharem enquanto se divertem com a Gabby! O objetivo do jogo é encaixar todas as peças corretamente, formando o alfabeto. - Indicado a partir de 4 anos - Composição: Papel Cartonado, Plástico - Dimensões Aproximadas da Embalagem: 20cm x 5 cm x 30cm (Altura x Largura x Comprimento) Características: - Marca: MIMO TOYS - Modelo: 2156 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Jogo do Alfabeto da Casa Mágica da Gabby jogo do alfabeto - jogo do alfabeto gabby - jogo educativo - jogos infantis', 41.0, 37.0, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-m1fvrc2ii4zt48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F19099542907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
