INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197995541', 'Jogo Kit 4 Pratos Raso 25cm Porcelana Tramontina Arbo Jantar Refeição', 'KIT 4 Pratos Porcelana Tramontina Raso 25cm Arbo – Elegância Natural para Sua Mesa Complete sua mesa com o Kit 4 Pratos Rasos Tramontina Arbo 25cm, uma opção sofisticada e funcional para servir refeições principais com estilo. Produzidos em porcelana de alta qualidade, os pratos apresentam um design natural e elegante que valoriza qualquer composição de mesa posta. Destaques do Produto: Material de Alta Qualidade: Fabricados em porcelana premium, são resistentes, duráveis e sofisticados. Design Exclusivo: Inspirado na natureza, o modelo Arbo traz um toque único e refinado para sua mesa. Dimensão Perfeita: Com 25 cm de diâmetro, são ideais para servir refeições principais de forma elegante. Praticidade: Compatíveis com micro-ondas e lava-louças, oferecendo mais comodidade no dia a dia. Especificações Técnicas: Material: Porcelana Diâmetro: 25 cm Modelo: Arbo Benefícios: Combina sofisticação e funcionalidade. Alta resistência, ideal para uso diário ou ocasiões especiais. Design que harmoniza com diferentes estilos de mesa posta. Escolha o Kit 4 Pratos Rasos Tramontina Arbo 25cm para elevar a elegância das suas refeições, garantindo beleza e qualidade em cada detalhe!', 149.9, 149.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rfgr-m3nxa2uo2wqz51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F20197995541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594812369', 'Tênis Infantil Morango do Amor Vermelho Pampili', 'O Tênis é a escolha ideal para as meninas que adoram unir conforto e doçura com estilo e um toque de fofura! Com design moderno e versátil, ele traz um visual apaixonante e solado caixa super leve, que garante estabilidade e liberdade para brincar o dia todo. O charme especial fica por conta do detalhe bordado e pingente removível em formato de morango do amor, um doce ícone que é a cara da Pampili e encanta em cada detalhe. O pingente também pode ser usado como acessório! Ideal para looks casuais ou aquele passeio especial, possui fechamento prático com material aderente e cadarço elástico. Forro macio e palmilha confortável. Solado com identificação em braile para ajudar as meninas cegas ou com baixa visão. Aposte! Perfeito para escola, passeios ou momentos de lazer, esse tênis combina com roupas leves e casuais.', 239.9, 167.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lk-mm22jcm6ymf81b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F23594812369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
