INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698474893', 'Kit 4 Alto Auto Falantes JBL 6TRMS80 6 Polegadas Boca 6x6 320W RMS VÁRIOS CARROS', 'A linha Multisystem, reconhecida por seu alto desempenho em som interno, apresenta seu primeiro Auto Falante 6'''' JBL Multisystem. , atualização de ID alinhado com produtos globais responde na região dos graves e subgraves e compõe sistemas de som interno , atuando em conjunto com alto-falantes multi-vias para dar mais corpo ao som e pressão sonora. Com excelente acabamento e visual arrojado, além de sua excepcional durabilidade e fidelidade sonora, entrega ao consumidor o melhor custo-benefício do mercado. CONTEÚDO DA EMBALAGEM: • - 04x Auto Falante 6'''' JBL Multisystem. • - 01x Manual. • - 01x Certificado de Garantia. COMPATÍVEL COM : • Onix (todos os anos) • S10 (todos os anos) • Equinox (todos os anos) • Spin (todos os anos) • Montana (todos os anos) • T-Cross (todos os anos) • Voyage (todos os anos) • Polo Hatch e Sedan (todos os anos) • Gol G2, G3, G4, G5, G6, G7, G8, G9 (todos os anos) • Golf (todos os anos) • Jetta (todos os anos) • Siena (todos os anos) • Ecosport (todos os anos) • Honda Civic (todos os anos) • Honda City (todos os anos) • Honda Fit (todos os anos) • Honda HR-V (todos os anos) • Corolla (todos os anos) • Hilux (todos os anos) • Etios (todos os anos) • Tucson (todos os anos) • Creta (todos os anos) • Hb 20 (todos os anos) • Nissan Kicks (todos os anos) • Nissan Sentra (todos os anos) • Nissan Versa (todos os anos) CARACTERÍSTICAS: • - JBL Multisystem • - Alto desempenho em som interno • - Graves e subgraves • - Visual arrojado • - Tweeter dinâmico ESPECIFICAÇÕES TÉCNICAS: • - Impedância Nominal: 4 Ohms • - Potência RMS: 80 WRMS (CADA) • - Potência RMS: 160 WRMS (PAR) • - Potência RMS: 320W RMS (KIT) • - Resposta de Frequência do Sistema: 60Hz – 20000 Hz • - Sensiblidade: 87 dB • - Polegadas: 6’’ • - Vias: 3 • - Cone: PP', 649.99, 579.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9orvxesq6gp33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F23698474893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
