INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53150988359', 'Bicicleta Caloi Expert R20 A25 1V Aro 20 Guidão BMX Cor Preta', 'A Bicicleta Caloi Expert R20 A25 é indicada para jovens ciclistas de 7 a 9 anos com altura entre 1,15m e 1,40m. Ideal para uso recreativo e exploração de diferentes terrenos. DETALHES TÉCNICOS - Modelo: 005197.19007 - Quadro: Aço aro 20 com suporte para freios V-brake - Garfo: Aço rígido - Aros: Alumínio VZAN P04, parede dupla - Cubos: Aço - Raios: Zincados - Pneu: 20x175 - Pedal: Plástico - Pedivela: Monobloco em aço, 140mm - Movimento central: Monobloco 45mm - Corrente: KMC X1 - Cassete: Roda livre 01 velocidade, 20D - Passadores: Manopla em PVC - Guidão: Aço BMX - Suporte de guidão: Aço - Manoplas: Plástico - Movimento de direção: Padrão - Freios: V-brake de aço - Manete de freios: Plástico - Selim: Caloi infantil - Canote do selim: Aço 22,2x280mm - Dimensões do produto: 138x56x83cm - Dimensões do produto embalado: 116x21x60cm - Peso bruto: 13,8kg - Peso líquido: 11,9kg - Capacidade máxima suportada: 37,5kg CARACTERÍSTICAS - Marca: Caloi - Modelo: 005197.19007 - Indicado para uso recreativo e exploração de terrenos diversos - Estrutura resistente em aço - Guidão tipo BMX para maior controle - Freios V-brake de aço para maior segurança CONTEÚDO DA EMBALAGEM - 01 bicicleta Caloi Expert na cor preta A25 aro 20 1V', 1081.0, 953.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mgqosmo9aolj81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F53150988359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23736699733', 'Pneu Technic SPORT R ( 80-100-18 = ( 2.75-18 42P TL ) USO SEM CÂMARA Dianteiro Titan / YBR / CBX 150 / CBX 200 / YES 125', 'Certificado Inmetro- Nº 08440-12/2021 *imagens meramente ilustrativas *não trabalhamos com pneus remold, apenas 100% novos com garantia. Identificação 80/100-18 Sport R Medida 80/100 MarcaTechnic Aro18 Índice de Velocidade P (150km/h) Índice de Carga 42 (150 Kg por Pneu) Modelo Sport R Largura (mm) 2.75 Tipo Convencional Garantia 3 Meses (Loja) - 1 Ano (Fabricante) Uso de Câmara Não ² Descrição A TECHNIC é uma empresa 100% brasileira que responde pela fabricação e distribuição nacional dos pneus novos para motocicletas da marca TECHNIC. Empresa com mais de 25 anos no mercado, com sede própria e instalações industriais na cidade de Santo André/SP. AplicaçãoTITAN / YBR / CBX 150 / CBX 200 / YES 125 1) O produto apresentado pode sofrer alteração de característica, estando sujeito também à alteração de preços, sem necessidade de prévio aviso. 2) O uso sem câmara dependerá da moto e roda. Somente para rodas de liga leve certificadas, com troca de bico e demais ajustes necessários para o uso correto do pneu. Largura:2.75 Aro:18', 184.81, 184.81, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7qvev-lgfjet1o45eeb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F23736699733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19677234402', 'Rede Capacete 45 X 45 Vermelha', 'Descrição; Rede Elástica Aranha Para Moto Capacete 45x45cm Elásticos em rede, capa de polipropileno e interior de látex ou câmara de pneu, excelente resistência e durabilidade. Desenvolvida para o transporte de objetos nos bagageiros de motocicletas, bicicletas, em porta-malas de carros, camping e também de uso domésticos. Aplicação; Indicada para o transporte de capacete e de objetos nos bagageiros de motos, bicicletas, e porta-malas de carros, Interior; Borracha vulcanizada. Revestimento; Fios de polipropileno de alta resistência Garantia 3 meses defeito fabricação Foto Ilustrativa', 35.56, 35.56, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/sg-11134201-7qveh-lggolxfoth840d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F19677234402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294489572', 'BROCA PARA CONCRETO, 6 X 160MM, ENCAIXE SDS PLUS, 1PC // MTX', 'A Broca de Concreto SDS PLUS é projetada especificamente para ser instalada em um martelo perfurador, permitindo a execução de furos em concreto, pedra e tijolo com eficácia notável. Esta ferramenta é reconhecida pela sua capacidade excepcional de lidar com as tarefas mais desafiadoras, graças à sua placa de corte feita de liga de carboneto de tungstênio VK8. A dureza impressionante de 80-90 HRC da placa de corte assegura cortes precisos e duradouros, destacando-se como um recurso essencial para profissionais que demandam o máximo em desempenho de perfuração. Vantagens: Instalação e Fixação Ágeis: O sistema de encaixe SDS Plus facilita uma instalação rápida e uma fixação extremamente segura da broca, características indispensáveis para maximizar a eficiência e estabilidade durante operações de perfuração. Durabilidade Sob Cargas Elevadas: A construção em aço de liga com adição de cromo na parte de trabalho da broca é projetada para resistir às cargas elevadas encontradas durante a perfuração com impacto, garantindo uma longa vida útil mesmo sob uso intenso. Perfuração de Precisão: Equipada com uma placa de corte que possui uma cabeça centralizadora, esta broca mantém sua trajetória com precisão durante o trabalho. Isso não só melhora a qualidade dos furos realizados, mas também prolonga a vida útil da ferramenta ao evitar desvios que podem causar desgaste irregular. Minimização de Vibrações: A área de seção transversal ampliada do corpo da broca é cuidadosamente projetada para reduzir as vibrações durante a perfuração. Isso não apenas aumenta o conforto do usuário, mas também diminui o risco de quebra da broca, melhorando a segurança geral do trabalho. Produtividade Aprimorada: A presença de uma espiral dupla reforçada otimiza a remoção de detritos, como lama, reduzindo a carga sobre a broca e aumentando significativamente sua produtividade. Este design eficiente é especialmente valioso em operações de perfuração que exigem a rápida evacuação de material para manter o progresso constante. A Broca de Concreto SDS PLUS é uma solução de alta qualidade e eficiência para profissionais que necessitam de uma ferramenta confiável e durável para a perfuração em materiais duros. Com sua placa de corte de liga de carboneto de tungstênio VK8 de alta dureza, esta broca garante cortes precisos e duradouros, tornando-a uma escolha excepcional para uma ampla gama de aplicações de perfuração.', 11.35, 11.35, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mfjvj54god1nf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F23294489572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697245510', 'Galliprant 60 mg Elanco para Cães - 7 Comprimidos', '- Trata a dor e inflamação associadas à OA; - Desenvolvido para levar bem-estar, não oferece riscos à saúde; - Realiza a manutenção das funções gastrointestinais, renais e hepáticas; - Os comprimidos são palatáveis e sulcados, podendo ser divididos em partes iguais; - Previne a degeneração da cartilagem, instabilidade articular e a redução da mobilidade. * Consulte sempre o Médico Veterinário de sua confiança para o uso apropriado deste produto. Leia a bula ou informações descritas na embalagem. Detalhes O Anti-Inflamatório Elanco Galliprant 60 mg para Cães apresenta um exclusivo modo de ação, é antagonista seletivo do receptor EP4, da classe dos piprants, que é responsável por mediar a dor e a inflamação associadas à osteoartrite. Permite melhor mobilidade nos exercícios físicos, aprimorando a força e a postura, facilitando a perda de peso. Dicas Especiais O Anti-Inflamatório Elanco Galliprant 60 mg para Cães deve ser administrado por via oral, com ou sem alimento, uma vez ao dia não excedendo a dose diária. Não há período máximo de duração do tratamento, sendo recomendado monitoramento do Médico Veterinário. Contraindicação: Cães com hipersensibilidade ao princípio ativo do produto e ao palatabilizante fígado de porco. Composição Cada 100 mg contém: Gapriprant 8 mg Excipiente q.s.p 100 mg', 156.3, 137.6, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820lm-mnn0fe5faw3kd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F18697245510', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697622043', 'Aurivet Pomada Otológica Vetnil para Cães e Gatos - 13 g', '- Ação efetiva contra vários agentes que causam otites em cães e gatos; - Promove anestesia local, aliviando a dor no ouvido; - Combate os sintomas clássicos da inflamação (calor, rubor, dor) suprimindo o prurido e a irritação nos condutos auditivos. * Consulte sempre o médico Veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes A Suspensão Oleosa Otológica Aurivet Vetnil é uma solução que associa Gentamicina, Betametasona, Clortrimazol e Benzocaína, apresentando uma combinação perfeita para o tratamento das otites nos pequenos animais. A associação de princípios ativos de sua fórmula promove ação efetiva contra vários agentes que causam otites em cães e gatos. Dicas Especiais Produto de uso tópico. - Cães com até 15 kg de peso: Instilar 4 gotas no ouvido, 2 (duas) vezes ao dia, por 7 dias consecutivos. - Cães com mais de 15 kg de peso: Instilar 8 gotas no ouvido, 2 (duas) vezes ao dia, por 7 dias consecutivos. - Gatos: Instilar 4 gotas no ouvido, 2 (duas) vezes ao dia, por 7 dias consecutivos. É importante massagear o ouvido externo após cada aplicação para garantir a perfeita distribuição do medicamento. O tratamento deve ser mantido 48 horas após o desaparecimento dos sintomas. Deve ser feita a limpeza dos ouvidos para que o tratamento se torne eficaz. Não há relatos de efeitos colaterais e/ou reações adversas aos componentes da fórmula. Composição', 144.68, 99.9, NULL, 'Pets > Pet Grooming > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rccr-lrb1m67ejg8b93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F20697622043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697795428', 'Kit 3 Unidades Brinca Dent One Brinquedo Osso Bamboo Sabor Bacon - MyPetOne', 'Kit 3 Unidades Brinca Dent One Brinquedo Osso Bamboo Sabor Bacon - MyPetOne - Ecológico; - Super resistente; - Indicado para cães; - Para todos os portes; - Fibra natural de bambu: - Ajuda na remoção de tartaro; - Auxilia na limpeza dos dentes; - Imagem meramente ilustrativa, cores e tons variados. É importante lembrar que nenhum brinquedo é 100% indestrutível e a brincadeira precisa ser monitorada. Detalhes Feito com fibra natural de bambu, o Kit 3 Unidades Brinca Dent One Brinquedo Osso Bamboo Sabor Bacon - MyPetOne, possui um sabor de bacon que ajuda a entreter seu peludo e auxilia na limpeza de seus dentes e de possíveis tártaros. Além disso mantém seu pet mais tranquilo e menos ansioso. Dicas Especiais O Kit 3 Unidades Brinca Dent One Brinquedo Osso Bamboo Sabor Bacon - MyPetOne apesar do gostinho de bacon não é comestível! Mantenha o brinquedo sempre limpo pois, seu cão está sempre a colocá-lo na boca. Importante Os brinquedos são recursos mais simples, barato e prático para proporcionar bem-estar físico e mental aos animais. Os brinquedos são instrumentos importantes no controle da ansiedade e instintos do seu peludinho. Destruir os brinquedos faz parte de um comportamento saudável, desde que seja supervisionado para que não engulam pedaços e se machuquem. É importante sempre verificar se o brinquedo escolhido está de acordo com o porte do seu pet e resistente o suficiente para ele. Indicação: Cachorros Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: Plástico, Polipropileno, Polipropileno, Homopolímero Apresentação: Tam. P; Tam. M, Tam G.', 99.99, 44.99, NULL, 'Pets > Pet Accessories > Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m29y87iyotsm62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F20697795428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098131341', 'Tampo Balcão 80Cm Henn Nature', 'Tampo Para Balcão 80 Cm Henn Nature Tampo para Balcão 80 cm Henn A Coleção une o que há de mais conceitual em tendências de design e soluções inteligentes, permitindo a versatilidade necessária para montar a cozinha dos seus sonhos. Características: Modelo: C904-23 Pintura: UV Caixa: MDF 25mm Dimensões: Altura: 2.5 cm largura: 80 cm Profundidade: 53.5 cm Peso: 8 kg Garantia do fornecedor de 3 meses.Cor: Cor', 149.9, 149.9, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rcdo-m6cpyh2gqtuf76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F18098131341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205525173', 'Lanterna Traseira Corsa Hatch 4 Portas 2000 2001 A 2009 Fume', '🚘 Lanterna Traseira Chevrolet Corsa Hatch (4 Portas) 2000 a 2009 – Fumê ✨ CARACTERÍSTICAS: Produto Novo: Ótima qualidade com excelente padrão de acabamento, ideal para reposição ou renovação do visual do seu carro. Visual Moderno: Acabamento Fumê, trazendo um toque esportivo e diferenciado para a traseira do veículo, sem perder a elegância. 🖤 Material Premium: Lente fabricada em acrílico injetado de alta durabilidade, resistente ao desbotamento solar e a pequenos impactos. Segurança Noturna: Garante excelente propagação e nitidez da luz nas sinalizações de freio, seta, ré e lanterna. ✔️ 🔧 ESPECIFICAÇÕES TÉCNICAS: Modelo: Fumê. Material da Lente: Acrílico automotivo de alta resistência. Carcaça: Ultra rígido injetado com encaixes de alta precisão. Encaixe Sob Medida: Desenvolvido exclusivamente para o alinhamento perfeito na carroceria do modelo Hatch de 4 portas. 🚗 COMPATÍVEL COM OS MODELOS (Corsa Classic / Wind / Super Hatch 4 Portas): Chevrolet Corsa Hatch 4 Portas 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008 e 2009 (Atenção: Compatível apenas com o modelo de 4 portas da geração G1/Classic; não serve no modelo de 2 portas ou no Novo Corsa Frente Montana). ⚠️ IMPORTANTE: Lado do Produto: Verifique o lado desejado (Motorista ou Passageiro) antes de finalizar a compra. Instalação Profissional: Recomendamos que a montagem seja feita por um profissional especializado para garantir o alinhamento correto e a vedação perfeita contra água e poeira; não nos responsabilizamos por instalação mal realizada. 🔧', 203.48, 115.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-820la-moean312iih167', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1386895250%2F58205525173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898767441', 'Lampadas Led Toyota Corolla 2015 A 2017 H11 Hb3 20000lm', 'Lâmpada Led FORCE ONE *IMPORTANTE: Compatível com os modelos XEI e GLI. O kit não é compatível com os modelos topo de linha SE-G e ALTIS. Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - 2 Super Led H11 - Alto - 2 Super Led HB3 - Baixo - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Aplicação: Toyota Corolla 2015 Aplicação: Toyota Corolla 2016 Aplicação: Toyota Corolla 2017 Lâmpadas Super Led ? 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED V10* Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 99.9, 92.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mdnlgwruduc14e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F22898767441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293831717', 'Kit Arame Para Solda Mig Uso Sem Gás 0.8mm 3 Rolos De 1 Kg Start', 'Distribuído por Ismafer Ferramentas 3 Arames de Solda 1kg 0.8mm Uso sem Gás Descrição do Produto: O Arame de Solda 0.8mm da Start é ideal para soldagem sem gás, oferecendo praticidade e eficiência em diversos projetos de soldagem. Fabricado com material de alta qualidade, este arame proporciona uma soldagem consistente e durável, sendo adequado para profissionais e amadores que buscam um excelente acabamento em suas soldagens. Ficha Técnica: - Peso: 1kg - Diâmetro: 0.8mm - Marca: Start - Uso: Sem Gás Vantagens: - Praticidade: Dispensa o uso de gás, facilitando o processo de soldagem. - Alta Qualidade: Material resistente, garantindo soldagens duradouras. - Versatilidade: Adequado para diversas aplicações de soldagem. - Consistência: Proporciona soldagens uniformes e de alta qualidade. Usos Recomendados: - Reparos domésticos e industriais. - Projetos de soldagem automotiva. - Manutenção e fabricação de estruturas metálicas. - Soldagem em locais onde o uso de gás não é viável. EAN: 7908822401209 SKU: KIT24033x3 Distribuído por Ismafer Ferramentas', 190.0, 169.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824h9-mpjv227o9lala7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F23293831717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
