INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40473974105', 'Orações dos Pequeninos', 'O livro Orações Dos Pequeninos é uma obra cativante e educativa especialmente desenvolvida para crianças. Com uma coleção de belas orações adaptadas à compreensão infantil, este livro encantador tem como objetivo introduzir os pequenos leitores ao universo da espiritualidade e da fé de uma maneira acessível e cativante. Repleto de ilustrações coloridas e envolventes, cada página deste livro proporciona momentos de reflexão, ensinamentos valiosos e uma abordagem delicada para familiarizar as crianças com a prática da oração. Ideal para pais, educadores e qualquer pessoa que queira compartilhar valores e ensinamentos importantes com os mais jovens. Título: Orações dos Pequeninos Número de páginas: 21 Acabamento: Capa brochura Dimensões: 15 larg. cm x 16 alt. cm Editora: Pé da Letra', 14.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8258w-mfsjf2n0en0u2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F40473974105', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48952483272', 'Kit 2 Livros Infantil | Ela é Ela Nikolas Ferreira + A Turminha do Leo Deive Leonardo', 'Kit 2 Livros Infantil | Ela é Ela Nikolas Ferreira + A Turminha do Leo Deive Leonardo Ela é Ela: Meninos e meninas são diferentes, e isso é maravilhoso! Com linguagem apropriada para crianças e ilustrações encantadoras, este livro celebra a identidade das meninas, mostrando que Deus as criou de forma única para cumprirem o propósito que o Senhor estabeleceu para elas nesta terra. Independentemente da profissão ou dos sonhos que escolherem, as meninas podem crescer confiantes em sua identidade como verdadeiras mulheres de Deus: sábias, bondosas e cheias graça. Autor: Nikolas Ferreira e Ana Campagnolo Editora: Vida Acabamento: Capa dura Dimensões: 23 cm larg. X 23 cm alt. Número de páginas: 48 A Turminha do Leo Infantil: Leo é um menino inteligente e curioso que ama passar tempo com seus amigos: Tony, o mais atrapalhado e brincalhão da turma; Paty, sempre conectada e pronta para ajudar; e Sophie, que cuida de cada um com muito amor. Juntos, eles aprendem a ser como Jesus e a fazer a diferença no mundo através do poder da amizade. Depois de ouvirem sobre a parábola do Bom Samaritano, embarcam na missão de desvendar uma importante questão: “Como podemos ajudar o próximo?”. Mesmo sendo crianças, sabem que, unindo suas forças, poderão encontrar uma maneira criativa e divertida de cuidar das pessoas. Deus quer usar a todos nós como instrumentos para espalhar o seu amor pela Terra, então venha participar desta aventura e aprender sobre Jesus ao lado de Leo e sua turminha! Autor: Deive Leonardo Editora: Vida Acabamento: Capa dura Dimensões: 20 cm larg. x 20 cm alt. Número de páginas: 60', 69.9, 59.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82262-mhrwn8i4f18lae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F48952483272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15281471137', 'O Pastor Aprovado Livro Richard Baxter', 'O Pastor AprovadoO pastor Aprovado é um dos mais extraordinários já publicados na língua inglesa. Sobre ele Spurgeon se expressou desta forma: Se você quiser conhecer a arte de argumentar, leia O Pastor Aprovado. Richard Baxter é o escritor mais poderoso', 47.9, 47.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mks6xj2x7ridae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F15281471137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
