INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46605237446', 'NAC 4well 600mg - 60 cápsulas - Combo 2 Potes', 'NAC 4well 600mg – 60 cápsulas O NAC (N-Acetilcisteína) 4well é um derivado do aminoácido cisteína, amplamente reconhecido por seu papel como precursor da glutationa, um dos mais importantes antioxidantes produzidos pelo organismo. Ele auxilia na proteção celular contra os radicais livres. Cada cápsula fornece 600mg de NAC puro, em uma dosagem prática e eficaz. Informações do produto: Marca: 4well Conteúdo: 60 cápsulas Porção/dose: 1 cápsula', 120.0, 120.0, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-8261s-mjtzgctp8ef71e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346351615%2F46605237446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
