INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16658577443', 'Pelúcia Squishmallows 12cm - Flip Série 6 - Danny/Damien', 'Descrição: Squishmallows são macios, fofinhos e estão prontos para se juntar ao seu esquadrão. Feitos com material super macio, parecido com marshmallow, os Squishmallows oferecem conforto, apoio, são ótimos companheiros de sofá, amigos de travesseiro, companheiros de dormir e companheiros de viagem. Com mais de 475 personagens Squishmallows para colecionar, há um Squishmallow para todos. Cada Squishmallow tem seu próprio nome e enredo únicos para aumentar a diversão. Quem vai se juntar ao seu esquadrão em seguida? Características: Marca: Sunny Brinquedos Referência: 3200B Série: - Idade recomendada: A partir de 2 meses Usa Pilhas/Baterias ?: Não Possui Luzes: Não Possui Sons: Não Dimensões aproximadas do produto: 12 x 13 x 13cm (A x L x C) Dimensões aproximadas da embalagem: 12 x 13 x 13cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Pelúcia Squishmallows de 12cm Certificado Inmetro: REGISTRO 000628/2021 BRI-1 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 99.99, 93.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/83ef72bc98107e3a4c38820bc3138cf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F16658577443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
