INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9969578949', 'Kit 2 Driver + 2 Cornetas Bocal Cone + 2 Super Tweeter Tuiter Champion 400w', 'Este kit contém 2 drivers, 2 tweeters e 2 cornetas no total de 400W de potência, ideal para reproduzir frequencias médias e agudas, com total definição sonora para o seu projeto de som. Carcaça super resistente e durável, qualidade e desempenho reunidos em um só kit. Especificações técnicas do Driver: Potência: 100W RMS (cada) Impedância Nominal: 8 ohms Sensibilidade driver: 109 Db Resposta de freqüência driver: 800 a 20000Hz Carcaça em Polipropileno Diagrama Fenólico Imã Ferrite de Bário Especificações técnicas do Tweeter: Potência: 100W RMS (cada) Impedância Nominal: 8 ohms Sensibilidade tweeter: 111 Db Resposta de freqüência tweeter: 4000 a 20000Hz Bobina Simples Carcaça em Polipropileno Imã Ferrite de Bário', 214.13, 190.41, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/be3b782b0dc22c81c53731fc6551c3a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F9969578949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
